window.__D("text/pelach-harimon/c000",{"p":[[4801940076,"<b>אדם</b> כי<sup data-n=\"1\">1</sup> יקריב<sup data-n=\"2\">2</sup> כו'. להבין ענין משארז\"ל ברכות חתנים<sup data-n=\"3\">3</sup> בעשרה<sup data-n=\"4\">4</sup> הלא עיקר הברכה לכלה כמאמר כלה בלא ברכה<sup data-n=\"5\">5</sup>. וי\"ל ענין הקרבן ותפלה במקום קרבן<sup data-n=\"6\">6</sup> ולכן ארז\"ל תיכף לסמיכה שחיטה וכן תיכף לגאולה תפילה<sup data-n=\"7\">7</sup> כו'. כי הנה הקרבן הוא יחוד חו\"כ כי ענין חתן וכלה יובן בהקדים ענין רוח האדם העולה למעלה<sup data-n=\"8\">8</sup> ורוח הבהמה היורדת למטה, כי הנה המלאכים נק' חיות ובהמות<sup data-n=\"9\">9</sup> הגם שהם בעלי השגה והתפעלות מ\"מ יש מי שאוהב כו' ולכן נק' בהמה שהוא בחי' יש, אך גם אור האלקי המחי' אותם הוא בחי' מל' שבה שם ב\"ן<sup data-n=\"10\">10</sup> בגימט' בהמה<sup data-n=\"11\">11</sup> אך נק' רוח הבהמה כו' חיות המחי' את המלאכים הנק' בהמה, והנה טבע הבהמה רוצה להיות יורד להשפיע<sup data-n=\"12\">12</sup> למטה דוקא ולכן אמרו יותר משהעגל רוצה לינק<sup data-n=\"13\">13</sup> פרה רוצה להניק, פרה דווקא כו' ואפי' בהמה רבה<sup data-n=\"14\">14</sup> שלפני האצי' (מל' דא\"ס<sup data-n=\"15\">15</sup>. ..) רוצה בהשפעה בעולמות כו', משא\"כ רוח האדם עולה למעלה כו', להיות בבחי' ביטול ואינו רוצה בהשפעה כלל כי איידי דטריד למיבלע<sup data-n=\"16\">16</sup> כו', כי אדם הוא בחי' מ\"ה<sup data-n=\"17\">17</sup> וביטול, ולכן משרע\"ה בחינתו ונחנו מ\"ה<sup data-n=\"18\">18</sup> לא רצה בהשפעת התורה לישראל ואמר",[["1","1","<b>אדם כי יקריב</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ (מליל ד' פ' ויקרא תרי\"ט).\nמאמר הצ\"צ נדפס במאמרי אדה\"ז תקס\"ג ח\"א בהוספה ע' שצה־ אוה\"ת סידור ע' ער [ושם הפתיחה: להבין ענין ברכת חתנים. והוא הגהות וכו' על מאמר ד\"ה זה מכ\"ק אדמו\"ר הזקן שנדפס במאמרי אדה\"ז שם ע' רמד. ובארוכה במאמרי אדה\"א דרושי חתונה ח\"א ע' קמו].\nראה מאמר זה בארוכה לקמן בהמאמר שנדפס לאח\"ז [וראה גם הנרשם בריש המאמר שם].\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["2","2","<b>אדם כי יקריב</b>: ויקרא א, ב."],["3","3","<b>ברכות חתנים</b>: כתובות ז, א. ב."],["4","4","<b>בעשרה</b>: תיבה זו ניתוספה בכת\"י מאוחר. ב: ליתא."],["5","5","<b>כלה בלא ברכה</b>: ריש מס' כלה. וראה זהר תרומה קסט, סע\"א."],["6","6","<b>ותפלה במקום קרבן</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["7","7","<b>תיכף לסמיכה. . לגאולה תפילה</b>: ברכות מב, א. ראה לקמן בפנים. אוה\"ת ויקרא כרך א ע' רכב."],["8","8","<b>רוח האדם העולה למעלה</b>: ראה קהלת ג, כא."],["9","9","<b>המלאכים נק' חיות ובהמות</b>: ראה תניא רפל\"ט. מאמרי אדה\"א ויקרא ח\"א ע' ט. וש\"נ."],["10","10","<b>מל'. . שם ב\"ן</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ג. שעה\"י קמה, א הערה 14. לקמן ע' ה."],["11","11","<b>ב\"ן בגימט' בהמה</b>: ראה תניא ספמ\"ו. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ."],["12","12","<b>להשפיע</b>: ניתוסף ע\"פ ב."],["13","13","<b>יותר משהעגל רוצה לינק</b>: ראה פסחים קיב, א. מאמרי אדה\"א דברים ח\"א ע' רפז. וש\"נ. תו\"ח ויצא קסט, ג ובהערה 35. לקמן מאמר ד\"ה רפאיני הא' על יד הערה 110."],["14","14","<b>בהמה רבה</b>: ראה תניא ספמ\"ו. לקו\"ת אמור לו, א. תו\"ח בראשית טז, ג ובהערה 26."],["15","15","<b>מל' דא\"ס</b>: ראה בהמאמר שלאח\"ז."],["16","16","<b>איידי דטריד למיבלע</b>: ראה חולין קח, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצה. תו\"ח נח סג, ג הערה 44."],["17","17","<b>אדם הוא בחי' מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. תו\"ח בראשית ט, א הערה 14."],["18","18","<b>משרע\"ה בחינתו ונחנו מ\"ה</b>: בשלח טז, ז-ח. ראה גם לקמן מאמר ד\"ה ואכלתם אכול תקצ\"ט ובהערה 54."]]],[4801940142,"כי כבד פה<sup data-n=\"19\">19</sup> כו' תושב\"כ ותשבע\"פ הנק' פה ולשון כו'. והנה כשהיו מקריבין הקרבן הי' עולה רוחני' הבהמה ונכללת בתחלה בפני שור כו', ואפי'<sup data-n=\"20\">20</sup> בפני נשר כו' ופועל שגם המה יעלו ויכללו ברוח הבהמה שהוא בחי' המל' שם ב\"ן כו' וממילא הי' עולה רוח הבהמה ונכללת בפני אדם בחי' מ\"ה כו', ועי\"ז נעשה טבע חדש בבחי' רוח הבהמה ג\"כ לעלות למעלה בבחי' ביטול והתכללות בעצמות אוא\"ס, ועלי' זאת גורם בחי' המשכה מלמעלה למטה להיות נגלה גילוי אוא\"ס למטה כמו למעלה (... ונעשה בבחי' רוח האדם טבע חדש לירד למטה בבחי' השפעה כו'. ..) ונמצא שנעשה יחוד מ\"ה וב\"ן עד שנכללים כא' ממש כו'. והנה עלי' רוחני' הבהמה בפני שור ועלי' פני שור בבחי' המל' הוא ע\"י אש של הדיוט כי הדיוט הוא בחי' ההשתל' (מט\"ט<sup data-n=\"21\">21</sup> שרו ש\"ע<sup data-n=\"22\">22</sup> נק' הדיוט לגבי מארי'<sup data-n=\"23\">23</sup> כו' ), אך עלי' רוח הבהמה ברוח האדם בחי' ב\"ן שעולה ומתייחד בבחי' שם מ\"ה הוא ע\"י אש שלמעלה כו'.\n<b>והנה</b> הקרבן הי' טעון מתחלה סמיכה<sup data-n=\"24\">24</sup> כי הסמיכה הוא בשתי ידים<sup data-n=\"25\">25</sup> ובכל כחו<sup data-n=\"26\">26</sup> כח וי\"ו<sup data-n=\"27\">27</sup> המייחד שתי ידים כו', ב\"פ י\"ד גימט' כח<sup data-n=\"28\">28</sup> וכן העונה איש\"ר בכל כחו<sup data-n=\"29\">29</sup> (ואפשר שכח וי\"ו הוא יד הרמה כו' עי' בסידור במאמר חייב אדם לבסומי<sup data-n=\"30\">31</sup> כו'<sup data-n=\"31\">30</sup>, ובמה שהוא סומך הוא ממשיך כח ועוז ברוחני' החיות שבבהמה שתוכל לעלות ע\"י שתי אשות הנ\"ל ולהתייחד בבחי' שם מ\"ה, ולכן צ\"ל תיכף לסמיכה שחיטה שבזה מייחדים המשכת האור העליון ברוחני' החיות שבבהמה שתוכל לעלות עי\"ז כנ\"ל, וכן הוא בתפילה במקום קרבן ע\"י ההתבוננות בפסוד\"ז ובברכות יוצר אור בא אח\"כ לבחי' מס\"נ באחד וזהו שמעלי'<sup data-n=\"32\">32</sup> הנה\"א הנק' ישראל<sup data-n=\"33\">33</sup> כי שרית עם אלקים<sup data-n=\"34\">34</sup> כו', אך זהו עליות הנשמה שהוא ג\"כ בחי' בהמה (כמבואר בכמה מקומות שיש נשמות שהם בבחי' בהמה בלבד והיינו נשמות דבי\"ע<sup data-n=\"35\">35</sup> כו'. ..) אך העלאת נה\"ב הוא בתפילה ולכן הוא סומך גאולה לתפילה שהוא המשכה מלמעלה ליתן כח ועי\"ז<sup data-n=\"36\">36</sup>",[["19","19","<b>כי כבד פה</b>: שמות ד, י. ראה זהר רע\"מ צו כח, א. מאמרי אדה\"א דברים ח\"ג ע' תתצו. וש\"נ. תו\"ח שמות ח\"א מז. ד. וש\"נ. קונט' בר מצוה תרנ\"ג ע' נב."],["20","20","<b>ואפי'</b>: כנצ\"ל: ועוף."],["21","21","<b>מט\"ט. . כו'</b>: כנצ\"ל: (... מט\"ט. . כו'. ..). ראה במאמר הבא ע' יא."],["22","22","<b>מט\"ט שרו ש\"ע</b>: ראה יבמות טז, ב ובתוס' שם."],["23","23","<b>מט\"ט. . הדיוט לגבי מארי'</b>: ראה זהר רע\"מ תצא רעו, א."],["24","24","<b>הקרבן. . סמיכה</b>: ויקרא א, ד. מנחות צב, א (במשנה)."],["25","25","<b>הסמיכה הוא בשתי ידים</b>: מנחות צג, א (במשנה)."],["26","26","<b>הסמיכה. . ובכל כחו</b>: חגיגה טז, ב."],["27","27","<b>ובכל כחו כח וי\"ו</b>: ראה סדר היום כונת הקדיש (ע' 12). אוה\"ת ויקרא כרך א ע' רכב."],["28","28","<b>ב\"פ י\"ד גימט' כח</b>: ראה ת\"ז תנ\"ה פט, א. שער הפסוקים שלח סי\"ד ד\"ה עוד ירצה [מזולתו]. סדה\"י שם."],["29","29","<b>העונה איש\"ר בכל כחו</b>: ראה שבת קיט, ב."],["30","31","<b>יד הרמה. . בסידור. . לבסומי</b>: שער הפורים רפג, א ואילך. וראה גם תו\"א מג\"א צה, ד."],["31","30","<b>(ואפשר.. כו'</b>: כנצ\"ל: (... ואפשר. . כו'. ..)."],["32","32","<b>שמעלי'</b>: ב: שמע\"י שמע ישראל."],["33","33","<b>הנה\"א הנק' ישראל</b>: ראה לקו\"ת תצא לח, א. תו\"ח תצוה ח\"ב שמו, ג. וש\"נ."],["34","34","<b>כי שרית עם אלקים</b>: וישלח לב, כט."],["35","35","<b>נשמות. . בהמה. . נשמות דבי\"ע</b>: ראה תו\"א ר\"פ משפטים."],["36","36","<b>ועי\"ז</b>: ב: ועוז."]]],[4801940206,"בנה\"ב שתוכל לעלות בתפילה כו', וזהו תיכף לגאולה תפילה כו'. והנה כן הוא בקבלת שבת שאנו אומרים לכה דודי לקראת כלה, היינו ג\"כ המשכה מלמעלה מבחי' דודי ליתן כח ועוז בבחי' כלה שתוכל לעלות בעליות העולמות דשבת כו'.\n<b>ומעתה</b> יובן ענין ברכת חתנים כי הנה חתן וכלה הוא ג\"כ בחי' אדם ובהמה בחי' מ\"ה וב\"ן, ועלי' רוח הבהמה בחי' ב\"ן להתכלל ולהתייחד בבחי' רוח האדם בחי' מ\"ה נק' בחי' כלה מלשון כלתה נפשי<sup data-n=\"37\">37</sup> כו' והיינו עלי' עולם ושנה בבחי' נפש ואח\"כ עלי' בחי' נפש שהוא נפש הבהמה להתכלל באדם נק' כלה, אך אינה ראוי' ליחוד זה רק כשיומשך בה כח ועוז מתחלה שתוכל לעלות כו', וזהו ברכת חתנים שהחתן מברך וממשיך בה כח ועוז בכל ז\"ס<sup data-n=\"38\">38</sup> שתוכל לעלות ואז נק' אלישבע משא\"כ מתחלה נק' בת שבע<sup data-n=\"39\">39</sup> כו' וד\"ל. והנה כן הוא עד\"ז בתפילה מברכין שבע ברכות כו' ג' בשחר וד' בערב<sup data-n=\"40\">40</sup> להמשיך בבחי' המל' שתוכל להתייחד ועיקר היחוד הוא בערבית ולכן ברכה שביעי' השכי' אבינו לשלום, וישכב במקום ההוא<sup data-n=\"41\">41</sup> יש כ\"ב<sup data-n=\"42\">42</sup> דמעייל בה כ\"ב אתוון כו'. אך באמת ברכות הנמשכי' לכלה הוא ממקום יותר גבוה מן החתן והחתן אינו אלא מעבר לזה, ומקור הברכות הוא פנים חדשות שהוא בחי' פנימי' המוחין למעלה מהתחלקות חסד וגבורה שמשם הי' שורש נשמת ר\"מ לכן הי' אומר על טמא טהור ומראה לו פנים<sup data-n=\"43\">43</sup> כו' וכאשר מתלבשים המוחין בבחי' חתן דכר נק' פנים וכשמתלבשים בבחי' המל' הוא בחי' נוק' נק' חדשים<sup data-n=\"44\">44</sup> לשון נוק', ונמצא שדכר ונוק' כלולים כחדא כענין נפתלי אילה כו' הנותן<sup data-n=\"45\">45</sup> כו'. והנה עד\"ז הוא ברכת כהנים כו' שיש להם כח לברך בחי' המל' ליתן בה כח ועוז כו' והוא ע\"ד ברכת חתנים והוא כמבואר בזוהר ע\"פ נשמת כל חי תברך את שמך דפרחא מחי העולמים<sup data-n=\"46\">46</sup> לכן אית לה רשות לברכא להאי אתר כו', וכל הברכות האלו הם מלמעלה למטה אך ברכת הדיוט הוא מלמטה למעלה כו'. והנה זהו ברכת חתנים בעשרה כי עיקר החתן הוא הת\"ת<sup data-n=\"47\">47</sup> אך באמת כל הע\"ס נק' חתנים ונכללים בת\"ת בעת הברכה ואז הוא ממשיך כח ועוז בבחי' כלה ולכן בעשרה דווקא שאז נכללים מכל הי\"ס אז יש לו כח לברך את המל' כענין נשמת כל חי הנ\"ל כו' וד\"ל.",[["37","37","<b>כלה מלשון כלתה נפשי</b>: תהלים פד, ג. ראה גם תו\"ח בשלח ח\"א רח, א ובהערה 19."],["38","38","<b>ז\"ס</b>: ז' ספירות."],["39","39","<b>אלישבע. . בת שבע</b>: ראה בהמאמר שלאח\"ז ובהערות 135-136."],["40","40","<b>ג' בשחר וד' בערב</b>: קודם ולאחר ק\"ש. ראה סה\"מ תרל\"ג ח\"א ע' רעו ואילך. ע' רצט ואילך. ע' שז ואילך."],["41","41","<b>וישכב במקום ההוא</b>: ויצא כח, יא."],["42","42","<b>וישכב. . יש כ\"ב</b>: ראה זהר רע\"מ פינחס רלט, א."],["43","43","<b>ר\"מ. . ומראה לו פנים</b>: ראה ערובין יג, ב. מאמרי אדה\"א נ\"ך ע' שמא. תו\"ח שמות ח\"א טז, ב ובהנסמן בהנ\"ל. המאמר שלאח\"ז."],["44","44","<b>חדשים</b>: כנצ\"ל: חדשות."],["45","45","<b>נפתלי אילה כו' הנותן</b>: ויחי מט, כא. ראה המאמר שלאח\"ז. פלח הרמון ויחי קלה, רעא."],["46","46","<b>נשמת כל חי. . דפרחא מחי העולמים</b>: פיוט נשמת. ראה זהר תרומה קלח, א."],["47","47","<b>החתן הוא הת\"ת</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ח מערכת חתן."]]],[4801940077,"<b>ב\"ה ליל ד' פ' ויקרא דשנת תרי\"ט בסעודת חתונה</b>\n<b>אדם</b> כי יקריב<sup data-n=\"48\">1</sup> מכם<sup data-n=\"49\">2</sup> כו'. להבין מה שארז\"ל ברכת חתנים בעשרה<sup data-n=\"50\">3</sup> וחתנים מן המנין כו' למה צריך לברכות אלו עשרה יותר מכל הברכות דברכות המצות וברכות ההודאה כו'. הנה מתחלה י\"ל<sup data-n=\"51\">4</sup> למה קראו לברכות אלו בשם ברכת חתנים כי לכאורה עיקר הברכה הוא בשביל הכלה כו' כמארז\"ל כלה בלא ברכה<sup data-n=\"52\">5</sup> אסורה לבעלה כנדה כו'. ויש להקדים ענין הקרבן מהו וענין התפלה שהוא במקום קרבן<sup data-n=\"53\">6</sup> מה היא, כי הנה בקרבן ארז\"ל תיכף לסמיכה שחיטה ובתפלה אמרו תיכף לגאולה תפילה כו' וכמאמרם ז\"ל שלש תכיפות הן כו' (ברכות מ\"ב ע\"א). כי הנה ענין הקרבן גורם למעלה יחוד חו\"כ העליונים.\n<b>ולהבין</b> ביאור ענין חו\"כ העליונים מה הם יש להקדים מאמר הכתוב (קהלת ג', כא) מי יודע רוח בני האדם העולה היא למעלה ורוח הבהמה היורדת היא למטה כו'. כי הנה ענין רוח הבהמה יובן בהקדם ענין המלאכים שנקראי' בשם חיות ובהמות<sup data-n=\"54\">7</sup> פני ארי' פני שור כו' בחי' חי ואינם נקראים בחי' אדם, ולכאורה אינו מובן כי בודאי ההשגה דפני ארי' שהוא בחי' מלאך מיכאל<sup data-n=\"55\">8</sup> כו' גדולה מאד ולמה נק' בחי' חי כו'. אך באמת כל השגתם אינו רק מאין ליש איך שאור האלקי מחי' ומהווה אותם בכל עת ורגע ומחמת זה הם במציאות יש ואם הי' מסתלק אפי' רגע א' היו חוזרי' לאין ואפס כמו קודם הבריאה אך כ\"ז שהוא שופע בהם הם במציאות יש<sup data-n=\"56\">9</sup> ונמצא שאינם מרגישים אמיתית האין כמו שהוא רק הארה בעלמא ממנו המתלבש בהם והיינו מציאותו ולא מהותו כו' אבל אם היו רואים אמיתית האין השופע בהם<sup data-n=\"57\">10</sup> היו מרגישים שהאין הוא אמיתית היש והמה בחי' אין ואפס המוחלט כו' (... וזהו בחי' איזו מתקרי חכים הרואה את הנולד<sup data-n=\"58\">11</sup> כו'. ..) ולכן התפעלותם מן ההשגה שמשיגים אינה בחי' ביטול המהות מכל וכל רק בחי' אהבה ויראה יש מי שאוהב ויש מי שירא",[["48","1","<b>אדם כי יקריב</b>: הנחת ר' הלל מדרוש של כ\"ק אדמו\"ר הצ\"צ.\nמאמר הצ\"צ נדפס במאמרי אדה\"ז תקס\"ג ח\"א בהוספה ע' שצה־ אוה\"ת סידור ע' ער [ושם הפתיחה: להבין ענין ברכת חתנים. והוא הגהות וכו' על מאמר ד\"ה זה מכ\"ק אדמו\"ר הזקן שנדפס במאמרי אדה\"ז שם ע' רמד. ובארוכה במאמרי אדה\"א דרושי חתונה ח\"א ע' קמו].\nממאמר זה כנראה יש ב' מהדורות א) הנדפס לפנ\"ז ושם נרשם בקיצור. ב) כפי שנרשם כאן בארוכה.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["49","2","<b>אדם כי יקריב מכם</b>: ויקרא א, ב."],["50","3","<b>ברכת חתנים בעשרה</b>: כתובות ז, א-ב."],["51","4","<b>למה צריך. . י\"ל</b>: ג: ליתא. וכנראה נשמט מפני תיבות הדומות: למה. . למה."],["52","5","<b>כלה בלא ברכה</b>: ריש מס' כלה. (וראה זהר תרומה קסט, סע\"א)."],["53","6","<b>התפלה שהוא במקום קרבן</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["54","7","<b>המלאכים. . חיות ובהמות</b>: יחזקאל א, י. ראה גם תניא רפל\"ט. מאמרי אדה\"א ויקרא ח\"א ע' ט. וש\"נ. לקמן מאמר ד\"ה וספרתם הד' ע' רפז. פלח הרמון שמות ע' כב."],["55","8","<b>ארי'. . מיכאל</b>: ראה זהר בהעלותך קנד, א."],["56","9","<b>ואם הי'. . יש</b>: ניתוסף ע\"פ ג."],["57","10","<b>בהם</b>: ניתוסף ע\"פ ג."],["58","11","<b>איזו </b>[ב: אידין]<b>. . הרואה את הנולד</b>: ראה תמיד לב, א."]]],[4801940143,"כו' ולכן נק' בהמה שהוא בחי' יש כו'. אך גם בחי' אור האלקי השופע בהם שהוא בחי' מל' דאצי' המחי' ומהווה כל המלאכים דבי\"ע כו' (... וזה\"ע המבואר למעלה שרק בחי' הארה מאין האלקי המה משיגים כו' כי עצם האין הוא בחי' י\"ס דאצי' ובחי' מל' הוא בחי' זיו בלבד מבחי' הי\"ס ונק' שם כו', אך גם בחי' שם הנ\"ל<sup data-n=\"59\">12</sup> נשגב שמו לבדו<sup data-n=\"60\">13</sup> מהשגת הנבראים כמאמר כי נשגב שמו לבדו<sup data-n=\"61\">14</sup> כו' רק הודו הארה מבחי' הזיו הוא המתפשט על ארץ ושמים הנבראים מאין ליש להחיותם, ובחי' זאת הוא בחי' מל' דמל' המתלבש בבחי' ג' עולמות דבי\"ע ובחי' זאת נק' בהמה כמשי\"ת. משא\"כ עצם המל' כמ\"ש בבחי' האצי' היא מכלל אדם כו' וד\"ל. ..) נק' ג\"כ בחי' בהמה כידוע דשם ב\"ן הוי' במילוי ההי\"ן הוא בבחי' המל'<sup data-n=\"62\">15</sup> דאצי' ובהמה בגימ' ב\"ן<sup data-n=\"63\">16</sup> כו'. אך להיות בחי' המל' דאצי' הנ\"ל הוא בחי' חיות האלקי המהווה ומחי' את כל הנבראים לכן נק' בשם רוח הבהמה כי הוא חיות האלקות המחי' את המלאכים הנק' בשם בהמה כו'.\n<b>והנה</b> זהו<sup data-n=\"64\">17</sup> מש\"א ורוח הבהמה היורדת היא למטה כי טבע הבהמה להיות רוצה בהשפעה כו', וכ\"ה למעלה בבחי' הרוחני' דמל' דאצי' חפצה ותשוקתה להשפיע חיות בנבראים מאין ליש כו'. ולכן ארז\"ל יותר משהעגל רוצה לינק<sup data-n=\"65\">18</sup> הפרה רוצה להניק כו', פרה דוקא שהוא בחי' בהמה שם ב\"ן שהוא בחי' המל' דאצי' רצונה להשפיע ולהחיות כל הנבראים מאין ליש כנ\"ל ואפי' בחי' בהמה רבה<sup data-n=\"66\">19</sup> שלפני האצי' (... נלע\"ד שהוא בחי' מל' דא\"ק או אפי' בחי' מל' דא\"ס כו' וד\"ל<sup data-n=\"67\">20</sup>. ..) רצון הבחי' זאת להשפיע בעולמות כו' משא\"כ רוח האדם אדם בגימ' מ\"ה<sup data-n=\"68\">21</sup> שהוא בחי' המדות דאצי' (... הנק' ז\"א<sup data-n=\"69\">22</sup> בלשון הקבלה שהוא ג\"כ פרצוף שלם מי\"ס מצד המוחין הנמשכים בו<sup data-n=\"70\">23</sup> כו' אע\"פ שבסוד שרש<sup data-n=\"71\">24</sup> לא נאצל רק בבחי' ששה מדות<sup data-n=\"72\">25</sup> כידוע בכהאריז\"ל. ..) עולה למעלה בבחי' ביטול האמיתי מצד הראי' שהוא<sup data-n=\"73\">26</sup> האמת איך שלמעלה הוא בחי' יש האמיתי ולמטה העולמות הם בחי' אין ואפס המוחלט לזאת הוא בבחי' ביטול האמיתי במקורו לכן הוא עולה למעלה ואינו רוצה בהשפעה כלל כי איידי דטריד",[["59","12","<b>הנ\"ל</b>: בג: הוי'."],["60","13","<b>שמו לבדו</b>: ניתוסף ע\"פ ג."],["61","14","<b>כי נשגב שמו לבדו</b>: תהלים קמח, יג."],["62","15","<b>דשם ב\"ן. . המל'</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ג. שעה\"י קמה, א הערה 14."],["63","16","<b>ובהמה בגימ' ב\"ן</b>: ראה תניא ספמ\"ו. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ."],["64","17","<b>זהו</b>: ניתוסף ע\"פ גד."],["65","18","<b>יותר משהעגל רוצה לינק</b>: ראה פסחים קיב, א. מאמרי אדה\"א דברים ח\"א ע' רפז. וש\"נ. תו\"ח ויצא קסט, ג ובהערה 35. לקמן מאמר ד\"ה רפאיני הא' על יד הערה 110."],["66","19","<b>בהמה רבה</b>: ראה תניא ספמ\"ו. לקו\"ת אמור לו, א. תו\"ח בראשית טז, ג ובהערה 26."],["67","20","<b>כו' וד\"ל</b>: ג: ליתא."],["68","21","<b>אדם בגימ' מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. תו\"ח בראשית ט, א הערה 14."],["69","22","<b>אדם. . ז\"א</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ה."],["70","23","<b>בו</b>: ניתוסף ע\"פ גד."],["71","24","<b>שבסוד שרש</b>: גד: שבעצם בסוד שרשו."],["72","25","<b>ז\"א. . ששה מדות</b>: ראה ע\"ח שער המוחין ש\"כ, פ\"א. שער רפ\"ח ניצוצין שי\"ח, פ\"ה מ\"ק."],["73","26","<b>שהוא</b>: ג: שרואה."]]],[4801940207,"למיבלע<sup data-n=\"74\">27</sup> כו' להיותו בבחי' מ\"ה וביטול לא פליט להשפיע למטה כו' ולכן גם בנשמת משרע\"ה שבחינתו הי' בחי' מ\"ה כמש\"א ונחנו מ\"ה<sup data-n=\"75\">28</sup> לכן לא רצה להיות שליח בהשפעת התורה לישראל וא' שלח נא<sup data-n=\"76\">29</sup> כו'. וזהו שא' על עצמו כי כבד פה וכבד לשון שכבד עליו להלביש א\"ע בהשפעת התושבע\"פ ותושב\"כ<sup data-n=\"77\">30</sup> הנק' פה ולשון כו'.\n<b>(הג\"ה</b><sup data-n=\"78\">31</sup>. לכאורה יש סתירה גדולה לזה כי לפי הנ\"ל הזכר שהוא בחי' מ\"ה הוא בחי' גבו' לעלות למעלה בבחי' ביטול ואינו רוצה בהשפעה כלל והנקבה שהוא בחי' ב\"ן רצונה בהשפעה כנ\"ל והוא בחי' חסד כו', ובלק\"ת פ' תזריע<sup data-n=\"79\">32</sup> בענין איש מזריע תחלה ואשה מזרעת תחלה כו' א' שם וז\"ל והענין הוא<sup data-n=\"80\">33</sup> כי הזכר הוא חסד<sup data-n=\"81\">34</sup> כו' ונקבה היא בחי' גבורה כו' ובסוף המאמר<sup data-n=\"82\">35</sup> א' וז\"ל וע\"פ הקבלה<sup data-n=\"83\">36</sup> הזכר נמשך<sup data-n=\"84\">37</sup> משם מ\"ה והנקבה משם ב\"ן כו' א\"כ לפי הנ\"ל הזכר שהוא בחי' מ\"ה הוא בחי' חסד וטבע החסד להיות רוצה בהשפעה והנקבה הוא בחי' גבורה וטבע הגבורה הוא כמו האש שעולה למעלה ואינו רוצה בהשפעה והוא היפוך מכל הנ\"ל. והנלע\"ד בדא\"פ שמה שאמר כאן שאדם אינו רוצה בהשפעה היינו בחי' אדם קדמאה בחי' חכ\"ע שמאין תמצא ומצד קירובו לבחי' האין הוא בבחי' מ\"ה כנ\"ל וכן אנו רואים מבשרי אחזה<sup data-n=\"85\">38</sup> כו' שטבע החכם להיות טרוד תמיד<sup data-n=\"86\">39</sup> בעמקות החכ' ואינו רוצה בהשפעה כלל ונמצא שטבע החכ' הוא בחי' גבו' (אפשר מצד המשכתה מבחי' חכ\"ס שמלובש בה גבו' דע\"י כו') אך בחי' אימא עילאה הנק' בינה הוא מל' יבנה<sup data-n=\"87\">40</sup> מקור ז' ימי הבנין<sup data-n=\"88\">41</sup> מקורה הוא להשפיע למטה בחי' מדות ומל' (ואפ\"ל דמקור הבינה הוא למעלה מחכ\"ע ושרשה בחסד דע\"י המלובש בגולגלתא. ועיין כעין זה בסידור בדרוש וביאור דיוצר הרים שהחכמה הוא מבחי' מל' דא\"ק והבינה מבחי' יסוד דא\"ק<sup data-n=\"89\">42</sup> כו'). וזהו רוח האדם ורוח הבהמה כו' חו\"ב עילאין הנק' אין ויש<sup data-n=\"90\">43</sup>",[["74","27","<b>איידי דטריד למיבלע</b>: ראה חולין קח, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצה. תו\"ח נח סג, ג הערה 44."],["75","28","<b>משרע\"ה. . ונחנו מ\"ה</b>: בשלח טז, ז-ח. ראה גם לקמן מאמר ד\"ה ואכלתם אכול תקצ\"ט ובהערה 54."],["76","29","<b>שלח נא</b>: שמות ד, יג."],["77","30","<b>כי כבד פה וכבד לשון. . התושבע\"פ ותושב\"כ</b>: שמות ד, י. ראה זהר רע\"מ צו כח, א. מאמרי אדה\"א דברים ח\"ג ע' תתצו. וש\"נ. תו\"ח שמות ח\"א מז. ד. וש\"נ. קונט' בר מצוה תרנ\"ג ע' נב."],["78","31","<b>הג\"ה</b>: סיום ההגה הוא לקמן על יד הערה 91."],["79","32","<b>ובלק\"ת פ' תזריע</b>: יט, ג."],["80","33","<b>הוא</b>: ג ובלקו\"ת: ליתא."],["81","34","<b>חסד</b>: בלקו\"ת: בחי' חסד."],["82","35","<b>ובסוף המאמר</b>: שם יט, ד."],["83","36","<b>הקבלה</b>: ג ובלקו\"ת: קבלה."],["84","37","<b>נמשך</b>: שם: הוא נמשך."],["85","38","<b>מבשרי אחזה</b>: ע\"פ איוב יט, כו."],["86","39","<b>תמיד</b>: ניתוסף ע\"פ גד."],["87","40","<b>הוא מל' יבנה</b>: ג: ליתא."],["88","41","<b>ז' ימי הבנין</b>: ראה תניא פ\"ג. לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב הערה 35."],["89","42","<b>בסידור. . שהחכמה. . מל' דא\"ק והבינה מבחי' יסוד דא\"ק</b>: דרושים לחתונה קלו, א. מאמרי אדה\"א דרושי חתונה ח\"א ע' רכט."],["90","43","<b>חו\"ב. . אין ויש</b>: ראה הנסמן בביאוה\"ז להצ\"צ כרך ב ע' תתרא. מאמרי אדה\"א בראשית ע' ב. דרושי חתונה ח\"ב ע' תעג. סה\"מ תרכ\"ט ע' רעח."]]],[4801940263,"כידוע כו'. ונמצא שעצמות החכ' הוא בחי' גבורה ועצמות הבינה הוא בחי' חסד מצד שרשם הראשון (בע\"י או בא\"ק כנ\"ל).\n<b>אך</b> מה שמצינו שחכמה הוא מקור החסדים<sup data-n=\"91\">44</sup> ולכן קו הימין הוא חח\"ן<sup data-n=\"92\">45</sup> ובינה מינה דינין מתערין<sup data-n=\"93\">46</sup> ולכן קו השמאל הוא בג\"ה<sup data-n=\"94\">47</sup> היינו מצד גילויים שבחי' החכמה מאין תמצא ע\"י מזל השמיני שהוא בחי' ונוצר חסד ומזל זה הוא מקור החכמה<sup data-n=\"95\">49</sup> כידוע בכהאריז\"ל ובחי' הבינה מתגלית ע\"י מזל ונקה<sup data-n=\"96\">48</sup> ששם הוא מקור הגבו'<sup data-n=\"97\">50</sup> כו'. וכן מצד ההלבשה שאבא מלביש לחסד דאריך ובינה מתלבשת לגבו' דאריך<sup data-n=\"98\">51</sup> כו' לכן בחי' החכ' הוא מקור החסדים ובחי' בינה מינה דינין מתערין כו', ולפ\"ז אפ\"ל שבחי' חו\"ב מצד פנימיותם שהוא בחי' ג\"ר שבהם החכ' הוא בחי' גבורה מובדל מהשפעה מצד התכללותה בבחי' האין ומקורה מבחי' גבו' דע\"י או מבחי' מל' דא\"ק כו' והבינה הוא בחי'<sup data-n=\"99\">52</sup> חסד לפעול בבחי' אין דחכ' בחי' התגלות והתפשטות מאין ליש מצד שרשה בבחי' חסד דע\"י או יסוד דא\"ק, אך מצד חיצוניותם שהוא בחי' מדות דחו\"ב הנק' יסו\"ת<sup data-n=\"100\">53</sup> הוא להיפוך שהחכ' מקור החסדים כי המדות מתגלים בחכ' מחמת ה\"ח הנמשכים בו מבחי' ונוצר חסד או מבחי' חסד דאריך המלובש בו ומדות דבינה הם בחי' גבורות להעלים שפע החכמה, כי המה מתגלים בבחי' בינה מצד מזל ונקה או מבחי' גבו' דאריך המלובש בה כו'.\n<b>והטעם</b> לזה למה חיצוניותם הוא היפוך מבחי' פנימיותם הוא ע\"ד המבואר במ\"א בענין מלכי ישראל שאינם רוצים להיות מלך כמו שאול שהי' נחבא אל הכלים<sup data-n=\"101\">54</sup> מפני שבחי' נשמתם הוא מעולם האצילות<sup data-n=\"102\">55</sup> והמה בבחי' ביטול במקורם לכן אינם רוצים להשפיל א\"ע להיות מלך על עם כו' שהוא בחי' יש לגבי הביטול שלהם וכמאמר והוי זנב לאריות<sup data-n=\"103\">56</sup> ואל תהי ראש לשועלים אריות הם נשמות דאצי' שהם",[["91","44","<b>שחכמה הוא מקור החסדים</b>: ראה סידור שער התפילין ט, סע\"ד ואילך. מאמרי אדה\"א בראשית ע' תקי. וש\"נ."],["92","45","<b>קו הימין הוא חח\"ן</b>: נסמן בהערה 47."],["93","46","<b>ובינה מינה דינין מתערין</b>: ראה זהר ויקרא י, סע\"ב. יא, רע\"א. מאמרי אדה\"א דברים ח\"ב ע' שעז. וש\"נ."],["94","47","<b>קו השמאל הוא בג\"ה</b>: ראה זהר רע\"מ בהעלותך קנג, ב. פרדס שער סדר עמידתן ש\"ו, פ\"א. מאמרי אדה\"א בראשית ע' ריז. וש\"נ."],["95","49","<b>החכמה</b>: גד: הה\"ח הה' חסדים."],["96","48","<b>החכמה. . ונוצר חסד. . הבינה. . ונקה</b>: ראה ע\"ח שער הכללים פ\"ה. הנסמן במאמרי אדה\"א דברים ח\"א ע' יז־ בראשית ע' ד."],["97","50","<b>הגבו'</b>: שם: ה\"ג ה' גבורות."],["98","51","<b>שאבא. . ובינה מתלבשת </b>[ג: מלביש]<b> לגבו' דאריך</b>: ראה ע\"ח שער או\"א שי\"ד, פ\"א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שנד."],["99","52","<b>בחי'</b>: ניתוסף ע\"פ ג."],["100","53","<b>מדות דחו\"ב הנק' יסו\"ת</b>: [ ישראל סבא ותבונה] ראה שעה\"י קי, ב ובהערה 15. שם קנז, ג ואילך. לקמן מאמר ד\"ה אשה כי תזריע תרכ\"ג על יד הערה 18."],["101","54","<b>שאול שהי' נחבא אל הכלים</b>: שמו\"א י, כב. ראה גם מאמרי אדה\"ז על ענינים ע' שצב ובהנסמן במ\"מ לשם."],["102","55","<b>מעולם האצילות</b>: ג: מעדאכ\"ס מעלמא דאתכסיא."],["103","56","<b>והוי </b>[ג: הוי]<b> זנב לאריות</b>: אבות פ\"ד, מט\"ו."]]],[4801940316,"בבחי' חכם הרואה את הנולד ונק' ארי' אותיות ראי'<sup data-n=\"104\">57</sup> ושועלים הם נשמות דבי\"ע כו'. אך רצון ה' שדייקא נשמה כזאת שהוא בבחי' ביטול במקורה באצי' תהי' מלך על עם נשמות דבי\"ע בכדי שתמשיך בחי' ביטול שיש לה גם בהם וממילא יהי' הגילוי למטה בבי\"ע כמו למעלה באצי' שזהו שלימות כוונת הבריאה להיות לו דירה בתחתונים, כ\"ה בכאן במקום גבוה יותר שמתחלה נאצל בחי' החכ' שהוא בבחי' ביטול במקורה ואח\"כ המשיך חסדים עליונים לפעול בבחי' החכ' בחי' מקור להשפיע ביטול שבחכ' בכל עולם האצי' ועי\"ז מתגלה בחי' מדות בחכמה שע\"י מתגלה בחי' החכ' בכל עולם האצי' כו'. אך בחי' הבינה הוא מקור לכלים דאצי' להלביש האורות הנמשכים מבחי' החכ', וזהו עצם הבינה שמקורה חסד להשפיע בחי' יש מקור הכלי' אך מתלבשת בבחי'<sup data-n=\"105\">58</sup> גבורות בכדי להאציל הכלים בבחי' ריבוי והתחלקות כו', וזהו איהו וחיוהי חד<sup data-n=\"106\">59</sup>, שזהו שפע החכמה הנק' חיוהי, ואיהו<sup data-n=\"107\">60</sup> וגרמוהי הוא בחי' שפע הבינה הממשיך כלים כו' וד\"ל.\n<b>והנה</b> ידוע דבן מסט' דאבא קאתי<sup data-n=\"108\">61</sup> שבחי' המדות דאצי' הנק' בן נמשכים מבחי' המדות שבחכ' שנק' אבא<sup data-n=\"109\">62</sup> כו', וכאמה בתה<sup data-n=\"110\">63</sup> שבחי' המל' נמשך מבחי' בינה כו'. ולפעמים א' להיפוך דאבא יסד ברתא<sup data-n=\"111\">64</sup> כמ\"ש הוי' בחכמה יסד ארץ<sup data-n=\"112\">65</sup>, וכונן שמים שהם המדות דאצי' בתבונה כו'. אך הענין הוא דעצמות פנימי' המדות הוא מבחי' החכ' כמבואר בבה\"ז במאמר כי מראש צורים אראנו<sup data-n=\"113\">66</sup> כו', אך בחי' התלבשות המדות בריבוי כלים כו'<sup data-n=\"114\">67</sup> כל מדה כלולה מיו\"ד ויו\"ד מיו\"ד עד אין שיעור זהו מצד הבינה. ועד\"מ מטיפת הזרע שנמשכה ממוח האב דייקא וכלולים בה כל רמ\"ח אברים בהעלם, ואח\"כ בבחי' האם מצטיירים כל האברי' בפרט ואח\"כ היא מוליד את הילד ומוציאו לאויר העולם. כן למעלה עצמיות המדות נמשכים מן החכמה ונקלטים בבחי' יסוד אימא, ושם מתחלקים בריבוי כלים, אך עדיין הם בהעלם בבחי' עיבור ואח\"כ מתגלים ע\"י הבינה להיות מקור להתהוות עולמות הנבראים מאין ליש כמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"115\">68</sup> שמקור בנין הנבראים הוא מבחי' המדות דאצי' שראשיתם הוא בחי' חסד כו'. ונמצא שעצמיות פנימי' המדות שהוא החיות שבהם הוא מבחי' החכ' (ונק' בנין הצורה כו'). אך התלבשותם בכלים והתגלותם להיות",[["104","57","<b>ארי' אותיות ראי'</b>: ראה ת\"ז ת\"ע [קכב, א]. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'ל."],["105","58","<b>החכ' וזהו. . בבחי'</b>: ניתוסף ע\"פ גד."],["106","59","<b>איהו וחיוהי חד</b>: ת\"ז בהקדמה ג, ב."],["107","60","<b>ואיהו</b>: ג: ליתא."],["108","61","<b>דבן מסט' דאבא קאתי</b>: ראה זהר במדבר קכ, א. מאמרי אדה\"א בראשית ע' תקלד. וש\"נ. אמ\"ב שער התפילין קכג, ג. וש\"נ. תו\"ח בראשית כח, ד."],["109","62","<b>שבחכ' שנק' אבא</b>: ראה תניא פ\"ג. מאמרי אדה\"א בראשית ע' א. וש\"נ. ש\"א ד, א הערה 9."],["110","63","<b>וכאמה בתה</b>: יחזקאל טז, מד."],["111","64","<b>דאבא יסד ברתא</b>: ראה זהר רע\"מ פינחס רנו, ב. רמח, א. רנח, א. אגה\"ק ס\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפ בהערה מצירופי. קונטרסים ס\"ע תקמז ואילך."],["112","65","<b>הוי' בחכמה יסד ארץ</b>: משלי ג, יט."],["113","66","<b>בבה\"ז במאמר כי מראש צורים אראנו</b>: בלק קג, סע\"א ואילך."],["114","67","<b>כו'</b>: גד: כי."],["115","68","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם לקמן מאמר ד\"ה ענין יצי\"מ וקי\"ס ובהערה 90."]]],[4801940365,"מקור מאין ליש (ונק' בנין החומר כו'), זהו ע\"י מדות דבינה שנק' תבונה כו'. אך בבחי' המל' דאצי' הוא להיפוך שעצמי' המל' הוא מבחי' המדות דבינה הנק' תבונה כו', שהוא מה שנאמר בזהר פ' בלק דמסט' דאימא אתמתח<sup data-n=\"116\">69</sup> ואושיט פסיעה לבר (ע' בב\"ז במאמר הנ\"ל). אך התגלות עצם המל' בריבוי כלים להיות פרצוף שלם בע\"ס כ\"א כלול מיו\"ד ויו\"ד מיו\"ד עד אין שיעור זהו מצד החכ' כידוע למטה מבשרי אחזה שצירופי אותי' הדיבור בריבוי והתחלקות הוא מצד מקור החכ' דייקא הנק' קדמות השכל ע' באגה\"ק במאמר ויעש דוד שם<sup data-n=\"117\">70</sup> כו'.\n<b>ובזה</b> יתורץ ענין הנ\"ל דמש\"א דבן (שהם בחי' המדות דז\"א) מסט' דאבא קאתי היינו הצורה<sup data-n=\"118\">71</sup> שעצמו' המדות נמשכים מבחי' החכ', ומש\"א כונן שמים בתבונה היינו התכוננותם<sup data-n=\"119\">72</sup> שהוא בנין החומר שלהם הוא<sup data-n=\"120\">73</sup> מצד המדות דבינה הנק' תבונה, ובמל' דאצי' העצמי' שהוא בחי' הצורה הוא מבחי' הבינה שעז\"נ דאמה כו' ובפי'<sup data-n=\"121\">74</sup> ההתפשטות בריבוי כלים שהוא בחי' בנין החומר הוא מצד החכ' ועז\"נ ה' בחכמה יסד ארץ כו'. אך א\"כ לכאורה אינו מובן מה שבכמה מקומות נאמר שבנין הזכר הוא מהחסדים<sup data-n=\"122\">75</sup>, ולפי הנ\"ל בנין המדות דז\"א שהוא בחי' דכר הוא מבחי' תבונה שהוא בחי' מדות דבינה, ומבואר למעלה דבינה מתגלים מצד ה\"ג דמזל ונקה או גבו' דאריך המתלבש בה ולכן הם בבחי' גבו' כו' ומהם נמשך בנין המדות דז\"א וא\"כ איך א' דבנין הזכר מהחסדים כו' ומל' בנינה מצד החכ', ואם הכוונה על מדות דחכ' הרי הם מתגלים מצד ה\"ח דמזל ונוצר או מבחי' חסד דאריך המתלבש בחכ' וא\"כ הם בבחי' חסדים ומהם נמשך בנין המל' ואיך א' דבנין המל' מהגבו', אך הנה מבואר בכהאריז\"ל שגם שבבחי' בינה נמשך ה' גבו' ממזל ונקה ובבחי' חכמה נמשך ה' חסדים ממזל ונוצר מ\"מ יש בחי' חו\"ג במוחין דאבא וחו\"ג במוחין דאימא<sup data-n=\"123\">76</sup> כו' וא\"כ יתורץ קושי' הנ\"ל כי הגם שבנין הז\"א הוא מבחי' תבונה מ\"מ בנינו מהחסדים שבה ובנין המל' הוא מבחי' חכ' מהגבו' דחכ' כו'.\n<b>ועתה</b> יובן ענין הסתירה הנ\"ל שמה שמבואר כאן שבחי' רוח האדם הוא עולה למעלה ואינו רוצה בהשפעה היינו בחי' מ\"ה דחכמה שבא מצד הביטול במקורו בחי' האין שלמעלה מבחי' החכמה מצד קרבתה אליו כי הוא ראשית הגילוי מבחי' האין כו' והיינו ג\"ר דחכ' כו' וא\"כ הוא בבחי' הגבו' לעלות למעלה. אבל בחי' המדות דחכ' מקבלים מבחי' ה\"ח דמזל השמיני שפועלים טבע הירידה בבחי' מ\"ה דחכ' שיתלבש במדות שבחכ' כו' ומבחי' מדות שבחכ' נמשך בחי' המדות דז\"א, לכן",[["116","69","<b>בזהר </b>[ג בזוה\"ק]<b> פ' בלק דמסט' דאימא אתמתח</b>: ראה שם רג, ב."],["117","70","<b>באגה\"ק במאמר ויעש דוד שם</b>: ס\"ה."],["118","71","<b>הצורה</b>: גד: מצד הצורה."],["119","72","<b>התכוננותם</b>: תוקן ע\"פ גד."],["120","73","<b>הוא</b>: ג: ליתא."],["121","74","<b>דאמה כו' ובפי</b>: גד: כאמה כן בתה כו' ובחי'."],["122","75","<b>שבנין הזכר הוא מהחסדים</b>: ראה זהר תזריע מח, ב. נשא קמה, ב. ע\"ח שער מ\"ן ומ\"ד שט\"ל, דרוש י."],["123","76","<b>מבואר בכהאריז\"ל. . חו\"ג במוחין דאבא. . דאימא</b>: ראה פע\"ח שער הציצית ש\"ג, פ\"ד. שער הכוונות שם דרוש ג."]]],[4801940411,"המ\"ה זה שבמדות הוא בחי' טבע הירידה להשפיע, ולכן נא' בלק\"ת שבחי' מ\"ה הוא הוא<sup data-n=\"124\">77</sup> בחי' חסד כו', ומבשרי אחזה חכם עמוק הוא בבחי' ביטול בתמידות מחמת שטרוד בעצמותו להשכיל בעא\"ע לכן הוא רחוק מהשפעה כו', משא\"כ חסד שבלב כמו איש החסדן בטבעו הוא בבחי' ביטול מצד השפלות ולכן יכול להשפיע כל אשר לו לזולתו כמאמר לשארית נחלתו למי שמשים עצמו כשיריים<sup data-n=\"125\">78</sup> וכמו אברהם דעביד טיבו יתירה<sup data-n=\"126\">79</sup> כו' מצד השפלות כמאמר ואנכי עפר ואפר<sup data-n=\"127\">80</sup> כו'.\n<b>ומעתה</b> יובן ג\"כ בבחי' המל' שהגם שמבואר למעלה שבחי' המל' עצמותה הוא מצד הגבורות וגם בניינה שהוא מבחי' החכ' הוא מבחי' הגבו' שבחכ' וא\"כ טבעה לעלות ולהסתלק למעלה כמאמר למען יזמרך<sup data-n=\"128\">81</sup> כו' נהורא תתאה קארי תדיר לנהו\"ע<sup data-n=\"129\">82</sup> כו' מ\"מ המשכתה להתלבש בבי\"ע זהו מצד החסדים דייקא, כמו במלך ממלכי ישראל שאינו חפץ במלוכה כנ\"ל, ואעפ\"כ רצון ה' פעל בו להיות בבחי' חסד להיות בבחי' ירידה להיות מלך על עם כו', כן כבי' למעלה רצון ה' להתלבש מדת המלוכה בבי\"ע להיות מלך על הנבראים נשמות ומלאכים דבי\"ע הנק' עם כו' וזהו והוכן בחסד כסא<sup data-n=\"130\">83</sup> כו', (כי<sup data-n=\"131\">84</sup> כסא הוא התלבשות מל' דמל' בבי\"ע כידוע בכהאריז\"ל דאורות תנה\"י דמל' המתלבשים בכחב\"ד דבריאה נק' כסא<sup data-n=\"132\">85</sup> והתלבשות זאת הוא מצד החסד עליון שבעצמות שרוצה וחפץ חסד הוא להיות לו דירה כו'). וזהו רוח הבהמה שהוא בחי' מל' דאצי' המתלבשת בבריאה יורדת למטה כטבע החסד כו' כי בניינה הוא ע\"י החסד כו' ולכן נק' בחי' רוח הבהמה כי בחי' חי הוא בבריאה<sup data-n=\"133\">86</sup> משא\"כ אצי' הוא בחי' מדבר ולכן המל' דאצי' כמ\"ש בבחי' אצי' נכללת ברוח האדם כו'. והנה שרש אדם ובהמה בעצמות אא\"ס שלפני הצמצום כו' שעל בחי' זאת נאמר כי לא אדם<sup data-n=\"134\">87</sup> אך שרש כל הבחי' ישנם בעצמות כו' היינו בחי' שעשועי' העצמי'<sup data-n=\"135\">88</sup> התגלות בחי' יחיד שזהו דוגמת רוח האדם לעלות למעלה בעצמותו אך בחי' אחד מה שעלה ברצונו להיטיב<sup data-n=\"136\">89</sup> ואנא אמלוך<sup data-n=\"137\">90</sup> שזהו שרש כח הירידה להתלבש למטה בעולמות כדוגמת רוח הבהמה היורדת כו' כל הנ\"ל כתבתי בדא\"פ וה' יצילנו משגיאות כו', עכ\"ה<sup data-n=\"138\">91</sup>. ..).",[["124","77","<b>הוא</b>: ג: ליתא."],["125","78","<b>לשארית נחלתו. . כשיריים</b>: מיכה ז, יח. ר\"ה יז, סע\"א ואילך."],["126","79","<b>אברהם דעביד טיבו יתירה</b>: ראה זהר ואתחנן רסב, ב. סידור שער התפילין יב, א. אמ\"ב שם קלז, א."],["127","80","<b>ואנכי עפר ואפר</b>: וירא יח, כז."],["128","81","<b>למען יזמרך</b>: תהלים ל, יג."],["129","82","<b>נהורא תתאה קארי תדיר לנהו\"ע</b>: ראה זהר היכלות פקודי רנו, ב. תרומה קמ, רע\"א. וישלח קעח, ב. לך עז, ב. פו, ב."],["130","83","<b>והוכן בחסד כסא</b>: ישעי' טז, ה."],["131","84","<b>כו' (כי</b>: תוקן ע\"פ ד. ובכת\"י זה כו') כי."],["132","85","<b>דאורות תנה\"י דמל'. . כסא</b>: ראה ע\"ח שער כסא הכבוד שמ\"ו, פ\"א."],["133","86","<b>חי הוא בבריאה</b>: ראה סה\"ש תשנ\"ב ע' 139 הערה 54. תו\"ח משפטים ח\"ב רצט, א. וש\"נ."],["134","87","<b>כי לא אדם</b>: שמו\"א טו, כט."],["135","88","<b>שעשועי' העצמי'</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. קונטרסים ע' שמה ובהנסמן בהנ\"ל."],["136","89","<b>שעלה ברצונו להיטיב</b>: ראה שבר יוסף ס\"א. כנפי יונה ח\"א, פ\"א. לקמן מאמר ד\"ה להבין וכו' פסח ומצה הערות 62-3."],["137","90","<b>ואנא אמלוך</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ז ”וכמ\"ש בזהר בפי' וימלוך אנא אמלוך\". הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצד."],["138","91","<b>עכ\"ה</b>: ההגה מתחלת לעיל על יד הערה 31."]]],[4801940453,"<b>והנה</b> כשהי' מקריבין הקרבן הי' עולה רוחני' החיות שבבהמה ונכללת במקורה בבחי' פני שור<sup data-n=\"139\">92</sup> שבמרכבה כו', ועופות עולים ונכללים בפני נשר כו', ועי\"ז פועלים שגם המה יעלו ויוכללו בבחי' רוח הבהמה שהיא בחי' המל' דאצי' המתלבשת בבריאה שהוא בבחי' שם ב\"ן כו' ואח\"כ נעשה העליות המל' הנק' רוח הבהמה ונכלל בבחי' פני אדם שהוא בחי' שם מ\"ה דז\"א כו', ונמצא שע\"י הקרבן נעשה טבע חדש בבחי' רוח הבהמה לעלות למעלה בבחי' ביטול והתכללות בעצמות אוא\"ס ועלי' זאת גורם בחי' המשכה מלמעלה למטה להיות נגלה גילוי אא\"ס למטה כמו למעלה (... ונעשה בבחי' רוח האדם טבע חדש לירד למטה בבחי' השפעה כו'. ..) ואז ע\"י התכללות זאת דאדם ובהמה שהוא בחי' מ\"ה וב\"ן נעשה (... כי רוח הבהמה שטבעה לירד נכלל בבחי' טבע רוח האדם לעלות למעלה ורוח האדם שבטבעו לעלות נכלל מבחי'<sup data-n=\"140\">93</sup> רוח הבהמה לירד למטה כו'. ..) נעשה<sup data-n=\"141\">94</sup> אח\"כ יחוד מ\"ה וב\"ן בתכלית, והיינו שמתייחדים כא' ממש להיות מהם תולדה אחת (... כמ\"ש ודבק באשתו והיו לבשר אחד<sup data-n=\"142\">95</sup> כו'. ..) היינו שנמשך גילוי חדש ע\"י שניהם שלפניו מעלה ומטה שוין ולכן מתגלה למטה בבי\"ע כמו באצי' ממש כו'.\n<b>והנה</b> בבחי' הקרבת הקרבן הי' ע\"י אש שלמעלה שהי' יורד ע\"ג המזבח, אך אעפ\"כ מצוה להביא מן ההדיוט<sup data-n=\"143\">96</sup> כו', הענין הוא כי מבואר למעלה שרוחני' חיות הבהמה עולה ונכלל בבחי' פני שור שבמרכבה ועי\"ז גורם שבחי' פני שור יעלה ויכלל<sup data-n=\"144\">97</sup> בבחי' המל' דאצי' שבבריאה שהוא בחי' שם ב\"ן כו'<sup data-n=\"145\">98</sup> ב' עליות אלו היו נעשים ע\"י אש של הדיוט שהוא בחי' גבו' שבג' עולמות דבי\"ע (... שכללותם הוא מט\"ט שרו ש\"ע<sup data-n=\"146\">99</sup> שנק' הדיוט לגבי מארי'<sup data-n=\"147\">100</sup> כו')<sup data-n=\"148\">101</sup> (... וגם התהוות ג' העולמות דבי\"ע הוא ע\"י צי\"א<sup data-n=\"149\">102</sup> דעש\"מ שנק' מילין דהדיוטא<sup data-n=\"150\">103</sup> כידוע. ..) אך עליות רוח הבהמה שהוא בחי' המל' דאצי' שעולה ונכללת בבחי' רוח האדם שהוא בחי' ז\"א דאצי' (... שזהו ע\"י בירור שני דשם מ\"ה מברר לב\"ן<sup data-n=\"151\">104</sup> בבחי' בירור אחר בירור כידוע. ..) זהו ע\"י אש שלמעלה שהם גבורות עליונות דאצי' כו' (... ואפ\"ל שב' אשות הללו הם בחי' אש יו\"ד ואש ה' דאיש ואשה<sup data-n=\"152\">105</sup> כו' וד\"ל. ..).",[["139","92","<b>הקרבן. . במקורה. . פני שור</b>: ראה זהר פינחס רמ, ב. לקמן מאמר ד\"ה ואכלתם אכול תקצ\"ט על יד הערה 32. סה\"מ תרל\"ח ע' לה."],["140","93","<b>מבחי'</b>: ג: בבחי' טבע."],["141","94","<b>נעשה</b>: שם: ליתא."],["142","95","<b>ודבק באשתו והיו לבשר אחד</b>: בראשית ב, כד."],["143","96","<b>אש שלמעלה. . להביא מן ההדיוט</b>: ראה תו\"כ ויקרא א, ז. ערובין סג, א. מאמרי אדה\"א דברים ח\"ד ע' א'תפה. וש\"נ."],["144","97","<b>ויכלל</b>: ג: ונכלל למע'."],["145","98","<b>כו'</b>: שם: כי."],["146","99","<b>מט\"ט שרו ש\"ע</b>: ראה יבמות טז, ב ובתוס' שם."],["147","100","<b>מט\"ט. . הדיוט לגבי מארי'</b>: ראה זהר רע\"מ תצא רעו, א."],["148","101","<b>כו')</b>: ניתוסף ע\"פ ד."],["149","102","<b>צי\"א</b>: צירופי אותיות."],["150","103","<b>דעש\"מ שנק' מילין דהדיוטא</b>: ראה זהר בהעלותך קמט, ב. סידור שער התפלה יח, סע\"ד. לקו\"ת אחרי כה, ב."],["151","104","<b>בירור שני דשם מ\"ה מברר לב\"ן</b>: ראה תו\"א ויחי מז, ד ואילך."],["152","105","<b>אש יו\"ד ואש ה' דאיש ואשה</b>: ראה סוטה יז, א. סידור שער הק\"ש פ, א ואילך. תו\"ח בשלח ח\"א רלח, ב. וש\"נ."]]],[4801940490,"<b>והנה</b> עם כל הנ\"ל יובן ענין תיכף לסמיכה שחיטה<sup data-n=\"153\">106</sup> כי ע\"י הסמיכה ממשיך כח ועוז ברוחני' החיות שבבהמה שתוכל לעלות ע\"י שתי אשות הנ\"ל ולהתייחד בבחי' רוח האדם בחי' שם מ\"ה העליון שבאצי', ולכן צ\"ל תיכף לסמיכה שחיטה כי ע\"י התכיפה מייחדים המשכת אור העליון ברוחני' החיות שבבהמה שתוכל לעלות עי\"ז, ולכן הסמיכה הוא בשתי ידים<sup data-n=\"154\">107</sup> ובכל כחו<sup data-n=\"155\">108</sup> כי ב\"פ יד בגימט' כח<sup data-n=\"156\">109</sup> ובכל כחו הוא כ\"ח וי\"ו<sup data-n=\"157\">110</sup> שהוי\"ו הוא המייחד שתי ידים כו' (... ואפ\"ל<sup data-n=\"158\">111</sup> דב' ידים הם שתי מדות חו\"ג כמו שהם בשרשם בעצמות היחידה כי הידים יוכל להגביה למעלה מן הראש מצד שרשם הנ\"ל וכח וי\"ו הוא עצמות היחידה שבו מתייחדים שתי ידות<sup data-n=\"159\">112</sup> הנ\"ל בתכלית ואפשר הוא בחי' יד רמה המבואר בסידור במאמר חייב אינש לבסומי<sup data-n=\"160\">113</sup> כו' וד\"ל. ..) וע\"י כח וי\"ו הנ\"ל נותנים כח ברוח הבהמה שתוכל לעלות כו', וכן העונה איש\"ר בכל כחו<sup data-n=\"161\">114</sup> הכוונה ג\"כ כנ\"ל שמתגלה בחי'<sup data-n=\"162\">115</sup> וי\"ו הנ\"ל ועי\"ז ממשיך בחי' שמו הגדול כו' (... שהוא עצמי' היחידה כנ\"ל בהג\"ה. ..) ונותן כח ועוז בבחי' המל' הנק' שם סתם שתתעלה ותתרומם עי\"ז כמו שמסיים ויתרומם כו' ויתעלה כו' שמי' דקוב\"ה כו' שהוא בחי' המל' הנק' שמי' דקוב\"ה כו' וד\"ל.\n<b>וכ\"ה</b> עד\"ז בתפילה במקום קרבן שמתחלה בפסוד\"ז ובברכות יוצר הוא ההתבוננות מבחי' השתלשלות שמוליד עי\"ז אהבה כרשפי אש התשוקה לדבקה בו וזה נק' אש של הדיוט כו', אך אח\"כ בא<sup data-n=\"163\">116</sup> לבחי' מס\"נ באחד וזהו שמע ישראל הנה\"א הנק' ישראל מצד שמשתררת<sup data-n=\"164\">117</sup> על בחי' אלקי' להפכו מבחי' יש לאין האלקי וכמ\"ש כי שרית<sup data-n=\"165\">118</sup> כו' וזהו בחי' אש שלמעלה כו', אך זהו עליות הנשמה שנק' ג\"כ בחי' בהמה (... כמ\"ש במ\"א דנשמות דבי\"ע נק' זרע בהמה<sup data-n=\"166\">119</sup> כו'. ..) אך שיהי' בחי' ביטול זה ועלי' זאת גם בנה\"ט כמו בנה\"א זהו בתפלה דייקא ולכן צריך מקודם לסמוך גאולה לתפי' ליתן כח ועוז בנה\"ב שתוכל לעלות בתפילה וזהו תיכף לגאולה תפילה<sup data-n=\"167\">120</sup> שתכיפה זאת ממשיך אור העליון ולייחדו בנה\"ב בכדי שיתן בה כח ועוז לעלות כו'. והנה כ\"ה בקבלת שבת שאנו אומרים לכה דודי לקראת כלה כו', הענין הוא כי המל' דאצי' המתלבשת בבריאה נק' כלה בשבת<sup data-n=\"168\">121</sup> מחמת שאז עליות",[["153","106","<b>תיכף לסמיכה שחיטה</b>: ברכות מב, א — הובא בריש המאמר כאן."],["154","107","<b>הסמיכה הוא בשתי ידים</b>: מנחות צג, א (במשנה)."],["155","108","<b>הסמיכה. . ובכל כחו</b>: חגיגה טז, ב. ראה אוה\"ת ויקרא כרך א ע' רכב."],["156","109","<b>ב\"פ יד בגימט' כח</b>: נסמן במאמר שלפנ\"ז הערה 28."],["157","110","<b>ובכל כחו הוא כ\"ח וי\"ו</b>: ראה סדר היום כונת הקדיש (ע' 12). אוה\"ת ויקרא שם."],["158","111","<b>כו' (... ואפ\"ל</b>: תוקן ע\"פ ג. ובכת\"י זה: כו') ואפ\"ל."],["159","112","<b>ידות</b>: גד: מדות."],["160","113","<b>יד רמה. . חייב אינש לבסומי</b>: סידור שער הפורים רפג, א ואילך. וראה גם תו\"א צה, ד."],["161","114","<b>העונה איש\"ר בכל כחו</b>: ראה שבת קיט, ב."],["162","115","<b>בחי'</b>: גד: כח."],["163","116","<b>בא</b>: ניתוסף ע\"פ גד."],["164","117","<b>שמשתררת</b>: תוקן ע\"פ גד."],["165","118","<b>כי שרית </b>[גד ניתוסף: עם אלקי']: וישלח לב, כט."],["166","119","<b>דנשמות דבי\"ע נק' זרע בהמה</b>: ראה תו\"א ר\"פ משפטים."],["167","120","<b>תיכף לגאולה תפילה</b>: ברכות מב, א — הובא בריש המאמר כאן."],["168","121","<b>המל' דאצי'. . כלה בשבת</b>: ראה גם תו\"ח בשלח ח\"א רצט, ב. וש\"נ."]]],[4801940523,"העולמות מצד כח האלקי שעול' מלמטלמע\"ע אחרי גמר המלאכה דהתהוות היש מאין בששת ימי בראשית כמ\"ש וביום השביעי<sup data-n=\"169\">122</sup> שבת<sup data-n=\"170\">123</sup> ולכן נק' כלה מצד עלייתה למעלה באצי' בבחי' כלות הנפש כו', ולכן צריך להמשיך בה כח ועוז מלמעלה שתוכל לעלות בעליות העולמות ולהפשיט א\"ע מבחי' צמצומה והסתרתה בלבושי דבי\"ע כו', וזהו לכה דודי להמשיך כח ועוז מן המשפיע הנק' דודי בבחי' המל' שתוכל לעלות ותקרא בשם כלה כו' וד\"ל).\n<b>והנה</b> מעתה י\"ל ענין חו\"ב כו'<sup data-n=\"171\">124</sup> כי הנה חתן וכלה הוא בחי' אדם ובחי' בהמה (... כי הדכר הוא בחי' אדם בחי' מה דחכ' שטבעו לעלות ולא לירד למטה בבחי' השפעה, והנקבה הוא בחי' ב\"ן בחי' המל' המתלבשת בבי\"ע שטבעה לירד כו'. והנה ביום החופה נמשך אור עליון מבחי' עצמות אא\"ס שלמעלה מבחי' משפיע ומקבל מלמעלה משני הפכים דחו\"ג ולכן פועל טבע חדש בבחי' אדם שהוא בחי' מ\"ה דחכ' שטבעו לעלות שזהו בחי' גבורה שיחפוץ בהשפעה וזהו בחי' חסד, ובבחי' המל' שטבעה לירד כו' שזהו בחי' חסד הוא פועל טבע חדש שתחפוץ לעלות ולהפשיט א\"ע מלבושי השפעה שזהו בחי' גבו' ולכן אז הדכר נק' בשם חתן מל' חות דרגא<sup data-n=\"172\">125</sup> כו'. והנקבה בחי' כלה מל' כלתה נפשי<sup data-n=\"173\">126</sup> או כלות הנפש כו' וד\"ל. ..) מ\"ה וב\"ן, ועלי' רוח הבהמה בחי' ב\"ן להתכלל ולהתייחד בבחי' שם מ\"ה שבאצי' שנק' רוח האדם בחי' זאת<sup data-n=\"174\">127</sup> נק' כלה מל' כלתה נפשי, והיינו ג\"כ ענין עש\"נ<sup data-n=\"175\">128</sup> ומתחלה עולים כל העולמות שהם בבחי' זמן שנק' שנה ומקום שנק' עולם בבחי' נפש שהוא בחי' המל'<sup data-n=\"176\">129</sup> דאצי' המתלבשת בבי\"ע<sup data-n=\"177\">130</sup> שנק' רוח הבהמה כנ\"ל, ואח\"כ עולה המל' שהוא בחי' נפש שנק' נפש הבהמה להתכלל באדם בחי' מה דחכ' ונק' רוח האדם (... כי בכלל מל' וז\"א מצד המוחין דחכמה שבקרבו נק' בחי' נפש ורוח<sup data-n=\"178\">131</sup> כו'. ..), ואז כאשר עולה ומתכלל ברוח האדם נק' בשם כלה, ואח\"כ המשכת השפע מלמעלה למטה בחי' עצמות אא\"ס בחכ\"ע וגורם המשכת שפע פנימי' זאת ונקלט בבחי' המל' כו' אז נק' המשפיע בשם חתן כו' (... כנ\"ל בהג\"ה שנעשה התחדשות בבחי' הדכר ובבחי' הנקבה כו'. ..), ואז נק' יחוד חו\"ב<sup data-n=\"179\">132</sup>. אך אינה ראוי' ליחוד זה כ\"א כשיומשך בה מתחילה כח ועוז לעלות ולהתייחד וזהו ברכות חתנים שהחתן מברך וממשיך כח ועוז בבחי' כלה שתוכל לעלות ולהתייחד עם החתן לקבל ולקלוט פנימי' השפע ממנו כו', ולכן מברכים שבע ברכות כי הכח ועוז צ\"ל בכל ז' ספירות שלה כו' וד\"ל.",[["169","122","<b>שעול' מלמטלמ\"ע. . שבת</b>: ניתוסף ע\"פ גד. ובכת\"י זה: שעלה מלמעלה למטה."],["170","123","<b>וביום השביעי שבת</b>: תשא לא, טז."],["171","124","<b>חו\"ב כו'</b>: גד: חו\"כ."],["172","125","<b>חתן מל' חות דרגא</b>: ראה יבמות סג, א."],["173","126","<b>כלה מל' כלתה נפשי</b>: תהלים פד, ג. ראה גם תו\"ח בשלח ח\"א רח, א ובהערה 19."],["174","127","<b>זאת</b>: ג: ז\"א."],["175","128","<b>עש\"נ</b>: עולם שנה נפש."],["176","129","<b>נפש. . המל'</b>: נסמן בסמוך הערה 131."],["177","130","<b>בבי\"ע</b>: ניתוסף ע\"פ ד."],["178","131","<b>מל' וז\"א. . נפש ורוח</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"ז. פרדס שער מהות והנהגה ש\"ח, פי\"ג. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשיז. מאמרי אדה\"א במדבר ח\"ב ע' תקעב. וש\"נ. דברים ח\"ג ע' תתעא. אוה\"ת בלק ע' א'לג."],["179","132","<b>חו\"ב</b>: גד: חו\"כ."]]],[4801940550,"<b>והנה</b> אחר העלי' נק' אלישבע (... כי שם אל הוא בחסד<sup data-n=\"180\">133</sup> וחסד כולל כל המדות דז\"א והוא<sup data-n=\"181\">134</sup> מורה על המוחין דז\"א, ולכן כאשר המל' עולה ומתייחדת בכל ז\"ס שלה עם כל הבחי' דז\"א מוחין ומדות נק' אלישבע<sup data-n=\"182\">135</sup> כנלע\"ד בדא\"פ. ..), משא\"כ קודם העלי' והיחוד נק' בת שבע<sup data-n=\"183\">136</sup> כו' (... כי בת נק' בחי' המל'<sup data-n=\"184\">137</sup> דאצי' המסתתרת בבי\"ע וגם אז יש בה ג\"כ ז\"מ ולכן קודם היחוד עם בעלה המשפיע נק' בת שבע כו'. ..). והנה בתפלה יש ג\"כ שבע ברכות קודם ק\"ש ואחר ק\"ש ג' בשחר וד' בערב<sup data-n=\"185\">138</sup> כו' וברכות אלו הם ע\"ד ברכת חתנים הממשיכים כח ועוז בבחי' המל' דאצי' שתעלה ותתייחד עם בחי' ז\"א, והנה ידוע שעיקר היחוד הוא בתפלת ערבית כמבואר בב\"ז פ' חיי שרה במאמ' א' ההוא גברא<sup data-n=\"186\">139</sup> כו', והנה קודם תפלת ערבית כבר נגמרו כל השבע ברכות שעל ידיהם נמשך כח ועוז בבחי' המל' דאצי' שתוכל להתייחד עם בעלה המשפיע בתפלת ערבית ולכן ברכה שביעית הוא השכיבנו אבינו לשלום כי שכיבה הוא גוף היחוד כמבואר בפסוק וישכב כו' יש כ\"ב<sup data-n=\"187\">140</sup>, דהיינו כ\"ב אתוון דאורייתא דמעייל המשפיע במקבל (... שזהו קליטת פנימי' השפע דמשפיע שהוא בחי' התורה ששרשה בפנימי' [ועצמו' אא\"ס כי אוריית' קוב\"ה כל\"ח<sup data-n=\"188\">141</sup> ונמשכת בבחי' המדות דז\"א דאצילות<sup data-n=\"189\">142</sup> והוא המשפיע שפע זאת בבחי' המל'] דאצי' וזה\"ע היחוד ולכן מ\"ת נק' יום חתונתו<sup data-n=\"190\">143</sup> כו' וד\"ל. ..).\n<b>והנה</b> שבע ברכות אינם מברכים רק כשיש פנים חדשות<sup data-n=\"191\">144</sup> (... לבד ביום החופה מברכים גם כשאין פנים חדשות מטעם שית'. ..), והטעם לזה כי באמת שרש ומקור הברכות הנמשכי' לכלה ליתן בה כח ועוז כנ\"ל הוא ממקום יותר גבוה מן החתן והחתן אינו רק מעבר בלבד להשפע הנמשך על ידם כו', ומקור הברכות הוא נמשך ע\"י פנים חדשות ששרשו בבחי' פנימי' המוחין דחו\"ב עילאין שלמעלה מהתחלקות חו\"ג, ומשם הי' שרש נשמת ר\"מ ולכן הי' אומר על טמא טהור ומראה",[["180","133","<b>אל הוא בחסד</b>: ראה זהר אחרי סה, א. הנסמן בתו\"ח נח סד, ג הערה 39."],["181","134","<b>והוא</b>: ג: והיו\"ד."],["182","135","<b>המל'. . אלישבע</b>: ראה גם זהר בשלח מט, ב (ובאוה\"ח שם). שמיני לח, ב (ובאוה\"ח שם). לט, א. אוה\"ת שבהערה הבאה."],["183","136","<b>המל'. . בת שבע</b>: ראה זהר שמיני לז, א. לח, ב. לקו\"ת להאריזל ס\"פ עקב. מאמר הפסיעות של אברהם אבינו בתחילתו נדפס ב(סו\"ס חסד לאברהם — ושם נשמטו תיבות אלו)־ שער מאמרי רז\"ל לב\"ר פמ\"ג־ כתבים חדשים להרח\"ו ירושלים תשמ\"ח ע' א. אוה\"ת נח כרך א ע' 120. בהעלותך ע' שכד."],["184","137","<b>בת. . המל'</b>: ראה גם פרדס שעה\"כ שכ\"ג, פ\"ב מערכת בת."],["185","138","<b>ג' בשחר וד' בערב</b>: ראה סה\"מ תרל\"ג ח\"א ע' רעו ואילך. ע' רצט ואילך. ע' שז ואילך."],["186","139","<b>שעיקר היחוד. . בב\"ז. . ההוא גברא</b>: יג, סע\"ד ואילך. ראה גם אוה\"ת סידור כאן (ע' רפג סוס\"ד)."],["187","140","<b>וישכב כו' יש כ\"ב</b>: ויצא כח, יא. ראה זהר רע\"מ פינחס רלט, א."],["188","141","<b>אוריית' קוב\"ה כל\"ח</b>: מובא בתניא (פ\"ד ופכ\"ג) בשם הזהר. ראה מאמרי אדה\"א ויקרא ח\"א ע' רפה. וש\"נ. אוה\"ת חוקת ע' תשס."],["189","142","<b>דאצילות</b>: ניתוסף ע\"פ גד."],["190","143","<b>מ\"ת נק' יום חתונתו</b>: שה\"ש ג, יא. תענית כו, ב (במשנה)."],["191","144","<b>שבע ברכות. . פנים חדשות</b>: ראה כתובות ח, א. רמב\"ם הל' ברכות פ\"ב, ה\"י. טושו\"ע אהע\"ז הל' קדושין סס\"ב, ס\"ז."]]],[4801940569,"לו פנים<sup data-n=\"192\">145</sup> כו'<sup data-n=\"193\">146</sup>, והיינו מחמת שמבחי' עצם החכ' או עצם הבינה יוכל להתהפך מחסדי' לגבורות ומגבורות לחסדים (... כמו כי יצר לב האדם<sup data-n=\"194\">147</sup> מנעוריו, שמתחילה שמשה סברא זאת על גבורו' ודינין להביא מבול לעולם, ואח\"כ מצד סברא זאת גופא אמר הוי' לא אוסיף עוד<sup data-n=\"195\">148</sup> כו' כי יצר לב האדם כו' ולכן אין להאשימו בזה כו'. ..) וכ\"ה ענין פנים חדשות שרשו ג\"כ בבחי' פנימי' המוחין דחו\"ב עילאין ושם שורה עצמות אא\"ס ומשם נמשך השפע ליתן כח ועוז לבחי' הכלה שתוכל לעלות ולהתייחד כו', אך נק' אעפ\"כ ברכת חתנים מצד שהשפע עוברת דרך החתן כו', ולכן נק' פנים חדשות כי פנים נק' בעת התלבשותם בבחי' חתן שהוא בחי' דכר, וחדשות נק' כאשר מתלבשים בבחי' הכלה בחי' המל' דאצי' ליתן לה כח ועוז לעלות ולכן נק' ל' נוק' כו', ונמצא שבחי' דכר ונוק' כלולים כחדא והוא ע\"ד אילה שלוחה הנותן אמרי שפר<sup data-n=\"196\">149</sup> שהנותן ל' דכר קאי על שרש התו' בבחי' שעשועים שאז הוא בבחי' דכר, ואילה שלוחה ל' נוק' קאי על התלבשות שפע התו' בדיבור שאז הוא בבחי' נוק', וכ\"ה כאן כנ\"ל, (... אך מה שביום החופה א\"צ לפנים חדשות כי אז החתן בעצמו במעלה ומדריגה גבוה כו'<sup data-n=\"197\">150</sup> מחמת חופתו ומתעלה<sup data-n=\"198\">151</sup> לבחי' או\"א עילאין שמשם מקור הברכות לכלה ולכן בכחו לברך את הכלה בלתי פנים חדשות כו'. ..), והנה ע\"ד ברכת חתנים הוא ג\"כ ענין ברכת כהנים כו' שהכהנים יש להם כח לברך לבחי' מקבל ליתן בה כח ועוז שתוכל לעלות ולהתייחד בבחי' המשפיע (... והמשכת השפע שהוא גוף היחוד הוא אח\"כ בשים שלום. ..) כו' וד\"ל.\n<b>והנה</b> הטעם לכל הנ\"ל מפני מה יש כח להחתן לברך את הכלה כו' וכן כהנים לברך את ישראל כו' הוא מטעם המבואר בזהר ע\"פ נשמת כל חי תברך כו' דקאי על נשמתא דפרחא מחי העולמים<sup data-n=\"199\">152</sup> לכן אית לה רשו לברכא להאי אתר כו', וכ\"ה עד\"ז בחתן מאיר בו נשמתא דפרחא מחי העולמים כנ\"ל, וכן הכהן מאיר בו בחי' נשמה הנ\"ל לכן יש בהם כח לברך את המל' הנק' שם כו' וד\"ל (... כי חי העולמים הוא בחי' יסוד ז\"א<sup data-n=\"200\">153</sup> ובשרשו הוא בחי' פנימי' הקו ששרשו מבחי' אורך העצמי<sup data-n=\"201\">154</sup> בחי' יחיד ממש, לכן נשמה כזאת יש לה כח לברך את בחי' המל' הנק' שם ואפי' בחי' מל' דא\"ס הנק' שמך עליון מצד שרשה בבחי' יחיד שלמעלה מבחי' הנק' בחי' א\"ס כידוע בשם הרה\"מ נ\"ע שעל העצמות לא יתכן לומר בחי' א\"ס<sup data-n=\"202\">155</sup> כו'",[["192","145","<b>ר\"מ. . ומראה לו פנים</b>: ראה ערובין יג, ב. מאמרי אדה\"א נ\"ך ע' שמא. תו\"ח שמות ח\"א טז, ב ובהנסמן בהנ\"ל."],["193","146","<b>כו'</b>: ג: של טהור."],["194","147","<b>כי יצר לב האדם </b>[ד ניתוסף: רע]<b> מנעוריו</b>: נח ח, כא."],["195","148","<b>לא אוסיף עוד</b>: ראה נח שם. לקמן ביאור מאמר ד\"ה והניף הכהן אותם ובהערה 54."],["196","149","<b>אילה שלוחה הנותן אמרי שפר</b>: ויחי מט, כא. ראה פלח הרמון בראשית קלה, רע\"א."],["197","150","<b>כו'</b>: ג: כי."],["198","151","<b>ומתעלה</b>: ג: נתעלה."],["199","152","<b>נשמת כל חי. . דפרחא מחי העולמים</b>: פיוט נשמת. ראה זהר תרומה קלח, א."],["200","153","<b>חי העולמים. . יסוד ז\"א</b>: ראה זהר מקץ קצג, ב. יאיר נתיב למאו\"א מערכת חי סכ\"ד. שעה\"י קלד, א."],["201","154","<b>אורך העצמי</b>: ג: אור העצמות."],["202","155","<b>בשם הרה\"מ נ\"ע שעל העצמות לא יתכן. . א\"ס</b>: ראה אוה\"ת נשא — כרך ד — ע' א'תלט [ובמהדורת תשנ\"ה כרך א ע' 82] והוא הנחת ר' הלל מש\"פ נשא תר\"י יודפס בע\"ה בספרו פלח הרמון בפ' נשא. לקמן מאמר ד\"ה וידבר וכו' אלה הם מועדי תר\"כ על יד הערה 48. ביאור ד\"ה את שבתותי תרי\"ב על יד הערה 11. פלח הרמון בראשית ז, ב. לך מד, סע\"א. (מקץ קח, א). וארא ע' מ. ע' ס. יתרו ס\"ע רסג. מג\"א ר\"ע שצו. ע' תו. ע' תיב. ע' תכא. שה\"ש ע' 100. ע' 250. וראה שם קטז, סע\"א בשם הרמ\"ע ז\"ל — ראה יונת אלם בהקדמה. פלח הרמון — להנ\"ל — שער ד, פ\"ג. תו\"ח ויקהל ח\"ב שפח, ג."]]],[4801940584,"וד\"ל. ..). אך ברכת הדיוט הוא מלמטה למעלה כו' (... פי' כנ\"ל שמט\"ט שרו ש\"ע נק' הדיוט לגבי מארי' כו' והוא הכולל דכל הנשמות ומלאכים דבי\"ע<sup data-n=\"203\">156</sup>.\n<b>והנה</b> בברכת יוצר נאמר וכולם פותחים כו' ומברכים ומשבחים כו', נמצא שמה שהנשמות עולים ונכללים בבחי' המל' דאצי' בבחי' ביטול נק' זה ברכה לגבי בחי' המל' מצד שמוסיפים בה כח ועוז ע\"י ביטול ועלי' זאת כו', וכן א' בזהר<sup data-n=\"204\">157</sup> בביאור על מאמר נשמת כ\"ח ביומא דחול איהי מקבלא ברכאן משאר נשמתין דקא מברכין לה מתתא שעליות מ\"ן<sup data-n=\"205\">158</sup> נשמות דבי\"ע במל' דאצי' נק' ברכה לגבי המל' מצד שמוסיפים בה כח ועוז עי\"ז כמ\"ש תנו עוז לאלקי'<sup data-n=\"206\">159</sup> כו' וזהו ברכת הדיוט כו', משא\"כ ברכת חתנים וברכת כהנים הם נשמות גבוהות הנמשכים מבחי' חי העולמים וברכתם הוא מלמעלה למטה (... ונמצא שבכלל ברכת חתנים וכהנים וברכת הדיוט הם בכלל בחי' מ\"ן ומ\"ד כו' וד\"ל. ..). ומעתה יובן ענין מארז\"ל ברכת חתנים בעשרה וחתנים מן המנין כו' כי עיקר החתן הוא הת\"ת<sup data-n=\"207\">160</sup> שהשלום<sup data-n=\"208\">161</sup> שלו בחי' יסוד וידוע שבחי' היסוד דווקא בכחו לברר<sup data-n=\"209\">162</sup> בחי' המל' דאצי' כנ\"ל בענין נשמתא דפרחא כו' לכן אית לה רשו לברכא כו', והיינו מצד שביסוד נכלל כל האורות עליונים אפי' בחי' פנימי' עתיק, אך מתי מאיר בו מפנימי' עתיק כו' היינו כשנכלל מכל הי\"ס ביחד דייקא אז מאיר בו מפנימי' עתיק כו' (... כי קוב\"ה לא שריא אלא באתר שלים<sup data-n=\"210\">163</sup> כו'. ..), ולכן ברכת חתנים בעשרה כי כשיש עשרה מישראל למטה בהסיבה אחת אז נעשה כן למעלה שכל הע\"ס נכללים בבחי' הת\"ת שהוא עיקר החתן וממילא שורה בו משלימות העליון דפנימית עתיק ואז נעשה חפץ בכל הי\"ס להשפיע וכולם נכללים בבחי' הת\"ת והיסוד להשפיע לבחי' המל' (... כמ\"ש בזהר כמה דבר נש מתייחד בכל רמ\"ח אברי' דילי'<sup data-n=\"211\">164</sup> כו'. ..) ולכן כל הי\"ס נק' בשם חתנים ע\"ש תשוקת ירידת השפע למטה ואז הת\"ת ממשיך כח ועוז לבחי' המל' שתוכל לעלות ולהתייחד כנ\"ל, ולכן בעשרה דוקא אז יש לו כח לברר את המל' כענין נשמת כל חי הנ\"ל, וחתנים מן המנין",[["203","156","<b>דבי\"ע</b>: אוצ\"ל: דבי\"ע. ..)."],["204","157","<b>בזהר</b>: תרומה קלח, א."],["205","158","<b>מתתא שעליות מ\"ן</b>: ג: לתתא ונמצא שעלי'."],["206","159","<b>תנו עוז לאלקי'</b>: תהלים סח, לה."],["207","160","<b>החתן הוא הת\"ת</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ח מערכת חתן."],["208","161","<b>שהשלום</b>: גד: שהשליש."],["209","162","<b>לברר</b>: שם: לברך."],["210","163","<b>קוב\"ה לא שריא אלא באתר שלים</b>: ראה זהר ויחי רטז, ב. אמור צ, ב. לקו\"ת אמור לח, רע\"א ובהנסמן במ\"מ לשם."],["211","164","<b>בזהר כמה דבר נש. . דילי'</b>: ראה ת\"ז בהקדמה ב, א."]]],[4801940595,"היינו הת\"ת שהוא עיקר החתן שהוא הוא<sup data-n=\"212\">165</sup> מן המנין, כי עשר ולא אחד עשר כמ\"ש בס\"י<sup data-n=\"213\">166</sup> כו' וד\"ל.",[["212","165","<b>שהוא הוא</b>: ג: שהוא."],["213","166","<b>עשר. . בס\"י</b>: פ\"א, מ\"ג (מנטובא שכ\"ב — ובדפו\"א: מ\"ד)."]]],[4801940078,"<b>ויקרא\nעוד בסעודה הנ\"ל </b>\n<b>להבין</b> בתוספת ביאור ענין פנים חדשות<sup data-n=\"214\">1</sup> מהו הנה בגמ' (מגילה דכ\"ג ע\"א) אמרו תני רב יוסף שלשה כו' שבעה רואי פני המלך, והיינו שבעה קרואים דשבתא הם כנגד שבעה רואי פני המלך. ולהבין מה ענינם לשבעה רואי פני המלך הנאמר במגילה כו'. יש להקדים ענין מאמר ריב\"ז (ברכות דף ל\"ד ע\"ב) אמר לה לאו<sup data-n=\"215\">2</sup> אלא הוא דומה כעבד לפני המלך ואני דומה כשר לפני המלך כו'. וביאור הענין הנה השר הוא המנהיג את המדינה ע\"פ נימוסי המלוכה אשר יצאו מפי המלך כו' שזהו דבר מלך שמלובש בו רצון המלך ולכן לא יוכל לפעול שום שינוי בהנהגה זאת אפי' כקוש\"י כו', משא\"כ העבד של המלך אין לו שום דעה בהנהגת המלוכה כו', אך יש בו יתרון יותר משר המלך במה שהוא עומד תמיד לפני המלך ורואהו תמיד ולכן יוכל לפרקים לפעול רצון אצל המלך היפוך מן ההנהגה הקבוע בתמידות כו' כי המלך בעצמו יוכל לשנות רצונו כו' וזהו ההפרש בין ריב\"ז ובין רחב\"ד כו', שריב\"ז הי' מקור התורה שבע\"פ כו' (... כי ר' אליעזר ור' יהושע היו תלמידיו<sup data-n=\"216\">3</sup> והמה היו רבותיו של רע\"ק<sup data-n=\"217\">4</sup> וידוע דכולהו סתימאה הוא אליבא דר' עקיבא<sup data-n=\"218\">5</sup> כו'. ..). ונמצא שהי' שר התורה<sup data-n=\"219\">6</sup>. וידוע דמלך במשפט יעמיד ארץ<sup data-n=\"220\">7</sup>, היינו הנהגת מלוכה עליונה להנהיג את כל העולמות הוא ע\"פ משפט התורה<sup data-n=\"221\">8</sup> דוקא דמחכ\"ע נפקת<sup data-n=\"222\">9</sup> ומתלבשת במדת המלוכה להנהיג עי\"ז כל העולמו' כו' ותו' זו המתלבשת במדת המלוכה<sup data-n=\"223\">10</sup> נק' תושבע\"פ כמאמר מל' פה תורה שבע\"פ קרינן לה<sup data-n=\"224\">11</sup> כו'.",[["214","1","<b>להבין בתוספת ביאור ענין פנים חדשות</b>: הנחת ר' הלל מדרוש של כ\"ק אדמו\"ר הצ\"צ משנת תרי\"ט.\nמאמר זה הוא ביאור על המאמר שנדפס לפנ\"ז.\nרשימת הצ\"צ מדרוש זה נדפסה באוה\"ת מג\"א ע' ט ושם הפתיחה: שבעת שרי פרס ומדי."],["215","2","<b>לאו</b>: תוקן ע\"פ ב."],["216","3","<b>ר' אליעזר ור' יהושע היו תלמידיו</b>: אבות פ\"ב, מ\"ט (לגי' אדה\"ז בסידורו, ובמשניות מ\"ח)."],["217","4","<b>ר' אליעזר ור' יהושע. . רבותיו של רע\"ק</b>: ראה סנהדרין סח, א. ב\"ק מא, ב. נדרים נ, א. פסחים סט, א. שבת לט, סע\"ב. רמב\"ם בהקדמה לס' היד."],["218","5","<b>דכולהו סתימאה. . דר' עקיבא</b>: ראה סנהדרין פו, א. תו\"ח שמות ח\"א י, ב הערה 457."],["219","6","<b>שר התורה</b>: ראה גם תו\"ח שם יא, ב הערה 497."],["220","7","<b>דמלך במשפט יעמיד ארץ</b>: משלי כט, ד."],["221","8","<b>דמלך במשפט. . ע\"פ משפט התורה</b>: ראה תו\"ח בשלח ח\"א קעג, א בשם הזהר. וש\"נ."],["222","9","<b>התורה. . דמחכ\"ע נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["223","10","<b>להנהיג עי\"ז. . המלוכה</b>: ניתוסף ע\"פ ב."],["224","11","<b>מל' פה תורה שבע\"פ קרינן לה</b>: ת\"ז בהקדמה יז, א."]]],[4801940144,"<b>והנה</b> ידוע דתנאים ואמוראים המה ממשיכים בחי' חכ' עילאה במדת המלוכה (... והיינו מצד ביטולם לבחי' אא\"ס שבחכ\"ע<sup data-n=\"225\">12</sup> שבבחי' אין דחכמה עילאה, ולכן נקראו סופרים<sup data-n=\"226\">13</sup> בחי' סופר דחכ\"ע למעלה מבחי' ספר<sup data-n=\"227\">14</sup> שהוא בחי' יש דחכמה המתלבש<sup data-n=\"228\">15</sup> בבחי' בינה כו' וד\"ל), ולכן המה מקורי התורה שבע\"פ ולכן המה המנהיגים את כל העולמות ע\"פ משפט התורה כו', וידוע דע\"פ משפט התורה הנפש החוטאת היא תמות<sup data-n=\"229\">16</sup> כו' (... והגם שמבואר במאמר<sup data-n=\"230\">17</sup> דהתורה אמרה יביא קרבן היינו לשגגות אבל לא לזדונות<sup data-n=\"231\">18</sup> כו'. ..) ולכן א\"א להם לפעול שינוי רצון כו' וזהו מדריגת ריב\"ז כו', אך רחב\"ד לא הי' במדריגת שר ולכן אין שום הלכה מאיתו<sup data-n=\"232\">19</sup> רק הנהגה במילי דחסידות במס' אבות כל שיראת חטאו<sup data-n=\"233\">20</sup> קודמת לחכמתו כו', אך בזה יש בו יתרון מעלה שבחי' הביטול שלו הוא ביטול פשוט לבחי' רצה\"ע שלמעלה אפי' משרש מקור החכמה (... הנק' חכ' סתימאה כו'. ..).\n<b>והנה</b> מעצם הרצון שלמעלה מן החכמה יוכל להיות שינוי רצון שלא ע\"פ משפט התורה והיינו המשכת רח\"ר להיות נושא עון ועובר על פשע<sup data-n=\"234\">21</sup> כו', וכמאמר ומה שחטאתי כו' מחוק ברחמיך הרבים אבל לא ע\"י יסורים<sup data-n=\"235\">22</sup> כו', ולכן הי' יכול לפעול בתפלתו שהוא יהי רצון כו' לשנות משפט התורה כו', וא\"כ היתרון שבבחי' עבד הוא בזה שהוא קרוב למלך ורואה פניו בתמידות ועוצם ביטולו בבחי' רצון שלמעלה מן החכמה כו', משא\"כ השר אינו רואה פני המלך כי הוא מוכרח להתלבש בענין הנהגת העולמות ע\"פ משפט התורה (... וכמשל השר המנהיג את המדינה ע\"פ רצון המלך ויכול להיות שלא יראה פני המלך כלל. ..) אך יש נשמות גבוהות שהם במדריגות שר ואעפ\"כ יש בהם ג\"כ מדריגות עבד לראות המלך בתמידות כו', וכמו משה רבינו ע\"ה שבודאי הי' במדריגת שר כי הוא מקור כל התורה (... אפילו מתורה שבע\"פ כי הכל נמסר לו בסיני כו'. ..) ואעפ\"כ נק' בשם עבד לראות פני המלך בתמידות כמאמר לא כן עבדי משה<sup data-n=\"236\">23</sup> כו' פנים אל פנים<sup data-n=\"237\">24</sup> אדבר כו', והנה נשמות אלו הם נשמות דאצי' עצמם (... כשיורדים לעוה\"ז לא נשתנה מהותם כלל כמבואר",[["225","12","<b>שבחכ\"ע בג</b>: ליתא."],["226","13","<b>נקראו סופרים</b>: ראה קדושין ל, א. מאמרי אדה\"א נ\"ך ע' נה."],["227","14","<b>סופר. . למעלה מבחי' ספר</b>: ראה גם לקמן מאמר ד\"ה וידבר כו' אלה הם מועדי תר\"כ על יד הערה 88. מאמרי אדה\"א נ\"ך ע' נו ואילך. וש\"נ."],["228","15","<b>דחכמה המתלבש</b>: ב: דח\"ע המתלבשת."],["229","16","<b>משפט התורה הנפש החוטאת היא תמות</b>: יחזקאל יח, ד. כ. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קסז. מאמרי אדה\"א בראשית ע' קעד. דברים ח\"ד ע' א'שט. וש\"נ. לקמן מאמר ד\"ה ענין יצי\"מ וקי\"ס על יד הערה 151."],["230","17","<b>במאמר</b>: ב במ\"א."],["231","18","<b>דהתורה אמרה. . לזדונות</b>: ראה סה\"מ קונטרסים ח\"א קלג, ב בשם ”מדרש\" הובא בלקו\"ש כרך ח ע' 158 הערה 58. ווי העמודים לבן השל\"ה פכ\"א (לא, א) בשם מדרש. וראה גם לקו\"ש כרך ד ע' 1359."],["232","19","<b>רחב\"ד. . אין שום הלכה מאיתו</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשיז."],["233","20","<b>כל שיראת חטאו</b>: אבות פ\"ג, מ\"ט."],["234","21","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח."],["235","22","<b>ומה שחטאתי. . לא ע\"י יסורים</b>: סיום הווידוי ביוה\"כ (אלוקי עד שלא נוצרתי)."],["236","23","<b>לא כן עבדי משה</b>: בהעלותך יב, ז."],["237","24","<b>פנים אל פנים</b>: ב: פא\"פ פה אל פה. בהעלותך שם, ח."]]],[4801940208,"באגה\"ק במאמר איהו וחיוהי<sup data-n=\"238\">25</sup> כו' ומשה רבינו הוא כולל כולם להיותו בבחי' הת\"ת<sup data-n=\"239\">26</sup> כו', משא\"כ המה הם בבחי' המדות דאצי' בפרט כו', אבל נשמות תנאים ואמוראים<sup data-n=\"240\">27</sup> הנ\"ל שרי המלוכה כו'<sup data-n=\"241\">28</sup> הם בבחי' נשמות דבריאה ויצירה כמבואר בכתבי החסידות כו' וד\"ל. ..), וזהו הנאמר במגילה שבעת שרי פרס ומדי<sup data-n=\"242\">29</sup> רואי פני המלך כו' שאע\"פ שהם במדריגות שרים מ\"מ הם רואי פני המלך כו' וד\"ל. והנה מספר שרים אלו הוא שבעה כנגד שבעה מדות שבבחי' אצי' עצמו כו' (... ולכן יוכלו להתלבש בעולמות להנהיג כל העולמות ע\"פ משפט התורה ואעפ\"כ אין העולם מסתיר בפניהם מצד שלא נשתנה מהותם כנ\"ל, ולכן יוכלו בשעת טרדתם בהנהגת העולמות ע\"פ משפט התורה לראות פני המלך כו'<sup data-n=\"243\">30</sup> יכולים להתלבש בבחי' מטה שהם העולמות דבי\"ע הנק' בשם מטה ואעפ\"כ הם דבוקים למעלה באצילות כו' וד\"ל. ..).\n<b>והנה</b> ידוע דביו\"ט נאמר ומועדים לשמחה<sup data-n=\"244\">31</sup> שאז הוא זמן השמחה ולכן אז היו עולים לרגל בזמן הבית לראות פני האדון הוי'<sup data-n=\"245\">32</sup> כו' וכמשל המלך בעת שמחתו מתגלה לכל והכל יכולים לראות אותו (... כי ביו\"ט מאירים מוחין דאימא<sup data-n=\"246\">33</sup> ושמחה הוא בבינה כמאמר אם הבנים שמחה<sup data-n=\"247\">34</sup>, לכן אז מתגלה אא\"ס בבריאה כו' כי יוצא לחוץ ממקומו כו' מצד גודל השמחה כו' ולכן הכל יכולים לראות אותו אפילו נשמות דבי\"ע כו' וד\"ל. ..) משא\"כ בשבת שאז הוא בחי' עונג<sup data-n=\"248\">35</sup> והעונג הוא בהעלם בעצמות המלך ולכן אין הכל רואים אותו (... כי בשבת הוא בחי' מוחין דאבא<sup data-n=\"249\">36</sup> הנק' עונג ואז אינו יוצא לחוץ להאיר בבי\"ע רק במקומו למעלה שהוא בחי' האצי' שהוא רשות שלו ולכן נק' רה\"י<sup data-n=\"250\">37</sup> כו' וד\"ל. ..), אך ע\"י העולים לתורה שהם ז' קרואים",[["238","25","<b>באגה\"ק במאמר איהו וחיוהי</b>: ס\"כ (קל, א)."],["239","26","<b>ומשה רבינו. . בבחי' הת\"ת</b>: ראה ת\"ז תס\"ט קיא, א. זהר חוקת קפא, ב. ע\"ח שער הכללים פ\"ג. שער ההקדמות דרוש ג' בענין זעיר ונוקבי' (קסג, רע\"א). מגלה עמוקות אופן פט [פח] (כג, ד)."],["240","27","<b>אבל נשמות תנאים ואמוראים</b>: ראה גם לקמן מאמר ד\"ה הנה להבין המדרש והצרוע תקצ\"ט על יד הערה 102. מאמרי אדה\"ז תקס\"ו ע' רעח. מארז\"ל ע' רצא. אוה\"ת דברים ע' כג. וראה גם מאמרי אדה\"ז תקס\"ה ח\"א ס\"ע תז ואילך. מאמרי אדה\"א דברים ח\"א ע' עו. וש\"נ. תו\"ח נח קנח, סע\"ב. אוה\"ת נ\"ך כרך ג ע' א'רעא."],["241","28","<b>הנ\"ל. . כו'</b>: ב: הנק'. . כנ\"ל."],["242","29","<b>שבעת שרי פרס ומדי</b>: אסתר א, יד."],["243","30","<b>כו'</b>: ב: כי."],["244","31","<b>ומועדים </b>[ב: מועדים]<b> לשמחה</b>: נוסח תפילת העמידה וקידוש ליו\"ט."],["245","32","<b>פני האדון ה'</b>: משפטים כג, יז. תשא לד, כג."],["246","33","<b>ביו\"ט מאירים מוחין דאימא</b>: ראה פע\"ח שער מקרא קדש ש\"כ, פ\"א. לקו\"ת צו יא, ד. בחוקותי מז, ג. סה\"מ תרכ\"ז ע' תפט. וש\"נ. שע\"ת צח, ב בשם הע\"ח. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'מד. לקמן מאמר ד\"ה להבין שרש ענין פסח ומצה על יד הערה 220."],["247","34","<b>ושמחה הוא בבינה כמאמר אם הבנים שמחה</b>: תהלים קיג, ט. ראה מאמרי אדה\"א נ\"ך ע' מח. וש\"נ. תו\"ח וארא פה, ג. לקמן מאמר ד\"ה לה\"ע ההפרש בין שבת ליו\"ט תר\"ב על יד הערה 103. ד\"ה רפאיני הא' על יד הערה 45."],["248","35","<b>בשבת. . עונג</b>: ראה שו\"ע אדה\"ז הל' שבת רסרמ\"ב. שעה\"י קיג, א הערה 5."],["249","36","<b>בשבת הוא בחי' מוחין דאבא</b>: נסמן לעיל בהערה 33."],["250","37","<b>האצי'. . רה\"י</b>: ראה לקוטי הש\"ס להאריז\"ל ריש מס' שבת ד\"ה ארבע רשויות. מאמרי אדה\"ז תקס\"ח ח\"א ע' רכח. לקו\"ת במדבר טז, א."]]],[4801940264,"עולים למעלה באצי' בבחי'<sup data-n=\"251\">38</sup> ז' המדות דאצי' ומגביהים לכללות נש\"י שיתעלו למעלה באצי' במקום המלך עצמו ועי\"ז יוכלו לראות פני המלך עצמו גם בשבת כו' וד\"ל. וזהו ג\"כ מדריגות פנים חדשות (... כי אע\"פ שהוא איש פשוט מ\"מ בשעת מעשה מאיר בו שרש נשמתו שבאצי' שהוא רואה פני המלך בתמידות ומגביה עמו את החתן שיהי' בו כח ועוז לברך הוא או שלוחו<sup data-n=\"252\">39</sup> את הכלה ליתן בה כח ועוז לעלות ולהתייחד כנ\"ל וד\"ל. ..) שהוא במדריגות המדות דאצי' ועי\"ז נמשך ז' ברכות שהם כנגד ז' מדות דאצי' כמבוא' בזהר פ' תרומה דקמ\"ט ע\"ב<sup data-n=\"253\">40</sup> במאמ' הינוקא ברי' דרב ספרא כו' וד\"ל.",[["251","38","<b>בבחי'</b>: תוקן ע\"פ ב."],["252","39","<b>הוא או שלוחו</b>: ניתוסף ע\"פ ב."],["253","40","<b>דקמט ע\"ב</b>: ב: (דקס\"ט ע\"ב)."]]],[4801940079,"<b>הנחת ר\"ה — ואכלתם אכול — פ' בהר תקצ\"ט</b>\n<b>ואכלתם</b> אכול<sup data-n=\"254\">1</sup> ושבוע<sup data-n=\"255\">2</sup> והללתם את שם הוי' אלקיכם אשר עשה עמכם להפליא ולא יבושו עמי לעולם. להבין מהו ואכלתם אכול דמשמע שתאכלו דבר הנאכל כבר ואיך שייך לאכול דבר הנאכל. ילה\"ק מש\"א זה קרבן אהרן ובניו<sup data-n=\"256\">3</sup> ביום המשח אותו ואמר במדרש<sup data-n=\"257\">4</sup> הה\"ד<sup data-n=\"258\">5</sup> מהאוכל יצא<sup data-n=\"259\">6</sup> מאכל<sup data-n=\"260\">7</sup> והי' שמשון תמיה הלא<sup data-n=\"261\">8</sup> ארי אוכל כו' ואיך<sup data-n=\"262\">9</sup> יצא ממנו מאכל וכך אהרן אוכל קרבנות<sup data-n=\"263\">10</sup> ועכשיו יצא ממנו קרבן. ולכאורה אינו מובן ענין התמיה והדמיון דאהרן אוכל קרבנות לארי אוכל כו', הנה מ\"ש ארי אוכל קאי על בחי' ארי' דאכיל קרבנין<sup data-n=\"264\">11</sup> בבהמ\"ק שנק' אכילת מזבח.",[["254","1","<b>ואכלתם אכול</b>: הנחת ר\"ה מדרוש כ\"ק אדמו\"ר הצ\"צ.\nלמאמר זה ראה לקו\"ת צו ז, ד ואילך [פ\"ב — שזהו הוספת הצ\"צ על דרוש דכ\"ק אדה\"ז]. לקו\"ת נשא כח, ד. ולסיום המאמר (ד\"ה ומעתה) ראה לקו\"ת צו ז, א ואילך ובמקביליו בדרושי אדה\"ז נסמנו במ\"מ ללקו\"ת שם."],["255","2","<b>ואכלתם אכול ושבוע</b>: יואל ב, כו."],["256","3","<b>זה קרבן אהרן ובניו</b>: צו ו, יג [בדילוג]."],["257","4","<b>במדרש</b>: ויק\"ר פ\"ח, ב."],["258","5","<b>הה\"ד</b>: שם: זש\"ה. וכ\"ה בלקו\"ת כאן."],["259","6","<b>מהאוכל יצא מאכל</b>: ס' שופטים יד, יד. במדרש ובלקו\"ת הובא גם התחלת הכתוב ויאמר להם."],["260","7","<b>מאכל</b>: בלקו\"ת כאן ניתוסף: כו' — דילוג בלשון המדרש."],["261","8","<b>הלא</b>: במדרש שם: בלבו ואמר. ובלקו\"ת: בלבו."],["262","9","<b>ואיך</b>: שם: ועכשיו."],["263","10","<b>וכך. . קרבנות</b>: שם: כך. . כל הקרבנות."],["264","11","<b>ארי' דאכיל קרבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שער האמונה עט, ב הערה 13."]]],[4801940145,"<b>ולהבין</b> ענינו ילה\"ק ההפרש בין שרפים לאופנים כי הנה שרפים הם בבריאה<sup data-n=\"265\">12</sup>, וידוע דאימא עילאה מקננא בכורסיא<sup data-n=\"266\">13</sup> שהוא עולם הבריאה, וידוע דבינה הוא בחי' השגה לכן משיגים גילוי אא\"ס והגם דלית מח' והשגה תפיסא בי'<sup data-n=\"267\">14</sup> היינו במהו\"ע אבל השגתם הוא במציאותו איך שהוא קדוש ומובדל ואין ערוך לכל ההשתל' אליו ית' ומחמת השגה זאת בטלי' ממציאותם בתמידות ולכן או' ק' בתמידות (... כידוע שאו' ג\"פ ק' וכל פעם נמשך ד' שעות<sup data-n=\"268\">15</sup> כו'. ..) כי ביטול זה הוא בבחי' טבעי' ועצמי' בהם, והטעם להיותם ראשי' הבריאה מאין ליש (... כידוע בלה\"ק שם בריאה הוא מאין ליש<sup data-n=\"269\">16</sup> ושרפי' הם בבריאה כו'. ..) ולכן מאיר בהם הארת האין בבחי' טבעי' הגם שהמה נבראי' בבחי' יש מ\"מ קרובי' הם לבחי' האין כו', משא\"כ האופנים שמקבלי' התהוותם אחרי ג' צמצומי' ומסכי' שהוא מאצי' לבריאה ומבריאה ליצי' ומיצי' לעשי'<sup data-n=\"270\">17</sup> לכן אין להם השגה כלל אפי' במציאותם איך שאין ערוך אליו וכולא קמי' כלא<sup data-n=\"271\">18</sup> כו' רק בבחי' הודאה מרחוק ה' נראה להם<sup data-n=\"272\">19</sup>. אך כשמאי' לפרקים בהם ענין הקדושה דאא\"ס בבחי' השגה קצת מצד שמקבלי' מבחי' שרפי' כמאמ' ומקבלין דין מן דין<sup data-n=\"273\">20</sup> אזי מתפעלים ברעש [כו'] מצד ההתחדשו' להשיג בדבר שהי' מוסתר מהם מקודם מצד טבע בריאותם, וכידוע המשל לזה<sup data-n=\"274\">21</sup> מההפרש שבין בן כרך שרואה את המלך בתמידו' אינו מתפעל במורגש אבל בן כפר שרחוק מאד מהכרת רוממות המלך לכן כאשר רואה לפרקי' מתפעל מאד במורגש מצד ההתחדשות, וזהו ההפרש בין רעש לאש כי התפעלות האופנים נק' רעש והתפעלות השרפי' נק' אש (... [ב]בחי' שלהבת י\"ה<sup data-n=\"275\">22</sup> התפעלות בחשאי כו'. ..). אך יש יתרון בהתפעלות האופנים להיותו במורגש לכן הוא רעש<sup data-n=\"276\">23</sup> גדול [ב]יותר מ[התפעלות] השרפי', וסיבת הכח הגדול הוא מחמת ההתחדשות שנולדה מצד ההיפך המסתיר ולכן מעורר[י'] למעל' באורות [ד]תוהו ממקום יותר עליון מהתפעלות השרפים (... והטעם כי בהיפך המנגד יש חלקי' מעולם התוהו יותר ע' בב\"ז פ' שלח<sup data-n=\"277\">24</sup> כו'. ..), וכמו התפעלות הבע\"ת דמשכין לי'",[["265","12","<b>שרפים הם בבריאה</b>: ראה לקו\"ת להאריז\"ל ישעי' פ\"ו. ביאוה\"ז שבהערה 21. מאמרי אדה\"א דברים ח\"א ע' רסג. וש\"נ. שע\"ת סב, א הערה 10."],["266","13","<b>דאימא עילאה מקננא בכורסיא</b>: ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["267","14","<b>דלית מח' והשגה תפיסא בי'</b>: ראה ת\"ז בהקדמה יז, א."],["268","15","<b>ג\"פ ק'. . ד' שעות</b>: ישעי' ו, ג. ראה לקו\"ת שה\"ש כט, ב ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקע\"א ע' קפה. מאמרי אדה\"א נ\"ך ע' שלו. וש\"נ. קונטרסים ע' רמז."],["269","16","<b>בלה\"ק שם בריאה הוא מאין ליש</b>: ראה רמב\"ן בראשית א, א."],["270","17","<b>האופנים. . לעשי'</b>: ת\"ז ת\"ו כג, א. ראה לקו\"ת האזינו עז, ב: וכמ\"ש האריז\"ל — ראה ע\"ח שער פו\"ח דרוש טו. ביאוה\"ז שבהערה 21. מאמרי אדה\"א ויקרא ח\"ב ע' תתסג. וש\"נ. קונטרסים ע' תקלה. וש\"נ. ראה גם לקמן מאמר ד\"ה וספרתם תרי\"ב ע' רסז."],["271","18","<b>וכולא קמי' כלא</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה פ\"א (ז, רע\"א). מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["272","19","<b>מרחוק ה' נראה להם</b>: ע\"פ ירמי' לא, ב."],["273","20","<b>ומקבלין דין מן דין</b>: ת\"י לישעי' ו, ג."],["274","21","<b>המשל לזה</b>: ראה לקו\"ת נשא כח, ד. סה\"מ תרכ\"ט ע' רלז ואילך. וש\"נ. וראה גם ביאוה\"ז בשלח לט, ד. פלח הרמון יתרו ע' רמא."],["275","22","<b>שלהבת י\"ה</b>: שה\"ש ח, ו."],["276","23","<b>רעש</b>: ב: בכח."],["277","24","<b>בב\"ז פ' שלח</b>: צא, ד ואילך."]]],[4801940209,"בחילא יתיר<sup data-n=\"278\">25</sup> מצד\"ג (... והיינו כי אע\"פ שצ\"ג המה בבחי' קירוב יותר מצד המשכת אלקות שהמשיכו בנפשם כל ימיהם בתורתם ועבודתם משא\"כ בבע\"ת שאינו מאיר בהם כ\"כ גילוי אלקות אפי' אחר התשובה מצד העדר הכלים כידוע שנק' אביוני אדם<sup data-n=\"279\">26</sup>, אך זהו באור המאיר ע\"פ השתל' דעולם התיקון אבל אורות דתוהו שלמעל' מהשתל' מתעוררי' יותר בהזזה דבע\"ת ועקירת הרצון שלהם להיות[ם] מצד המנגד לכן הוא בכח גדול לעורר למעל' מהשתל' כו' ועיקר הטעם כנ\"ל בשם ב\"ז פ' שלח כו'. ..). וכ\"ה עד\"ז היתרון באופנים משרפי' שהתפעלותם הוא בחילא יתיר כו' וד\"ל.\n<b>והנה</b> השרפים ואופנים שניהם נתבררו כבר בתחילת ההשתל' משא\"כ עוה\"ז הגשמי מקבל משמרי<sup data-n=\"280\">28</sup> האופנים<sup data-n=\"281\">27</sup> וענין השמרי' הוא שלא נתברר[ו] עדיין רק נשאר לעשות לתקן ע\"פ מעש' התחתוני' וכמאמר אשר ברא אלקי' לעשות לתקן<sup data-n=\"282\">29</sup>, וע\"כ צ\"ל שהטוב שבנוגה שבעוה\"ז הגשמי שרשו ממקום עליון ביותר ולכן נפל למטה יותר<sup data-n=\"283\">30</sup> ובלתי אפשר לו להתברר ע\"פ הארה אלקי' שהאיר בתחי' ההשתל' ע\"פ ח\"ח<sup data-n=\"284\">31</sup> כו' רק מוכרח להתברר ע\"י אור אלקי יותר נעלה שמאיר מצד העלאת מ\"נ דמעשה\"ת דוקא. והנה זהו\"ע הקרבן שלוקח[ין] בהמה גשמי' שהי[א] מעורבת טו\"ר והחיות שבה הוא ממקום יותר נעלה אפי' מבחי' האופני' כנ\"ל וע\"י השריפה ע\"ג המזבח נדחה הפסולת והחיות שבה נכלל בפני אריה<sup data-n=\"285\">32</sup> דוקא, [והטעם וענין ההתכללות בפני ארי' דייקא] להיותו מלך בחיות<sup data-n=\"286\">33</sup> אפי' בחיות שבמרכבה עצמה שהם השרפי' דבריאה כידוע דפני ארי' להימין<sup data-n=\"287\">34</sup> וארי' אותיות ראיה<sup data-n=\"288\">35</sup> דחכ'<sup data-n=\"289\">36</sup> שהוא בחי' ראשי' הגילוי<sup data-n=\"290\">37</sup> בעולם הבריאה ולזאת נתעלה החיות דבהמה הגשמי' עד רום המעלות בשרש' היותר ראשון שהוא בחי' החכ' דבריאה להיות ג\"כ בבחי' ביטול",[["278","25","<b>דמשכין לי' בחילא יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. תו\"ח שמות ח\"א לז, א. וש\"נ. לקמן מאמר ד\"ה כי ביום הזה יכפר תקצ\"ח על יד הערה 84 ואילך."],["279","26","<b>בבע\"ת. . שנק' אביוני אדם</b>: ישעי' כט, יט. ראה מאמרי אדה\"א נ\"ך ע' נא ואילך. תו\"ח שמות ח\"א ע' ט. וש\"נ."],["280","28","<b>משמרי האופנים</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ט."],["281","27","<b>עוה\"ז. . משמרי האופנים</b>: ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ר\"ע קכא. תו\"ח נח נט, ד ובהערה 57. בא ח\"א קכו, ד. משפטים ח\"ב רפג, ג."],["282","29","<b>אשר. . לעשות לתקן</b>: בראשית ב, ג. ראה ב\"ר פי\"א, ו וברש\"י שם. מאמרי אדה\"א ויקרא ח\"ב ע' תתסח. וש\"נ. תו\"ח בשלח ח\"א קלח, ד. וש\"נ. סה\"מ תרכ\"ח ע' א."],["283","30","<b>שרשו. . למטה יותר</b>: ראה ש\"א שער הפורים נח, א. סה, א. לקמן מאמר ד\"ה להבין כו' פסח ומצה ובהערה 133."],["284","31","<b>ח\"ח</b>: חפץ חסד."],["285","32","<b>בהמה. . נכלל בפני אריה</b>: ראה גם לעיל מאמר ד\"ה אדם כי יקריב הב' על יד הערה 92. סה\"מ תרל\"ח ע' לה."],["286","33","<b>ארי'. . מלך בחיות</b>: חגיגה יג, ב."],["287","34","<b>דפני ארי' להימין</b>: יחזקאל א, י."],["288","35","<b>וארי' אותיות ראיה</b>: ראה ת\"ז ת\"ע (קכב, א). הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'ל."],["289","36","<b>ראי' דחכ'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"כ מערכת ראי'. מאמרי אדה\"א הנחות תקע\"ז ע' כז. וש\"נ. תו\"ח שמות ח\"א כז, ג. וש\"נ."],["290","37","<b>דחכ'. . ראשי' הגילוי</b>: ראה תניא פל\"ה בהגהה. לקמן ע' שצז ואילך. סה\"מ תרל\"ח ע' נ ובהערה 260."]]],[4801940265,"ע\"ד ביטול דחכ' הנ\"ל שבפני' ארי', אך אע\"פ שזה נחשב בחי' עלי' לחיות הבהמה מ\"מ אחר ההתכללות בפני ארי' הנ\"ל נתעלה בחי' ארי' הנ\"ל ע\"י הקרבן (... וכדוגמת המאכל שאוכל האדם שמתחילה נחשב עלי' לגבי המאכל במה שמתעל' מבחי' דצ\"ח לבחי' מדבר להיות דם כדם האדם ובשר כבשרו אך אח\"כ מוסיף כח וחיות באדם והטעם להיותו גבוה בשרשו יותר מנפש האדם שהוא בחי' התוהו שקדם לתיקון כו'. ..), וענין עלייתו הוא מה שניתוסף בו כח ועוז ע\"י חיות הקרבן הנכלל בו להיות נושאות את הכסא ומנושאות עם הכסא<sup data-n=\"291\">38</sup> והיינו שמתחלה נתעלה בבחי' ביטול בבחי' הכסא ואדם שעל הכסא שזהו בחי' מנושאות ואח\"כ ע\"י ביטולם בבחי' הכסא מתנשא הכסא ואדם שעה\"כ לקבל ממקום יותר נעלה שלא הי' יכול [להגיע] מצד עצמו (... והטעם ג\"כ להיותם בחי' חיות ובהמות לגבי אדם שעהכ\"ס ושרשם בתוהו יותר נעלה ולכן ביכולתם לנשאות את הכסא כו' וכידוע במרכבה לגבי הרוכב כו'. ..). והנה אחר שנושאות את הכסא בבחי' העלאה אז נתוסף אור וחיות באדם שעהכ\"ס וממנו לכל העולמות וזהו מה דאתזני כל עלמין ע\"י הקרבן<sup data-n=\"292\">39</sup>.\n<b>אך</b> כל העלי' בפני ארי' להיות מנושאות הוא רק במקורו שנק'<sup data-n=\"293\">40</sup> מקור העולמות [בלבד] (... שהוא בחי' מדות שבמל' בלבד או [יו\"ד] כלי' האמצעי' וחיצוני' [ד]מל' כו'. ..) ולזא[ת] גם ההמשכה שנעשה מבחי' [ההעלאה] אינ[ה] רק בחיצוני' ממקור העולמות וזהו אכילת מזבח שהוא מה שנשרף ע\"ג המזבח בארי' דאכיל קרבנין הנ\"ל, אבל יש עוד בחי' אכילת אדם<sup data-n=\"294\">41</sup> (... שהוא מה ש[ה]כהנים אוכלי'<sup data-n=\"295\">42</sup> בשר כו' שהוא בירור יותר פנימי וגורם המשכה פנימי' יותר. ..). כי הנה ידוע שבד\"כ בחי' אדם מדבר הוא באצי'<sup data-n=\"296\">43</sup> כי אד\"ם הוא בחכ'<sup data-n=\"297\">44</sup> כח מ\"ה<sup data-n=\"298\">45</sup> וידוע דבחי' החכ' מאיר בכל עולם דאצי'<sup data-n=\"299\">46</sup> ואין אא\"ס שורה אלא בחכ'<sup data-n=\"300\">47</sup> לכן מאיר אא\"ס בכל עולם האצי' שהו\"ע תפיסת המהות וכידוע דבאצי' איהו וחיוהי וגרמוהי חד<sup data-n=\"301\">48</sup> משא\"כ בבריאה אינו רק",[["291","38","<b>נושאות. . ומנושאות עם הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג. מאמרי אדה\"ז תקס\"ד ע' כג. שה\"א ע, א. תו\"ח פקודי ח\"ב תנט, א. וש\"נ."],["292","39","<b>דאתזני כל עלמין ע\"י הקרבן</b>: ראה זהר תזריע מח, א."],["293","40","<b>שנק'</b>: ב: ליתא."],["294","41","<b>אכילת מזבח. . אכילת אדם</b>: ראה (בנוסף ללקו\"ת כאן ז, סע\"ד ואילך) מאמרי אדה\"ז תקס\"ה ח\"א ע' קסג ואילך. סה\"מ תרכ\"ז ע' שלז. תרכ\"ט ע' רמט ואילך. וש\"נ."],["295","42","<b>ש[ה]כהנים אוכלי'</b>: פסחים נט, ב. רמב\"ם הל' מעשה הקרבנות פ\"י, ה\"א. ראה גם מאמרי אדה\"ז וסה\"מ שבהערה שלפנ\"ז ובהנסמן לשם. שע\"ת מד, א. מאמרי אדה\"א במדבר ח\"ג ע' תתקנא. וש\"נ."],["296","43","<b>מדבר הוא באצי'</b>: ראה סה\"ש ה'תשנ\"ב ע' 139 הערה 54. תו\"ח משפטים ח\"ב רצט, א. וש\"נ."],["297","44","<b>אד\"ם הוא בחכ'</b>: ראה גם לקמן מאמר ד\"ה להבין כו' פסח ומצה על יד הערה 146."],["298","45","<b>בחכ' כח מ\"ה</b>: זהר רע\"מ צו כח, א. לד, א."],["299","46","<b>החכ' מאיר בכל עולם דאצי'</b>: בלקו\"ת תזריע כג, ב מציין לע\"ח שמ\"ז, פ\"ג [ובדפו\"א פ\"ב]. ראה גם הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקי."],["300","47","<b>אא\"ס. . בחכ'</b>: ראה תניא פי\"ח (ובמ\"מ הגהות והע\"ק שם). פל\"ה בהג\"ה (ובמ\"מ הגהות והע\"ק שם). לקו\"ת במדבר יד, ב [ושם מציין: ”בע\"ח שער מ\"ז פ\"ג\" ולפנינו הוא פ\"ב ”ושער ב' במה\"ב פ\"א פ\"ג\" ולפנינו הוא בשער סדר אצי' ש\"ג]. תו\"ח שמות ח\"א ז, ד הערה 333."],["301","48","<b>איהו וחיוהי וגרמוהי חד</b>: ת\"ז בהקדמה ג, ב."]]],[4801940317,"במדר[יגת ח]י<sup data-n=\"302\">49</sup> ואינו מאיר רק מבחי' בינה<sup data-n=\"303\">50</sup>. וע\"ד העבודה הוא כמו ההפרש בין בחי' אה' לבחי' ביטול כמו נשמת אברהם אוהבי<sup data-n=\"304\">52</sup> ששרשו בבריאה<sup data-n=\"305\">51</sup> ולכן נא' ושמי הוי' שהוא בחי' כלי' דאצי' לא נודעתי<sup data-n=\"306\">53</sup> כו' משא\"כ במשה ואהרן נא' ונחנו מה<sup data-n=\"307\">54</sup> בחי' ביטול בתכלי' מצד שהאיר בהם אור האצי' כו' וד\"ל [כנ\"ל דאימא מקננא כו' לכן אינו מאיר ונתפס בעולם הבריאה מהות אא\"ס רק מציאותו בלבד כו' וד\"ל]. ולכן אחר שנתברר חיות הקרבן ונכלל בפני ארי' הנ\"ל צריך להתעלות ולהתברר בבירור אחר בירור ליכלל באצי' שהו\"ע לאשתאבא בגופא דמלכא<sup data-n=\"308\">55</sup> בכדי לגרום המשכה פנימי' יותר מעולם האצי' (... שיאיר גם בבי\"ע אור האצי' בחי' ביטול דחכ' כח מ\"ה כו'. ..) ולזאת מוכרח להיות בירור ועלי' בפני ארי' עצמו לאשתאבא בגופא [דמלכא] כו' ואז יתעלה גם חיות הקרבן ואז מהאוכל נעשה מאכל כי אע\"פ שבבריאה הוא בגדר אוכל ומברר (... להיות מאיר בו מחכ' דבריאה פני אדם לארבעתן<sup data-n=\"309\">56</sup> כו'. ..) אבל לגבי אצי' בחי' אדם מדבר האמיתי אינו רק בגדר חי וצריך להתברר ע\"י [ה]מאכל המתברר ע\"י האדם למטה.\n<b>והנה</b> זהו\"ע דשמשון שמגווית הארי' רדה הדבש<sup data-n=\"310\">57</sup> נמצא שנתהפך גווית הארי' לדבש ואח\"כ אכל הדבש ולמעל' היינו בחי' אכלתי יערי עם דבשי<sup data-n=\"311\">58</sup>, כי הנה ידוע דיערי הם בחי' המלאכי'<sup data-n=\"312\">59</sup> להיותם שלוחי ההשפעה וע\"י משתלשל ההשפעה מעילה לעלול<sup data-n=\"313\">60</sup> מבריאה ליצירה ומיצירה לעשי' עד עוה\"ז הגשמי שמזה נמשך בעוה\"ז הגשמי הן השפעת גשמי' כמו מזון ומאכל הן השפעת רוחני' כמו השפעת שכל<sup data-n=\"314\">61</sup> כו' וכידוע דאין לך עשב<sup data-n=\"315\">62</sup> בפרט שאין לו מזל מלמעל' וגבוה מעל גבוה שומר<sup data-n=\"316\">63</sup> כו' עד שרשו בשרפי' דבריאה ולכן נק' המלאכי' בשם יערי שהוא בחי' צומח ע\"ש ההשפעה הנמשך מהם (... וכידוע בענין לכולם בשם יקרא<sup data-n=\"317\">64</sup> בא\"ב בפתח השער<sup data-n=\"318\">65</sup>. ..). והנה בחי' יערי הנ\"ל שהם בחי' המלאכי' נכללי' בבחי' דבשי שהם בחי'",[["302","49","<b>בבריאה. . ח]י</b>: נסמן לעיל בהערה 43."],["303","50","<b>בבריאה. . בינה</b>: נסמן לעיל בהערה 46."],["304","52","<b>אברהם אוהבי</b>: ישעי' מא, ח."],["305","51","<b>נשמת אברהם. . בבריאה</b>: ראה אגה\"ק סט\"ו. תו\"ח וארא ח\"א סב, א. וש\"נ."],["306","53","<b>ושמי הוי'. . לא נודעתי</b>: וארא ו, ג."],["307","54","<b>ונחנו מה</b>: בשלח טז, ז. ח. ראה גם לעיל מאמר ד\"ה אדם כי יקריב הא' על יד הערה 18. ד\"ה אדם כי יקריב הב' על יד הערה 28. לקמן ד\"ה אם בחוקותי הא' על יד הערה 58. מאמרי אדה\"א בראשית ע' כב. וש\"נ. תו\"ח שמות ח\"א מג, א. וש\"נ."],["308","55","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' מה. תו\"ח בראשית מ, ב הערה 25."],["309","56","<b>פני אדם לארבעתן</b>: ראה גם לקמן מאמר ד\"ה וספרתם הד' ובהערה 33."],["310","57","<b>שמגווית הארי' רדה הדבש</b>: ס' שופטים יד, ט."],["311","58","<b>אכלתי יערי עם דבשי</b>: שה\"ש ה, א."],["312","59","<b>דיערי. . המלאכי'</b>: ראה זהר פינחס רכו, סע\"א ואילך. מאמרי אדה\"א ויקרא ח\"א ע' קלח. וש\"נ. הנחות תקע\"ז ע' שלז. וש\"נ. אמרי בינה פתח השער יא, ד."],["313","60","<b>מעילה לעלול</b>: בלקו\"ת ברכה צה, ב: בספרים. ראה גם רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו."],["314","61","<b>השפעת שכל</b>: ב: השגת השכל."],["315","62","<b>דאין לך עשב</b>: ראה ב\"ר פ\"י, ו. מאמרי אדה\"א דברים ח\"ג ע' תתמח. וש\"נ. שם ע' תתעו ואילך. שער האמונה ע' נג. אוה\"ת וארא כרך ח ע' ב'תתפג."],["316","63","<b>וגבוה מעל גבוה שומר</b>: קהלת ה, ז."],["317","64","<b>לכולם בשם יקרא</b>: ישעי' מ, כו."],["318","65","<b>בא\"ב בפתח השער</b>: ראה שם י, ג. יא, ב."]]],[4801940366,"הנשמות<sup data-n=\"319\">66</sup> דבריאה (... שמקבלי' מחב\"ד דמל' או מבחי' י' כלי' הפנימי'. ..) ונק' הנשמות בשם דבשי להיות עבודתם בבחי' אה' בתענוגי' להתענג על הוי' במתיקות ותענוג כמאמר נהנין מזיו<sup data-n=\"320\">67</sup> כו', משא\"כ המלאכי' בד\"כ עבודתם הוא בבחי' יראה וביטול (... להיותם מקבלים מחיצוני' הכלים א\"א להם לקבל גילוי אוא\"ס בבחי' תענוג כו' רק בבחי' ביטול מהותם כו'. ..) ולכן המלאכי' נכללי' בנשמות ומתעלי' ע\"י, ואח\"כ המלאכי' ונשמות נעשי' מאכל ומתבררי' ועולי' למעל' באצי' לאשתאבא בגופא דמלכא כו' וזהו\"ע אכלתי יערי עם דבשי כו' (... וענין ההתכללות דמלאכי' בנשמות הוא ע\"ד דוגמא באדה\"ת כאשר המאכל מתברר בו<sup data-n=\"321\">68</sup> ונכלל בו בנפשו הטבעי' ומוסיף בו כח ועוז אך אח\"כ כשלומד ומתפלל בכח האכילה נכלל חיות המאכל בנשמה האלקי'<sup data-n=\"322\">69</sup> כו'. ..). וזהו\"ע עובדא דשמשון שמתחילה נתהווה מגווית הארי דבש שהוא בחי' התכללות דמלאכי' בנשמות דבריאה ואח\"כ אכל אותו<sup data-n=\"323\">70</sup> שזהו\"ע הבירור והעלי' מבריאה לאצי' (... מדצ\"ח למדבר כו'. ..) מביטול דיחו\"ת לביטול דיחו\"ע, וזהו\"ע אכילת שמשון שהוא בחי' יחו\"ע כמארז\"ל שמשון נק' על שמו של הקב\"ה<sup data-n=\"324\">71</sup> כמ\"ש כי שמש ומגן הוי' [אלקי']<sup data-n=\"325\">72</sup> וידוע דהוי' הוא בחי' יחו\"ע ואלקי'<sup data-n=\"326\">73</sup> יחו\"ת<sup data-n=\"327\">74</sup> כו'. ועד\"ז הי' ג\"כ אכילת אהרן שנק' אכילת אדם כי כשהי' הכהן אוכל הבשר פעל למע' אכילת אדה\"ע לברר הבירורי' דבי\"ע שנכללו בפני ארי' וגם פני ארי' עצמו עם הנשמות דבי\"ע שיהיו נכללי' כולם באדה\"ע דאצי' שהו\"ע לאשתאבא כו' וד\"ל (... ואפשר לחלק בין אכילת שמשון לאכילת אהרן כי שמשון אפשר שהוא הארת יסוד אבא ביסוד ז\"א שמאיר ג\"כ בבי\"ע כידוע בב\"ז<sup data-n=\"328\">75</sup> במא' מחצית השקל ולכן נק' שמשון בתוס' ו' נ'<sup data-n=\"329\">77</sup> להקטנת הענין<sup data-n=\"330\">76</sup> כידוע לבעלי הדקדוק ונמצא שהוא בחי' סובב ומקיף דבי\"ע משא\"כ אהרן הוא הארת יסו\"א בגופא דז\"א וע\"י אכילת שמשון נכלל ביסוד ז\"א כו' אבל ע\"י אכילת אהרן מתעלה ונכלל בגופא דז\"א כו' וד\"ל. ..).\n<b>והנה</b> כמו שמבואר למעלה בענין אכילת מזבח שמוסיף כח ועוז בפני ארי' כו' כן אכילת אדם מוסיף כח ועוז באדה\"ע דאצי' מבחי' עצמות אוא\"ס דלאו מכל אילין מדות<sup data-n=\"331\">78</sup> איהו כלל וזהו\"ע ריח ניחוח להוי'<sup data-n=\"332\">79</sup> דאצי' עצמו כו'. והנה אחר שניתוסף כח ועוז באדם דאצי' מצד הבירורי' של הקרבן אז נמשך המשכה פנימי' מאדם דאצי' לבי\"ע להיות מאיר בחי' הביטול דחכ' כח מה גם בבי\"ע כו' וד\"ל.",[["319","66","<b>דבשי. . הנשמות</b>: ראה בהדרושים שבהערה 59."],["320","67","<b>נהנין מזיו</b>: ראה ברכות יז, א."],["321","68","<b>בו</b>: ב: ליתא."],["322","69","<b>בנשמה האלקי'</b>: שם: בנשמת האדם בנה\"א."],["323","70","<b>ואח\"כ אכל אותו</b>: ס' שופטים יד, ט."],["324","71","<b>שמשון. . שמו של הקב\"ה</b>: סוטה י, א."],["325","72","<b>כי שמש ומגן הוי' </b>[אלקי']: תהלים פד, יב."],["326","73","<b>דהוי'. . יחו\"ע ואלקי' יחו\"ת</b>: ראה תו\"א תצוה פא, ד. ויקהל קטו, ב. לקו\"ת ראה כג, ד."],["327","74","<b>יחו\"ע. . יחו\"ת</b>: זהר בהקדמה יב, א."],["328","75","<b>יסוד אבא ביסוד ז\"א. . בב\"ז</b>: תשא נד, ד ואילך."],["329","77","<b>נ'</b>: ב: ליתא."],["330","76","<b>שמשון בתוס' ו' נ' להקטנת הענין</b>: ראה גם של\"ה מסכת חולין קך, א. תו\"א יתרו סז, ד־ תו\"ח שם ח\"ב רנה, ד: מאותיות האמנתי\"ו שהן להקטין הענין."],["331","78","<b>דלאו מכל אילין </b>[ב: אינון]<b> מדות</b>: ראה ת\"ז בהקדמה יז, ב."],["332","79","<b>ריח ניחוח להוי'</b>: ויקרא א, ט."]]],[4801940412,"<b>והנה</b> ההפרש בין אהרן למשה כי גם שניהם בבחי' ונחנו מה דאצי' אבל מ\"מ יש הפרש בין חכ' המאיר במדות דאצי'<sup data-n=\"333\">80</sup> ובין ח\"ע [מ]אוא\"ס עצמו וכדוגמא באדה\"ת אין ערוך לשכל המלובש במדות לגבי עצם השכל, והנה אהרן אותיו' נראה<sup data-n=\"334\">81</sup> שרשו בבחי' ראי' דחכ' המלובש במדות כידוע דאהרן א'<sup data-n=\"335\">82</sup> ה\"ר<sup data-n=\"336\">83</sup> שהוא בחי' המדות<sup data-n=\"337\">84</sup> משא\"כ משה הי' בבחי' חכ' בעצם כו'. והנה כשנתכהן אהרן לכה\"ג וכן כל כהן כשנתעלה להיות כה\"ג אז עולה לקבל ביטול דחכ' בעצם שלמעלה מחכ' המלובש במדות וזהו מה שמושחין אותו בשמן המשחה<sup data-n=\"338\">85</sup> כידוע דשמן משחת קדש הוא בחכ'<sup data-n=\"339\">86</sup> וריח הבשמי' שבו הוא בחי' מקיפי' דכתר<sup data-n=\"340\">87</sup> המאיר בחכ' וכ\"ז האיר בכה\"ג לזאת ביום המשח אותו הוא מוכרח להתברר ולהתעלות לבחי' ביטול דחכ' בעצם ולזאת מוכרח להקריב קרבן ולהתברר ע\"י כו'.\n<b>והנה</b> זהו\"ע התמיה דשמשון ארי' אוכל כו' יעשה מאכל פי' כי כל אוכל ומברר מוכרח להיות מבורר<sup data-n=\"341\">88</sup> בתכלי' וכ\"ז שלא נתברר בתכלי' א\"א לו<sup data-n=\"342\">89</sup> לברר אחרי', ולזאת הטעם לא חל קדושת א\"י על סוריא<sup data-n=\"343\">90</sup> מטעם דסמוך לפלטין שלך לא כבשת<sup data-n=\"344\">91</sup> כו', וכן אסור לאכול קודם התפילה<sup data-n=\"345\">92</sup> מצד שלא נתברר נפשו הטבעי' חלק השייך לאותו יום<sup data-n=\"346\">93</sup> כו' לכן א\"א לו לברר המאכל, ולכן כיון שארי' אוכל קרבנות מוכרח לומר שהוא מבורר בתכלית וא\"כ איך יעשה מאכל שזה מורה שצריך להתברר עדיין ואינו מבורר בתכלית, אך התירוץ הוא כי במקומו הוא מבורר בתכלי' עד שיוכל לקבל גילוי אא\"ס המאיר לפ\"ע מקומו, אכן כשמתעלה למקום יותר עליון ששם מאיר אא\"ס בעילוי יותר הוא נחשב לבחי' פסולת לפ\"ע הגילוי ההוא ולכן הוא מוכרח להתברר בירור אחר בירור, ולכן מהאוכל יצא מאכל דארי' דאכיל קרבנין שהוא בחי' מברר בעולם הבריאה כשמתעלה למדות שבאצי'",[["333","80","<b>דאצי'</b>: ב: ליתא."],["334","81","<b>אהרן אותיו' נראה</b>: ראה זהר אמור קג, א ובמק\"מ ובהרמ\"ז שם. מאמרי אדה\"א ויקרא ח\"ב ע' תשסז. וש\"נ. שמות ח\"ב ע' שמ. וש\"נ."],["335","82","<b>דאהרן א' ה\"ר</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' קכו ואילך."],["336","83","<b>דאהרן א' ה\"ר</b>: ב: דאהרן אה\"ר — ראה תו\"א תצוה פב, א-ב."],["337","84","<b>ה\"ר שהוא בחי' המדות</b>: ראה זהר (סבא) משפטים קט, ב ובמפרשים שם. תו\"ח שמות ח\"א יד, ד הערה 642."],["338","85","<b>כה\"ג. . שמושחין אותו בשמן המשחה</b>: צו ו, טו. הוריות יא, ב. רמב\"ם הל' כלי המקדש פ\"א, ה\"ז."],["339","86","<b>דשמן משחת קדש הוא בחכ'</b>: תשא ל, כה. לא. ראה גם ביאוה\"ז שמיני סד, ג. ש\"א כד, ב ובהערה 20. תו\"ח בשלח ח\"א ריב, א."],["340","87","<b>וריח. . דכתר</b>: ראה גם סידור שער התפלה כח, ג."],["341","88","<b>כל אוכל ומברר מוכרח להיות מבורר</b>: ראה (בנוסף ללקו\"ת כאן) לקמן סוד\"ה וספרתם תקצ\"ח. וש\"נ."],["342","89","<b>לו</b>: ב: ליתא."],["343","90","<b>לא חל קדושת א\"י על סוריא</b>: ראה רמב\"ם הל' תרומות פ\"א, ה\"ג."],["344","91","<b>דסמוך לפלטין שלך לא כבשת</b>: ספרי ס\"פ עקב. ירושלמי חלה פ\"א, ה\"ב."],["345","92","<b>אסור לאכול קודם התפילה</b>: ראה ברכות י, ב. שו\"ע אדה\"ז הל' תפלה ספ\"ט, ס\"ה. לקו\"ת כאן ח, א. נשא כו, ג. בלק עב, א. וראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשנו ואילך. וש\"נ. שמות ח\"א ס\"ע קפב ואילך. וש\"נ. סה\"מ תרל\"ח ע' ריב. לקמן מאמר ד\"ה כי תבואו וכו' ושבתה תר\"ט על יד הערה 115."],["346","93","<b>שלא נתברר. . חלק השייך לאותו יום</b>: ראה גם תו\"ח בא ח\"א צג, א. וש\"נ."]]],[4801940454,"לאשתאבא בגופא דמלכא עם נשמות דבריאה (... ע\"י מיכאל כה\"ר<sup data-n=\"347\">94</sup> דמקריב נשמות<sup data-n=\"348\">95</sup> כו'. ..) מוכרח להיות מאכל להתברר בירור אחר בירור. וכן עד\"ז הוא בחי' אהרן ששרשו יותר גבוה מפני ארי' להיות[ו ב]חכ' שבחסד דאצי' והוא מבורר שם בתכלית ולכן אוכל קרבנות בבחי' אכילת אדם כנ\"ל אך כאשר עולה לקבל [בחי'] שמן משחת קדש דחכ' מוכרח להתברר בירור אחר בירור ולכן אע\"פ שאוכל קרבנות מוכרח להקריב קרבן. והנה גם זה הבירור דאהרן<sup data-n=\"349\">96</sup> להתעלות לשמן משחת קדש הוא ג\"כ מדצ\"ח למדבר כידוע דיש בי\"ע גם באצי'<sup data-n=\"350\">97</sup> שהוא בחי' בינה מדות ומל' שהם בחי' דצ\"ח [דאצי'] ועלייתם לבחי' מדבר [דאצי' שב]אצי' בחי' שמן הנ\"ל כו', וזהו ביום המשח אותו דהול\"ל מיום המשח אותו כיון שא' אח\"כ מנחה תמיד, אך הענין הוא דיום הוא מל' אור כמ\"ש ויקרא אלקי' לאור יום<sup data-n=\"351\">98</sup> וכן מ\"ש לא יהי' לך השמש לאור יומם<sup data-n=\"352\">99</sup> כ\"א ה' יהי' לך לאור עולם ולכן א' זה קרבן פי'<sup data-n=\"353\">100</sup> שצריך [לו] להקריב בעת הגילוי בהמשח אותו מנחה תמיד כי בלתי הקרבן א\"א לקבל זה הגילוי [כו'] וד\"ל.\n<b>ומעתה</b> יובן ג\"כ ענין [ד]ואכלתם אכול להיות כי הנשמות היותר גבוהות דעכשיו כמו אפי' נשמת משה מקבל מבחי' ממכ\"ע מבחי' הקו\"ח ולעתיד יתגלו נשמות חדשות<sup data-n=\"354\">101</sup> מבחי' סוכ\"ע עיגול שלפני הקו ולכן יצטרכו נשמות דעכשיו להתברר ע\"י נשמות החדשות כי<sup data-n=\"355\">102</sup> כמאכל המתברר ע\"י האדם, ונמצא שגם שעכשיו הם מבוררי' בתכלית לגבי גילוי אא\"ס המאיר עכשיו מבחי' ממכ\"ע ולכן הם מבררי' אחרי' אבל לעתיד לגבי גילוי החדש דסוכ\"ע יצטרכו להתברר עוד הפעם. וזהו ג\"כ ענין הסעודה דלויתן ושור הבר<sup data-n=\"356\">103</sup> שהם נשמות דעכשיו מבחי' עדאתכ\"ס ועדאת\"ג ולעתיד יהיו בבחי' מאכל לצדיקים שהם נשמות החדשות שיתגלו לעתיד כו'. וזהו ג\"כ ענין צדיקים יושבין שזהו הנשמות דעכשיו ועטרותיהן בראשיהן<sup data-n=\"357\">104</sup> שהוא בחי' נשמות החדשות [ש]מבחי' סוכ\"ע שיתגלה בהם ונק' עטרה כו' (... אך הסעודה הוא",[["347","94","<b>מיכאל כה\"ר</b>: ראה זהר ס\"ת לך פ, סע\"א ואילך. הנסמן במאמרי אדה\"א בראשית ע' נו."],["348","95","<b>מיכאל. . דמקריב נשמות</b>: ראה חגיגה יב, ב כגי' הע\"י. תוד\"ה ומיכאל מנחות קי, א. מאמרי אדה\"א ויקרא ח\"א ע' א. וש\"נ. תו\"ח שמות ח\"א ה, א. וש\"נ. מאמר ד\"ה כמים הפנים תר\"ם בתחלתו."],["349","96","<b>דאהרן</b>: ב: דאצי'."],["350","97","<b>דיש בי\"ע גם באצי'</b>: ראה ע\"ח שער כללות אבי\"ע שמ\"ב, פ\"ד. וראה גם לקמן ביאור מאמר ד\"ה שבת שבתון ובהערה 38."],["351","98","<b>ויקרא אלקי' לאור יום</b>: בראשית א, ה."],["352","99","<b>לא יהי' לך השמש לאור יומם</b>: ישעי' ס, יט [ושם: לך עוד השמש. . והי' לך ה' לאור עולם]"],["353","100","<b>פי'</b>: ב: כו'."],["354","101","<b>נשמות חדשות</b>: בלקו\"ת כאן מציין הצ\"צ: ועיין מענין הנשמות החדשות שיתגלו לעתיד בספר הגלגולים פ\"ז. וקרוב לסופו בד\"ה ענין נשמות חדשות [גלגולים לקוטים ע, ב]. ובמ\"ח מסכת השגת הנשמות [פ\"א] ובהרמ\"ז ר\"פ תולדות גבי ועטרותיהם בראשיהם [קלד, ב ד\"ה יתקיימו]. וראה גם תו\"ח ויקהל ח\"ב תכט, ב. וש\"נ. וראה עוד בענין נשמות חדשות לקמן מאמר ד\"ה אם בחוקותי הא' על יד הערה 121. ד\"ה אם בחוקותי תר\"י על יד הערה 100."],["355","102","<b>כי</b>: ב: ליתא."],["356","103","<b>הסעודה דלויתן ושור הבר</b>: ראה ב\"ב עד, ב. ויק\"ר פי\"ג, ג. סה\"מ תרל\"ח ע' שצח. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'קיח. תו\"ח שמות ח\"א ו, ד הערה 293."],["357","104","<b>צדיקים יושבין. . ועטרותיהן בראשיהן</b>: ראה ברכות יז, א."]]],[4801940491,"עלי' דממלא בסובב ובחי' עטרותיהן בראשיהן הוא בחי' ההמשכה דסובב בממלא כו' וד\"ל. ..). וזהו והללתם את שם ה' אלקיכם אשר עשה עמכם להפליא היינו שיתגלה בהם בחי' פלא דסוכ\"ע כו' (... ושם ה' אלקיכם אפשר שזהו שם הוי' שבעצמות שרש נש\"י שהוא למעל' מסובב וממלא לכן ביכולתו לעשות הפלא היינו לתקנו שיבוא לידי גילוי כו' וד\"ל. ..), והנה ע\"ז א' ולא יבושו עמי לעולם כי עכשיו הכלה הופכת פניה<sup data-n=\"358\">105</sup> וכמא' הירושלמי מאן דאכיל דלאו דידי' בהית מסתכלא בי'<sup data-n=\"359\">106</sup>, ולכן עכשיו המקבל דמקור נש\"י לית לי' מגרמי' כלום רק מה שמקבל מלמעלה לכן הקבלה הוא בבחי' ביטול בחשאי שהו\"ע הבושת ביטול והפשט' המהות מכל וכל, משא\"כ לעתיד שתתעלה מקור נש\"י להיות בבחי' אחע\"ב<sup data-n=\"360\">107</sup> להשפיע מעצמות אא\"ס לבחי' י\"ס דאצי' משפיע דעכשיו להיות כי המה יהי' למעלה במדר[יגה] גבוה מאד וכמא' עתידי' צדיקי'<sup data-n=\"361\">108</sup> שיאמרו לפניהם ק[דוש] כו' לזאת יקבלו גילוי אא\"ס במורגש שלהם [כו'] (... כי המורגש יהי' מזוכך מאד [ו]נקי מתערובת פסולת שהוא בחי' הפירוד. ..) לזאת לא יבושו כו' כי לא יצטרכו לבחי' הפשט[ת] המהות רק שעצם מהותם יהי' [בחי'] כלי לקבל גילוי אלקות במורגש כו' וזהו\"ע קול כלה<sup data-n=\"362\">109</sup> כו' וד\"ל.",[["358","105","<b>הכלה הופכת פניה</b>: בשע\"ת קא, ב בשם הזהר. ובלקו\"ת כאן: כמ\"ש במשנה ספ\"ז דפסחים, ראה שם פו, א."],["359","106","<b>מאן דאכיל דלאו דידי' בהית מסתכלא בי'</b>: במאמרי אדה\"א דרושי חתונה ח\"ב ע' תרמז מביאו בשם הזהר. ובלקו\"ת כאן מירושלמי פ\"ק דערלה ראה שם ה\"ג."],["360","107","<b>אחע\"ב</b>: משלי יב, ד."],["361","108","<b>עתידי' צדיקי'</b>: ב\"ב עה, ב. ראה גם לקמן ע' שטז. וש\"נ."],["362","109","<b>קול כלה</b>: סדר ברכת נשואין. ראה סידור ברכת נשואין קלט, ב."]]],[4801940080,"<b>פסח</b>\n<b>מה</b> נשתנה<sup data-n=\"363\">1</sup> הלילה הזה מכל הלילות<sup data-n=\"364\">2</sup>. הנה להבין למה הקשה על הלילה מכל הלילות דוקא, הלא באמת ליל פסח משונה גם מכל הימים שגם בהן אין מטבילין כו', וגם אין חובה לאכול מצה ומרור ולא בהסיבה. אך הענין יובן ע\"פ מה ששמעתי מאדמו\"ר שליט\"א<sup data-n=\"365\">3</sup> שיש ב' מדריגו' מדת לילה ומדת יום, בחי' יעקב וישראל, בחי' תו' ותפלה. ובאה\"ע ע\"פ מ\"ש אם תעירו<sup data-n=\"366\">4</sup> כו' את האה' עד שתחפץ שעת לכל חפץ היינו התעוררו' מדת האה' הוא ביום בזמן ק\"ש ותפלה דייקא, וענין התעוררו' הוא כמשל אדם הישן שנסתלקו כל הכחות הפנימי' שכל ומדות לעצמית הנפש ולא נשאר רק כח המדמה שיכול לדמות ב' הפכים כא', כך בכל איש ישראל",[["363","1","<b>מה נשתנה</b>: כנראה דרוש ר' הלל (כנראה רק חלק)."],["364","2","<b>מה נשתנה. . הלילות</b>: נוסח ההגדה."],["365","3","<b>מאדמו\"ר שליט\"א</b>: כ\"ק אדמו\"ר הצ\"צ."],["366","4","<b>אם תעירו</b>: שה\"ש ב, ז. ג, ה."]]],[4801940146,"האה' בבחי' שינה כעין גנבא אפום מחתרתא רחמנא קריא<sup data-n=\"367\">5</sup> מצ\"ע האה' וההתקשרו' לה' שהוא ענין תוקף האמונה הפשוטה ואעפ\"כ עושה היפוך רצונו מצד שהאה' מסותרת בלתי מתפשטת בשכלו ומדותי', וצריך לעורר מדת האהבה המסותרת ע\"י התבוננות בשמע ישראל<sup data-n=\"368\">6</sup> ה' אלקינו ה' אחד, שה' אחד הוא בחי' אתה הוא לאחר שנבה\"ע, ובחי' ה' אלקינו הוא בחי' אתה הוא קודם שנבה\"ע<sup data-n=\"369\">7</sup>, המה שוין ביחודם בלתי שינוי כלל, נמצא שהוא לבדו ממש לאחר שנבה\"ע כמו קודם שנבה\"ע בלתי שינוי כלל וכמ\"ש אני ה' לא שניתי<sup data-n=\"370\">8</sup>. וכשיתבונן בכל הנ\"ל אזי תתעורר אהבה מסותרת מהעלם אל הגילוי באהבה עזה כרשפי אש להשתפך אל חיק אביה כו' עד שיתבטלו כל התאוות וכל הלגרמי' שהם בבחי' נפרד מאלקות, אך לא כל העיתים מסוגלות לזה שתתעורר מדת האהבה ע\"י התבוננות הנ\"ל רק בזמן ק\"ש ותפלה כנ\"ל, אבל כל היום ומכ\"ש בלילה הוא זמן ההסתר לגמרי עד שאינו מאיר גילוי אור האהבה רק בבחי' אמונה פשוטה שהוא נקודת יהדותו בלבד אבל לא בבחי' גילוי במוח ולב, ואלו נשמות נק' בחי' יעקב ומדת לילה ונק' בעלי תפלה. אבל יש נשמו' שנק' בעלי תורה אותם שהם מדת יום אצלם האהבה בגילוי בתמידות מצד שנתגלה אצלם שורש נשמתם כמ\"ש מתקשראן באורייתא ואורייתא וקוב\"ה כולא חד<sup data-n=\"371\">9</sup>, ולכן נק' תורה אור<sup data-n=\"372\">10</sup> שהיא מאירה את ההעלם דקוב\"ה שהוא סדכ\"ס<sup data-n=\"373\">11</sup> [מפני שהוא סתום ונעלם אפי' מעלמין סתימין שלמעלה מיוד שנברא בי' עוה\"ב<sup data-n=\"374\">12</sup> והם נק' נפלאותיך כו'], ושם אין החושך דלילה מסתיר כלל ונק' בחי' ישראל זהו תוכן הדברים בקיצור.\n<b>והנה</b> בזמן יצי\"מ א' קול דודי הנה זה בא מדלג על ההרי' כו' שהאיר מבחי' עצמי' אוא\"ס שהוא בחי' מל' דא\"ס עצמו שלפני הצמצום דקמי' כחשיכה כאורה<sup data-n=\"375\">14</sup> [כמבואר במ\"א באריכות ע\"פ הנ\"ל<sup data-n=\"376\">13</sup> ], ולשם אין אתעדל\"ת מגיע רק שמאיר מצ\"ע, ובחי' זאת נק' דילוג, ולזה האיר מבחי' עצמו' אוא\"ס בכללו' נש\"י גם במדריגת הנמוכי' הנק' מדת לילה בהשוואה עם אותם הנק' מדת יום, ולהיות כן עיקר השינוי הי' במדריגת הנק' מדת לילה [אך אעפי\"כ ג\"כ הי' שינוי במדריגת הנק' מדת יום שהאיר שלא לפ\"ע אתעדל\"ת שלהם כיון שהגילוי הי' מצ\"ע כו']. וזהו כללו' הקושיא ואח\"כ ביאר בפרט ד' שינוי', הא' שבכל הלילו' אין אנו מטבילי' כו' פי' ע\"ד טיבול גשמי שעי\"ז נאכל המאכל בטוב טעם יותר, כך",[["367","5","<b>גנבא אפום מחתרתא רחמנא קריא</b>: ראה ברכות סג, א ע\"פ גי' הע\"י. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' ט."],["368","6","<b>בשמע ישראל</b>: ואתחנן ו, ד."],["369","7","<b>אתה הוא לאחר. . קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה ג, ב. פלח הרמון שה\"ש ע' 58."],["370","8","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["371","9","<b>ואורייתא וקוב\"ה כולא חד</b>: מובא בתניא (פ\"ד ופכ\"ג) בשם הזהר. ראה מאמרי אדה\"א ויקרא ח\"א ע' רפה. וש\"נ. אוה\"ת חוקת ע' תשס."],["372","10","<b>תורה אור</b>: משלי ו, כג."],["373","11","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["374","12","<b>שנברא בי' עוה\"ב</b>: מנחות כט, ב."],["375","14","<b>כחשיכה כאורה</b>: תהלים קלט, יב. ראה לקו\"ת צו יב, א. סידור סדר הגדה רצז, רע\"ד. עט\"ר דרוש לעשי\"ת ע' נא. סה\"מ תרכ\"ז ע' תצד."],["376","13","<b>קול דודי. . ע\"פ הנ\"ל</b>: שה\"ש ב, ח. ראה פלח הרמון שה\"ש כג, ב ואילך."]]],[4801940210,"ע\"ד העבודה בנפש כאשר מביא בחי' הראי' דחכ' שבנפשו בהרחבה והשגה בטוב טעם יותר ולא בדרך קצרה בלבד ונק' טיבול וזהו בחי' יחוד חו\"ב שבנפש, להיות כי כאשר ההתבוננו' היא בבחי' חיצוני' האותיו' בלבד אעפ\"י שעומק ההשכלה ישנה אצלו בבחי' ראי' מרחוק לא נק' עדיין בחי' יחוד חו\"ב רק כשיעמיק דעתו ומעיין היטיב בהרחבת ההשגה בכל פרטי' עד שמרגיש עומקו תמצית ההשגה שעי\"ז ממילא מאיר אור עצם ההשכלה ג\"כ בכל פרט [כידוע דעומק המשיג דבינה נק' שער הנו\"ן כתר דבינה דבי' עייל שביל דקיק<sup data-n=\"377\">15</sup> שהוא ענין יסו\"א גילוי עצם ההשכלה הנק' ברק המבריק<sup data-n=\"378\">16</sup> כו' שהוא המייחד לבחי' חו\"ב]. וזהו בחי' יחוד חו\"ב הנק' יחו\"ע בנפש שהו\"ע יחוד אלקות ממש בשכל ומח', ואח\"כ נולד מזה ההתפעלו' במדות שבלב בבחי' גדלו' המוחין היינו שההתפעלו' הוא מעצם ההשגה ואינה נבדלת ממנה עד שיכול לדבר דברי תו' ותפלה בקול רם ואינו מבלבל כלל לעומק ההשגה כענין קול מעורר הכוונה<sup data-n=\"379\">17</sup> [ע' בביאור שמח תשמח, בביאור ע\"כ יעזוב<sup data-n=\"380\">18</sup> כו'], וזהו נק' טיבול שני שהוא ענין הרגשת טוב טעם ענין האלקי במדות שבלב ודיבור וענין יחוד המדות ודיבור נק' יחו\"ת בנפש. וזהו שבכל הלילות הוא הסתר גמור עד שאין אור האלקי מאיר אפי' במוח ההשגה רק עצם נקודת יהדותו מאיר קצת בבחי' ראי' מרחוק מצד כח מה שבנפשו שהוא בחי' נקודה בהעדר ההתפשטו' לגמרי רק בבחי' חיצוני' האמונה בלבד כנ\"ל בענין השינה, ובלילה הזה האיר כ\"כ האור בכללו' ההשתלשלות דיחו\"ע ויחו\"ת למעלה שהוא בחי' יחוד אוא\"ס בע\"ס דאצי' שמקבלי' מבחי' יחוד דאו\"א, וגם בבי\"ע שמקבלי' מבחי' זו\"נ דאצי' שהוא ענין יחוד מדות ודיבור עד שהאיר למטה בעשי' גשמי' כמו למע' ממש [מעין לע\"ל שיהי' הוי' א' ב\"פ י\"ה<sup data-n=\"381\">19</sup> ]. ולכן נשתנו כל המדריגות דיעקב וישראל שיהי' מאיר בנפש ג\"כ טוב טעם ענין האלקי במוח ולב ודיבור בהשוואה כנ\"ל, וזהו ענין טיבול שני פעמים שהוא ענין ב' יחודים, יחו\"ע ויחו\"ת בהשתל' למעלה ובנפש ג\"כ כו' וד\"ל.",[["377","15","<b>דבי' עייל שביל דקיק</b>: ראה זהר בהקדמה יג, ב. מאמרי אדה\"א בראשית ע' ד. וש\"נ."],["378","16","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק לקמן מאמר ד\"ה והניף הכהן אותם הב' ובהערה 54."],["379","17","<b>קול מעורר הכוונה</b>: ראה ר\"ח שער הקדושה ספט\"ו. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' נה ובהסמן במ\"מ לשם. תו\"ח בא ח\"א קו, ד ובהערה 433."],["380","18","<b>בביאור שמח תשמח, בביאור ע\"כ יעזוב</b>: ראה מאמרי אדה\"א דרושי חתונה ח\"ב ע' תסג ואילך."],["381","19","<b>לע\"ל. . ב\"פ י\"ה</b>: זכרי' יד, ט ובלקו\"ת מהאריז\"ל שם. ראה הנסמן במאמרי אדה\"א נ\"ך ע' קנב. סה\"מ תרכ\"ט ע' קכג. וש\"נ."]]],[4801940081,"<b>להבין</b> שרש ענין פסח ומצה<sup data-n=\"382\">1</sup> כו', הנה ידוע בספרי הקבלה בשרש ענין המצה שהוא בחי' קטנות דאבא<sup data-n=\"383\">2</sup>, ויש להבין דאם הכוונה בפי' קטנות זו דאור אבא הוא בחי' נה\"י שלו, הרי\"ז כמו בחי' נה\"י דאבא שמלובשים באימא שזה[ו] ענין המועדים שנק' מקרא קדש<sup data-n=\"384\">3</sup> וה\"ז ג\"כ<sup data-n=\"385\">4</sup> ענין יו\"ט דפסח בכל הז' ימים וא\"כ מהו ענין המצה שהיא חובה בליל א' בלבד<sup data-n=\"386\">5</sup>. ועוד למה נק' המשכת נה\"י דאבא בזו\"נ (דוודאי הכוונה בפי' מצה שהוא קטנות דאבא על המשכתם בזו\"נ שהמה האוכלים המצה דהיינו המשכת השפע דמצה בב' בחי' דזו\"נ הנ\"ל וכן למטה מטה<sup data-n=\"387\">6</sup> הוא המשכת השפע בנש\"י אשר שרשם בזו\"נ כמאמר בנים אתם לה' אלקיכם<sup data-n=\"388\">7</sup> כו' וד\"ל) בשם קטנות הלא כל המשכות בחי' מוחין דגדלות אפי' בחי' גדלות שני<sup data-n=\"389\">8</sup> הוא רק מבחי' נה\"י דאו\"א כידוע, וא\"כ למה נק' בשם קטנות כו'. ועוד דבוודאי יש יתרון במועד זה דפסח מכל המועדים במצות אכילת מצה שבו ולפי הנ\"ל הוא בחי' גרעון ח\"ו דביו\"ט נמשך בחי' מוחין דגדלות בזו\"נ ומצות אכילת מצה הוא רק בבחי' הקטנות בלבד. ועוד יש לתמוה דלפי המבואר בפע\"ח בכונות דליל פסח בלילה זה מאיר כל המוחין בפ\"א<sup data-n=\"390\">9</sup> בלי סדר והדרגה כלל ובזה יש יתרון לבחי' ליל א' של פסח [על שאר הימים] אפי' על בחי' השבת כמשי\"ת, וא\"כ למה עיקר המצוה בלילה זו היא אכילת מצה שרמוז בה בחי' הקטנות בלבד, ולמה לא גזרה חכמתו שבתו' ית' מצוה אחרת שיהי' רמוז בה בחי' מוחין דגדלות כו'.\n<b>אלא</b> הענין הוא דבחי' קטנות זו היא למעלה<sup data-n=\"391\">10</sup> גם מנה\"י שהרי אומרים הא לחמא<sup data-n=\"392\">11</sup> עניא די כו', בחי' נקודה תחילה<sup data-n=\"393\">12</sup> כו', כי בחי' מל' דאצי' כאשר נבנית ב[בחי'] פרצוף שלם בבי\"ע אז נק' בחי' ה\"א במילוי א' כי ג' קווי' הה\"א הוא כנגד ג' עולמות דבי\"ע<sup data-n=\"394\">13</sup> ורגל הקצר המפסיק מן הה\"א<sup data-n=\"395\">14</sup> הוא כנגד עולם העשי' כמאמר אף עשיתיו",[["382","1","<b>להבין שרש ענין פסח ומצה</b>: המאמר הוא דרוש מכ\"ק אדה\"א שנאמר בחג הפסח תקפ\"ה ונדפס בתו\"ח בא ח\"א קטו, ג [בשינויים — ושם הפתיחא והי' כי יביאך. ראה הנרשם ברשימת הכת\"י לשם] וראה הנרשם בריש המאמר שם. עם הערות וכו' מר' הלל (ולפנינו כנראה חסר ההמשך)."],["383","2","<b>מצה. . קטנות דאבא</b>: ראה סידור סדר הגדה חצר, סע\"א ואילך. תו\"ח בא ח\"א צד, ד הערה 393."],["384","3","<b>המועדים שנק' מקרא קדש</b>: בא יב, טז. אמור כג, ז ואילך. ב: מקראי קדש — אמור כג, ב. ד. לז. ראה תו\"ח כאן הערה 8."],["385","4","<b>ג\"כ</b>: ניתוסף ע\"פ ב."],["386","5","<b>המצה שהיא חובה בליל א' בלבד</b>: פסחים קכ, א. מכילתא ורש\"י בא יב, טו. רמב\"ם הל' חו\"מ רפ\"ו. שו\"ע אדה\"ז הל' פסח סתע\"ה, סל\"ב."],["387","6","<b>מטה</b>: ניתוסף ע\"פ ב."],["388","7","<b>בנים אתם לה' אלקיכם</b>: פ' ראה יד, א."],["389","8","<b>גדלות שני</b>: ראה גם בענין גדלות שני פע\"ח שער חג המצות שכ\"א, פ\"א. פ\"ה. ביאורי הזהר תזריע ע, ד ואילך. ומקבילו — הנחת הר\"מ — במאמרי אדה\"ז תקס\"ג ח\"א ע' שלא."],["390","9","<b>דליל פסח. . כל המוחין בפ\"א</b>: ראה פע\"ח שם פ\"א. ועוד."],["391","10","<b>למעלה</b>: ב: למטה."],["392","11","<b>שהרי אומרים הא לחמא</b>: בנוסח ההגדה."],["393","12","<b>די. . נקודה תחילה </b>[ב: תח\"י]: ראה פע\"ח שער חג המצות שכ\"א, פ\"ז. שה\"א פי\"ב. בסמוך בפנים."],["394","13","<b>ג' קווי' הה\"א. . דבי\"ע</b>: ראה גם לקמן מאמר ד\"ה ענין יצי\"מ וקי\"ס על יד הערה 26. ד\"ה וזכרתי הר\"ת על יד הערה 21. אוה\"ת ואתחנן ע' ריז. בא ע' רפג. סה\"מ תרל\"ב ח\"א ר\"ע כב. ס\"ע קמז ואילך."],["395","14","<b>המפסיק מן הה\"א</b>: ב: ליתא."]]],[4801940147,"אף הפסיק הענין<sup data-n=\"396\">15</sup>, וזהו ענין בנין המל' בפרצוף שלם והיינו כאשר נמשך אור המל'<sup data-n=\"397\">16</sup> למטה מטה אפי' בעולם העשי' ואז גם עולם עשי' הוא בבחי' ביטול לאלקים חיים ומלך עולם<sup data-n=\"398\">17</sup> ואז נק' ה' והא' שבמילוי [ההא] הוא המשכת בחי' אלקות דז\"א דאצי' הנמשך ע\"י בחי' המל' דאצי' בבי\"ע. אך כשעולה המל' מברי' לאצי' להבנות בבחי' פרצוף שלם בבחי' אצי' א\"א לה לקבל אור האצי' כמ\"ש<sup data-n=\"399\">19</sup> למע' אם לא שנתעלם תחילה בבחי' נקודה א'<sup data-n=\"400\">20</sup> שזהו [ענין] לחמא עניא תכלית השפלות שאינו מאיר בה אפי' בחי' נה\"י (כי כל הט\"ס באים בסוד תוס' ומתעלמים במקורם כידוע), רק בחי' עצמות הנ\"ל<sup data-n=\"401\">21</sup> (כמו שנאצלה ביסוד<sup data-n=\"402\">22</sup> שרש)<sup data-n=\"403\">18</sup> שאינה אלא בחי' נקודה בלבד, ואז נק' בשם ד'<sup data-n=\"404\">23</sup> דלית יו\"ד כי הד' מורה שאינו מאיר בחי' המל' בבחי' [ה]עשי' ולכן נחסר רגל הקצר, ואז גם בבחי' יצירה אינו מאיר רק האור שנמדד בהם רק<sup data-n=\"405\">24</sup> עפ\"י קו המדה דהשתל' ולא [ב]בחי' תוספת אור התלוי במעשה התחתונים דעשי'<sup data-n=\"406\">25</sup> דווקא וא\"כ גם בבחי' המל' עצמה אינו מאיר תוס' [ה]אור מבחי' אא\"ס שעי\"ז אתבסמת נוק'<sup data-n=\"407\">26</sup> כו', ונשאר רק עצם טבע המל' שהוא בבחי' הסתלקות והתכללות במקורה מגו דחיקו דרחימא<sup data-n=\"408\">27</sup> כמבואר במ\"א. ואז היא בבחי' נקודה בלבד למטה מנה\"י דז\"א כנ\"ל, וממילא אינו מאיר מבחי' אבא בבחי' נקודה זו רק בחי' הקטנות דאור אבא שלמטה מנה\"י שבו כו'. אך יש בו יתרון מעלה הרבה שמלובש בזה מעצמות ומהות דאור אבא מבחי' ג\"ר שבו (מעצם המהות ש[ב]הן ולא הארתן בלבד כמשי\"ת) שאינו מלובש באו\"א<sup data-n=\"409\">28</sup> כלל [כי אעפ\"י שאו\"א כחדא שריין<sup data-n=\"410\">29</sup> מ\"מ לא יוכל להתקבל בבחי' בינה רק הארת אבא, רק שכל הפרצוף דאבא מאיר באימא בכל הי\"ס שבו ולא כמו בזו\"נ שיש שינוים רבים בהארת ז\"א בנוק' לפעמים אינו מאיר רק נה\"י כו' ולפעמים שווין בקומתם<sup data-n=\"411\">30</sup>, אבל באו\"א מאיר בתמידות אפי' הארת ג\"ר שבו בבחי' אימא אבל לא עצמות המהות שבו כו' וד\"ל).\n<b>וביאור</b> הענין הנה ידוע בכללות ענין ההפרש בין בחי' מוחין דאבא לבחי' מוחין דאימא<sup data-n=\"412\">31</sup> שזהו בחי' רו\"ש שהמה ב' הפכים כאש ומים ממש, ואעפ\"כ המה",[["396","15","<b>אף עשיתיו אף הפסיק הענין</b>: ישעי' מג, ז. ראה גם לקמן מאמר ד\"ה ענין יצי\"מ וקי\"ס על יד הערה 24. תו\"ח בשלח ח\"א קמד, ג. וש\"נ."],["397","16","<b>אור המל'</b>: ב: ליתא."],["398","17","<b>לאלקים חיים ומלך עולם</b>: ע\"פ ירמי' י, י."],["399","19","<b>כמ\"ש</b>: ב: כמו שהוא."],["400","20","<b>א'</b>: שם: תח\"י."],["401","21","<b>עצמות הנ\"ל</b>: שם: עצמית המל'."],["402","22","<b>ביסוד שרש</b>: שם: בסוד ספירה."],["403","18","<b>המל'. . הט\"ס באים בסוד תוס'.. ביסוד שרש</b>: ראה ע\"ח שער מיעוט הירח של\"ו, פ\"א. פ\"ב. לקו\"ת צו יא, ב. ביאוה\"ז להצ\"צ כרך א ע' תצו ואילך. סה\"מ תרל\"ח ע' ח. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתפו."],["404","23","<b>ד'</b>: שם: די."],["405","24","<b>רק</b>: שם: ליתא."],["406","25","<b>דעשי'</b>: שם: ליתא."],["407","26","<b>אתבסמת נוק'</b>: ראה זהר לך צד, א."],["408","27","<b>מגו דחיקו דרחימא</b>: ראה זהר בלק קצא, א. ביאוה\"ז שבהערה 18. מאמרי אדה\"א שמות ח\"ב ע' תמז. וש\"נ."],["409","28","<b>באו\"א</b>: ב: באור אמא."],["410","29","<b>שאו\"א כחדא שריין</b>: ראה זהר (אד\"ז) האזינו רצ, ב."],["411","30","<b>בזו\"נ. . שווין בקומתם</b>: ראה ע\"ח שבהערה 18. ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקצג ואילך."],["412","31","<b>ההפרש בין בחי' מוחין דאבא. . דאימא</b>: ראה ביאוה\"ז תזריע עב, א. מאמרי אדה\"ז תקס\"ה ח\"א ע' תכג."]]],[4801940211,"בתכלית היחוד עד שלא יוכל למשוך בחי' מוחין דאבא שהוא בחי' מים ובחי' שוב אם לא ע\"י ההעלאה דרצוא שהוא מבחי' מוחין דאימא שהוא בחי' אש<sup data-n=\"413\">32</sup> כו', והיינו ע\"י כח המייחדם שהוא בחי' הדעת שעלי' נאמר יעשה שלום לי<sup data-n=\"414\">33</sup>. וכידוע דהתפעלות רשפי אש התשוקה הנולד בלב מבינה שנק' אימא<sup data-n=\"415\">34</sup>, שהוא ההשגה והקליטה במוח בינה בהסבר הדבר בגדלות הבורא איך שהוא בעצמו קדוש ומובדל מגדר ממלא וסובב רק הודו בלבד מאיר על ארץ ושמים<sup data-n=\"416\">35</sup> ועי\"ז נעשה בחי' רצוא שהוא בחי' הפשטת המדות שבלב שכללות[ה] הוא מדת האהבה ותתפשט אהבה זאת מלבושי' לא לחפוץ שום דבר גשמי' ורוחני' רק לה' לבדו עצם הממלא והסובב כו'. והנה ההעלאה הזאת עיקר הכוונה היא ממנה שימשך על ידה גילוי אא\"ס [מ]למעלה למטה שנק' בחי' מוחין דאבא שזהו בחי' השוב שנמשך מצד הרצוא כנ\"ל, ולהיות שהרצוא והשוב המה [ב]ב' הפכים כנ\"ל [ו]לכן כדי להתהוות מבחי' הרצוא בחי' שוב צריך שיהי' מתחלה בחי' ביטול התשוקה וביטול ההשגה בתחלה. והיינו כאשר מאיר אצלו למעלה מכלי ההשגה דאורך ורוחב<sup data-n=\"417\">36</sup> בחי' עומק המושג שהוא בחי' שער הנו\"ן דבינה ומבחי' עומק המושג בא לבחי' ביטול השגה לגמרי שהוא ענין מה פשפשת<sup data-n=\"418\">37</sup> כו', ובחי' זאת הוא בחי' [יסוד] אבא שנמשך ממנו בחי' הדעת (כי יסוד אבא הוא ביטול ההשגה דבי' עייל אבא לאימא<sup data-n=\"419\">38</sup> שזהו בחי' המשכת עצם השכל כמשי\"ת, ודעת הוא בלב בחי' ביטול התשוקה כו'). וכאשר נעשה בחי' ביטול ההשגה והתשוקה, אזי נמשך בחי' אוא\"ס<sup data-n=\"420\">39</sup> שהוא בחי' ראיית השכל [ש]בעצמו[ת] אלקות הממלא ו[ה]סובב שהוא בחי' עצם המהווה שהוא למע' הרבה מן ההשגה והבנה באיכות התהוות המתהווה שהוא רק הארה בעלמא כמא' הודו כנ\"ל, וממילא משיג איכות הביטול שלו לעצם המהווה. אך מה שמאיר בחי'<sup data-n=\"421\">40</sup> הראי' דחכ' אחרי ביטול השגה בבחי' עצם המהווה הוא למעלה הרבה מהשגת הביטול שאינו אלא לפ\"ע ההשגה שלו באיכות הביטול, ואינו מאיר אמיתת הביטול כמ\"ש, אבל בבחי' הראי' דחכ' מאיר אמיתית הביטול כמ\"ש, וכידוע בענין אינו דומה שמיעה לראי'<sup data-n=\"422\">41</sup> כי כשרואה פני המלך מתבטל בביטול עצמי שלמע' מן ההשגה וטעם לגמרי כו', וביטול זה מאיר במוח ואז ג\"כ מתקרר התשוקה והצמאון שבבחי'<sup data-n=\"423\">42</sup> הלב ברשפי אש להפשיט א\"ע מלבושי' וכלים שלו<sup data-n=\"424\">43</sup> תשוב רוחו שבלב אליו להתלבש בכלי הלב והוא",[["413","32","<b>מוחין דאבא. . מים. . דאימא. . אש</b>: ראה מאמרי אדה\"א בראשית ע' תעא ואילך. הנחות תקע\"ז ע' קמז. תו\"ח שמות ח\"א כז, ג ובהנסמן במקומות הנ\"ל."],["414","33","<b>יעשה שלום לי</b>: ישעי' כז, ה."],["415","34","<b>מבינה שנק' אימא</b>: ראה זהר אד\"ז האזינו רצ, א. ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"ה. מאמרי אדה\"א בראשית ע' א. וש\"נ."],["416","35","<b>הודו. . על ארץ ושמים</b>: תהלים קמח, יג."],["417","36","<b>למעלה. . ורוחב</b>: ב: מכללות השגה דאוי\"ר."],["418","37","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["419","38","<b>דבי' עייל אבא לאימא</b>: ראה זהר בהקדמה יג, ב. מאמרי אדה\"א בראשית ע' ד. וש\"נ."],["420","39","<b>אוא\"ס</b>: ב: אוא\"ב אור אבא."],["421","40","<b>בחי'</b>: שם: כח."],["422","41","<b>אינו דומה שמיעה לראי'</b>: ראה מכילתא יתרו יט, ט. לק\"ט שלח יג, יח. מאמרי אדה\"א דברים ח\"א ע' קמו ואילך. שה\"א ט, ב הערה 14. סה\"מ תרכ\"ז ע' שמט. וש\"נ. תרל\"ב ח\"א ע' י. וש\"נ."],["423","42","<b>שבבחי'</b>: ב: שבחיות."],["424","43","<b>תשוב</b>: שם: כי עי\"ז יתמשך."]]],[4801940266,"בחי' שוב כמאמר אם רץ לבך<sup data-n=\"425\">44</sup> ע\"י ההשגה דבינה שוב כנ\"ל ע\"י הארת אוא\"ס שאחר<sup data-n=\"426\">45</sup> הרצוא שנעשה ע\"י ההשגה דבינה נמשך<sup data-n=\"427\">46</sup> בחי' שוב ע\"י [בחי'] ביטול דראי' דחכ'.\n<b>וביאור</b> הענין למה נעשה ע\"י החכ' בחי' שוב כי לכאו' הוא למעלה מבחי' בינה וא\"כ הי' צריך להיות התגברות הרצוא. אך הענין יובן בהבין ענין עצם החכ' הוא בחי' ראשית הגילוי מאין בכח<sup data-n=\"428\">47</sup> המשכיל ונק' בחי' שכל, ועפ\"י רוב שכל זה [ה]מאיר כברק הוא שכל פשוט להיותו מושכל ראשון ואח\"כ כשמייגע עצמו בשכל הזה<sup data-n=\"429\">48</sup> להבין דבר מתוך דבר אז מוליד ממנו השכלות עמוקות בא\"ע בלי<sup data-n=\"430\">49</sup> שיעור. ולכאורה איך<sup data-n=\"431\">50</sup> יוליד משכל קטן שכל הגבוה ממנו, וע\"כ שבחי' המושכל ראשון הוא הוא<sup data-n=\"432\">51</sup> עצם המושכל שלמעלה מגילוי אור והוא אינו מאיר<sup data-n=\"433\">52</sup> והוא אינו בגדר מעלה ומטה כלל ובו כלול כח העילוי וכח הירידה ביחד, והיינו מה שבכח השכל להשכיל ממנו השכלות עמוקות יותר נק' כח העילוי [שבו] (שהוא בחי' האין דחכ' הנק' מ\"ע כמבואר בביאור תו\"ח<sup data-n=\"434\">53</sup> כו'), ומה שבכח השכל להוציא<sup data-n=\"435\">54</sup> השגות המלבישים השכל וכן להוליד בחי' מדות מהשגה והלכה למעשה מבחי' המדות נק' כח הירידה שבחכ' זאת (שהוא בחי' היש דחכ' הנק' מים תחתונים כו'), אך עצם המושכל הוא הכולל כח העילוי וכח הירידה כא' נמצא שאינו בגדר מעלה ומטה כלל. והנמשל יובן למשכיל בבחי' אוא\"ס<sup data-n=\"436\">55</sup> שראשית הגילוי מאא\"ס להיות מקור ההשתל' הוא בחי' נקודה בלבד ובה מלובש אא\"ס בבחי' העלם למעלה מגדר גילוי אור (ונק' בחי' עקודים בל' הקבלה כו'), ומבחי' נקודה זאת [נתגלה כל בחי' ההשתלשלות בריבוי מדרגות בעא\"ע עד אין קץ שהוא בחי' עלמין סתימין ובירידה אחר ירידה שהוא בחי' עלמין דאתגלי', ובחי' זאת] דעצמות אא\"ס נמשך ומתלבש בהעלם בכל עולם בפרט בבחי' החכ' שבו. ונמצא שבחי' עומק רום ועומק תחת הוא בבחי' הבינה שהוא כח המגלה כל פרטי ההשתל' בעא\"ע לאין קץ, ובירידה אחר ירידה עד אין תכלית שזהו בחי' מח' דבינה, ו[ב]בחי' זאת שייך לומר שכל מי שהוא בבחי' עומק תחת ביותר שרשו בעומק רום ביותר אבל בבחי' החכ' לא שייך לומר עומק רום ועומק תחת [כלל] כי הוא אינו בגדר רום ותחת כלל. ויובן עוד עפ\"י משל א' מחטה שאין בה עדיין טעם כלל ולכן הכוסס את החטה מברך בפה\"א<sup data-n=\"437\">56</sup> מצד דלא אשתני למעליותא, אכן כשטוחנים אותה ועושים ממנה מטעמים שונים אז<sup data-n=\"438\">57</sup> מתגלה ממנה טעמי' שונים משובחים מאד וע\"כ [לומר] שכל הטעמים האלו היו כלולים",[["425","44","<b>אם רץ לבך</b>: ס\"י פ\"א, מ\"ח."],["426","45","<b>אוא\"ס שאחר</b>: ב: דאור אבא שנעשה אחר."],["427","46","<b>נמשך</b>: שם: ליתא."],["428","47","<b>בכח</b>: שם: הנעלם מכח."],["429","48","<b>הזה</b>: שם: ליתא."],["430","49","<b>בא\"ע בלי</b>: שם: בעא\"ע [ בעילוי אחר עילוי] עד אין."],["431","50","<b>ולכאורה איך</b>: שם: ולבאר האיך."],["432","51","<b>הוא</b>: שם: ליתא."],["433","52","<b>והוא אינו מאיר</b>: שם: ליתא."],["434","53","<b>האין דחכ' הנק' מ\"ע. . תו\"ח</b>: ראה תו\"ח בראשית א, ב. פלח הרמון שם ד, א ואילך."],["435","54","<b>להוציא</b>: ב: להמציא."],["436","55","<b>אוא\"ס</b>: שם: א\"ס."],["437","56","<b>הכוסס את החטה מברך בפה\"א</b>: ברכות לז, א."],["438","57","<b>אז</b>: ב: מאוד."]]],[4801940318,"בחטה בבחי' העלם ואעפ\"כ לא הרגיש[ו] בה שום טעם כלל. וע\"כ [לומר] שטעם הפשוט דחטה הוא טעם עצמי' ופשוט שלמעלה מבחי' טעם מורגש, רק ע\"י הרכבה ובישול ממשיכים ומלבישים טעם הפשוט העצמו' בטעמים שונים ומורגשים ואז מתגלה טעם הפשוט בבחי' גילוי אור, כי בכל הטעמים מורגש מעין טעם החטה שזהו רק גילוי אור [ה]עצמי' הטעם שבה. ועד\"ז יובן בבחי' גילוי עצמות החכ' לגבי גילוי אור דבינה שכולל כל הגילוים דמעלה ומטה דבינה [כולם] כאחד וד\"ל (ועיין בזהר פ' תרומה בהפרש שבין סד\"צ<sup data-n=\"439\">58</sup> לכל הזהר [כולה] כו' וד\"ל).\n<b>אך</b> עדיין אינו מובן דא\"כ למה אור החכ' הוא פועל בחי' שוב בלבד ולא בחי' רצוא, כיון שאור החכ' אינו בגדר מקום כלל<sup data-n=\"440\">59</sup> א\"כ כמו שיכול להיות נמצא בבחי' מטה ושוב (ולא כמו אור הבינה שעולה מלמטה למעלה והיינו כל מה שמתבונן בעומק תחת [ב]יותר שהוא ההסבר בטוב טעם באיכות התהוות המתהווה יבוא לבחי' עומק המושג<sup data-n=\"441\">60</sup> יותר שהוא בחי' השגת איכות הביטול הנק' עומק כנ\"ל<sup data-n=\"442\">61</sup> ), אבל מ\"מ יכול להיות נמצא גם בבחי' מעלה כיון שאינו בגדר מקום כנ\"ל, אך שרש הענין הוא להיות שפנימיות הרצון שעלה ברצון הפשוט<sup data-n=\"443\">62</sup> להיטיב<sup data-n=\"444\">63</sup> הי'<sup data-n=\"445\">*64</sup>* ע\"י סוכ\"ע<sup data-n=\"446\">64</sup> דווקא כמאמ' במי נמלך בנשמתן של צדיקים<sup data-n=\"447\">65</sup> שהוא בחי' נש\"י בגופים, והנה מבחי' הרצון להיטיב נמשך בחי' הצמצום וההעלם להעלים את עצמותו שהוא בחי' גבו' שנמשך מחסד שברצון הנ\"ל, והיינו שיתעלם אורו וזיוו אשר הוא בבחי' א\"ס ולא יתגלה רק הארה דהארה כפי הצורך להיות מקור ההשתלשלות וכמ\"ש כי עמך מקור חיים<sup data-n=\"448\">66</sup> באורך נראה אור הארה דהארה בלבד כו'. והנה ראשית הגילוי שאחר הצמצום להיות מקור ההשתל' כי היא<sup data-n=\"449\">67</sup> בחי' נקודה הנק' עולם העקודים כנ\"ל, ובכל עולם ועולם ראשית הגילוי המתגלה אחר הצמצום שבשביל עולם ההוא הוא בחי' החכ' שבכל עולם ועולם כנ\"ל, וא\"כ בבחי' החכ' מלובש הרצון להיטיב ע\"י צמצום [כנ\"ל] ופנימי' הרצון הי' להיות לו דירה בתחתונים<sup data-n=\"450\">68</sup> לכן עיקר גילוי החכ'",[["439","58","<b>סד\"צ</b>: ספרא דצניעותא (זהר תרומה קעו, ב-קעח, ב). ב: סתי' דכל סתימ'."],["440","59","<b>כלל</b>: ב: ליתא."],["441","60","<b>המושג</b>: שם: ראשון."],["442","61","<b>עומק כנ\"ל</b>: שם: עומ\"ר [ עומק רום] כו'."],["443","62","<b>שעלה ברצון הפשוט</b>: ראה ע\"ח שער עגו\"י ש\"א, ענף ב. אדם ישר דרושי העגולים ענף ב. עמה\"מ שער שעשועי המלך רפ\"א. שעה\"י קטו, א הערה 2. לקמן בפנים על יד הערה 122. מאמר ד\"ה ענין זכר בא לעולם על יד הערה 19. ד\"ה הנה וכו' הצרוע תקצ\"ט על יד הערה 18. ד\"ה ענין העבודה דיוה\"כ על יד הערה 7. ד\"ה אם בחוקותי הג' על יד הערה 102."],["444","63","<b>להיטיב</b>: ראה ע\"ח שער הכללים בתחילתו. שער ההקדמות דרוש גדול כשעלה ברצון המאציל לברא העולם (קנו, א). עמה\"מ שם. שבר יוסף — להנ\"ל — ס\"א. כנפי יונה ח\"א רפ\"א."],["445","*64","<b>הי'</b>: ב: הוא."],["446","64","<b>סוכ\"ע</b>: שם: סוף מעשה."],["447","65","<b>במי נמלך בנשמתן של צדיקים</b>: ראה ב\"ר פ\"ח, ז. רו\"ר פ\"ב, ג. לקו\"ש פ' החודש כרך טז ע' 487 בהערה. שע\"ת קטו, ב."],["448","66","<b>כי עמך מקור חיים</b>: תהלים לו, י. ראה מאמרי אדה\"א דברים ח\"א ע' קעח. וש\"נ. תו\"ח וארא ח\"א ס, ב הערה 24."],["449","67","<b>כי היא</b>: ב: הוא."],["450","68","<b>להיות לו דירה בתחתונים</b>: ראה תניא רפל\"ו (ובהנסמן בליקוט פירושים לשם). ביאוה\"ז תזריע עב, ג. מאמרי אדה\"א הנחות תקע\"ז ע' שכט. שערי אורה צז, ב. לקמן מאמר ד\"ה אם בחוקותי הג' (קרוב לסופו) פיסקא אך הנה ידוע. סה\"מ תרל\"ח ע' לט הערה 138."]]],[4801940367,"הוא פועל בחי' שוב והיינו שיהי' הגילוי למטה כו' וד\"ל. והנה בחי' רו\"ש הנ\"ל שהוא בחי' היחוד דחו\"ב נק' בשם תשובה עילאה, תשובה<sup data-n=\"451\">69</sup> דבחי' רצוא דבינה לכלל באור אבא בבחי' שוב שזהו היפוך בחי' הרצוא עצמו לבחי' [שוב] דהיינו שתשוב רשפי אש<sup data-n=\"452\">70</sup> התשוקה שבלב ומוח בינה להיות בבחי' ביטול דחכ' כו', ובזה נתקן [בחי'] גבו' דאימא ונמתקים בחסדים דאבא ויוכל לבוא בה<sup data-n=\"453\">71</sup> השפעת אור אבא.\n<b>וביאור</b> הדברים יובן ע\"פ המבואר בב\"ז פ' תזריע בפי' והובא את בדיו<sup data-n=\"454\">72</sup> ולא אמר והעלה, וכללות הענין המובן [מ]שם הוא שלהיות עיקר הכוונה בחי' המשכת אוא\"ב<sup data-n=\"455\">73</sup> באימא דווקא שזהו נק' יחוד דווקא ולא העלאת אור אימא באבא שאינו נק' יחוד כלל, כי בהתעלות אור אימא ליכלל באוא\"ב נתבטל ממציאותו ואין זה יחוד רק כששניהם הם במציאות ומתאחדים זה בזה והיינו כשאור אבא מאיר [ב]גילוי בבחי' אימא בהיותה במקומה אז הוא אמיתית היחוד כנ\"ל. וביאור הענין הנה ידוע שיש בחי' רצוא ובחי' שוב המתגבר על בחי' הרצוא ומתבטל מציאותו לגמרי, ויש בחי' שוב המתגבר על כח<sup data-n=\"456\">74</sup> הרצוא וממתיקו עד שמתהפך בחי' הרצוא לשוב, כי הנה מבואר למע' בבחי' הרצוא המתהווה ע\"י ההשגה דמוח בינה בהסבר הדבר בגדלות הבורא איך שהוא ית' למעלה מבחי'<sup data-n=\"457\">75</sup> ממלא וסובב ורק הודו על ארץ ושמים, והנה בחי' זאת הוא בחי' גבורותיו של הקב\"ה שפועל הארה<sup data-n=\"458\">76</sup> בעצמות אורו ועי\"ז נ[ת]גלה בחי' הארה דהארה מעצמות האור להיות בבחי' ירידה למטה מטה עד אין תכלית, וכל שמעלים א\"ע ביותר בבחי' עליות והתכללות האור במאור יותר נעשה בחי' ירידה יותר בהארה דהארה המתגלה מעצמות האור ולכן עומק תחת תלוי בעומק רום כנ\"ל. והנה בחי' זאת דגבורותיו של הקב\"ה מתגלית בנפש במוח הבינה שמוח הבינה שבנפש שהוא [בחי'] כלי לאור ההשגה הנה ההשגה הוא בחי' קליטה ותפיסא לתפוס הכח [ד]גבור' של הקב\"ה, ולכן מלמטה למעלה תלוי [עומ\"ר] בעומק תחת שכל מה שמתבונן באיכות התהוות כל פרטי ההשתל' מאין ליש בהרחבה יותר שזהו בחי' עומק תחת כנ\"ל יותר נקלט אצלו תמצית ההשגה יותר, והיינו בחי' עומק המושג שהוא הקליטה שנתפס ונקלט במוח בינה איכות ביטול כל ההשתל' למקורם המהווה אותם מאין ליש כנ\"ל וזהו בחי' עומק רום כנ\"ל. והנה מצד ההשגה הזאת נתהווה בחי' גבורות בלב שהוא בחי' הצימאון ורשפי אש האה' להתפשט מלבושי' וליכלל מעלה מעלה באורו העצמי שלמעלה [מעלה] מההשתל' ליכלל<sup data-n=\"459\">77</sup> במאור (שמסיבה זאת היתה התהוות ההשתלשלות כו').\n<b>והנה</b> מבואר למעלה בסיבת הצמצום שהוא בחי' הגבורות, הנה גבורות אלו נמשכים מבחי' החסדים שהוא מה שעלה ברצונו הפשוט להיטיב שהוא בחי'",[["451","69","<b>תשובה</b>: ב: תשוב ה\"א."],["452","70","<b>אש</b>: שם: ליתא."],["453","71","<b>בה</b>: שם: בחי'."],["454","72","<b>בב\"ז. . והובא את בדיו</b>: תרומה כז, ז. ביאורי הזהר תזריע עג, ד."],["455","73","<b>אוא\"ב</b>: אור אבא."],["456","74","<b>כח</b>: ב: בחי'."],["457","75","<b>ית' למעלה מבחי'</b>: שם: ליתא."],["458","76","<b>הארה</b>: שם: העלאה"],["459","77","<b>ליכלל</b>: שם: כמו שהוא נכלל."]]],[4801940413,"חסד שברצון הנ\"ל, כי הנה מה שאנו אומרים עליית והתכללות האור במאור לשון עלי' לא שייך רק בבחי' האור אבל לא בעצם המאור, ואדרבה על בחי' המאור שייך לשון ירידה והמשכה שהוא ענין בחי' תפיסא והלבשה בהארה דהארה המאיר בבחי' השתלשלות שבחי' תפיסא זאת פועל העלם עצמי' האור ולהיות נגלה בחי' הארה, ולכן בבחי' המאור יתפרש בחי' צמצום לשון תפיסא והלבשה בדבר מצומצם שהוא מלשון דחק כענין האה' דוחקת את הבשר<sup data-n=\"460\">78</sup> וכענין צמצם שכינתו בין שני בדי הארון<sup data-n=\"461\">79</sup> להיות מועט מחזיק את המרובה, והיינו שכל העצמות יתעלם ויתלבש בבחי' ההשתל' שהוא רק פרט אחד לגבי העצמות כמו ויצא כברק חצו<sup data-n=\"462\">80</sup>. והנה בחי' תפיסא והלבשה [זאת] בא מצד הרצון שנתעורר בבחי' חסד וטוב שהוא להיות נמשך בבחי' מטה דווקא וידוע בשם הבעש\"ט שבכל מקום שנתפס הרצון<sup data-n=\"463\">81</sup> שם נתפס העצמי' כנ\"ל<sup data-n=\"464\">82</sup>, ובחי' זאת היא הגורמת צמצום והתעלמות האור להיות נראה אור. ונמצא שמקור הגבורות אלו הפועל התכללות האור במאור הוא בחי' חסדים שבמאור שהוא ענין צמצום הראשון<sup data-n=\"465\">83</sup> להיות נתפס למטה בהשתל' דווקא [כו' וד\"ל]. ומבואר למעלה שבחי' זאת דרצון הנעלם הפועל את הצמצום הוא נתפס בבחי' ראשית הגילוי שאחר הצמצום שהוא בחי' הנקודה כנ\"ל (שהוא בחי' עולם הנקודים<sup data-n=\"466\">84</sup> בכלל ובפרט הוא בחי' החכ' שבכל עולם ועולם כנ\"ל ), ולכן אחר הרצוא דמוח בינה מתגלה עצם הנקודה דחכ' להיות בבחי' שוב שהוא ענין הביטול דראי' דחכ' בעצמי' כח האלקי המהווה כנ\"ל. והנה בחי' זאת נק' קדושה שהיא עצמית גילוי אור החכ' הנק' קדש מלה בגרמי'<sup data-n=\"467\">85</sup> כנ\"ל, אך אחר הקדושה נמשך בחי' ברכה והו\"ע המשכת אור אבא באימא, והיינו מה שנמשך הביטול [ה]עצמי' [הנ\"ל] בכל פרטי ההשתל' להרגיש בכל פרט ופרט מפרטי ההשתל' בחי' עצם כח האלקי המהווה אותו, וזהו נק' [בחי'] כלל שאחר הפרט שהוא מרגיש את הכלל בכל פרט [ופרט] הנמשך ממנו, ובחי' זאת נמשך ע\"י הדעת המיחד בחי' או\"א ושרשו הוא מבחי' רצה\"פ עצמו כמ\"ש<sup data-n=\"468\">86</sup> קודם שנתלבש בבחי' טוב וחסד (שהוא בחי' פרט אחד מרצון הנ\"ל). והנה בגמר המשכה זאת בכל הפרטים דבינה והיינו כאשר מתגלה אצלו ראי' החכ' דעצם המהווה בכל פרט מפרטי ההשתל' עד פרט היותר אחרון דעוה\"ז הגשמי עד שאין מסתיר לפניו אפי' גשמי' דעוה\"ז אז נק' בחי' יחוד אמיתי [ד]או\"א, וזהו בחי' תשו\"ע הנ\"ל בהיפוך הרצוא עצמו לבחי' שוב כו' וד\"ל.",[["460","78","<b>האה' דוחקת את הבשר</b>: ב\"מ פד, א. ראה גם תניא פמ\"ט. מאמרי אדה\"ז על ענינים ע' כב."],["461","79","<b>צמצם שכינתו. . הארון</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). לקו\"ת אמור לד, ב. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12. לקמן מאמר ד\"ה והתהלכתי בתוככם תר\"ב על יד הערה 18."],["462","80","<b>ויצא כברק חצו</b>: זכרי' ט, יד."],["463","81","<b>בשם הבעש\"ט שבכל מקום שנתפס הרצון</b>: ראה גם לקמן מאמר ד\"ה וספרתם הה' ובהערה 222."],["464","82","<b>כנ\"ל</b>: ב: כו'."],["465","83","<b>הראשון</b>: שם: הרצון."],["466","84","<b>הנקודים</b>: שם: העקודים."],["467","85","<b>החכ' הנק' קדש מלה בגרמי'</b>: ראה זהר אמור צד, ב. לקו\"ת מסעי צג, א. מאמרי אדה\"א דברים ח\"ג ע' תתקב."],["468","86","<b>עצמו כמ\"ש</b>: ב: כמו שהוא."]]],[4801940455,"<b>והנה</b> כ\"ה בלב נעשה ג\"כ יחוד הנ\"ל דרו\"ש והתהפכות הרצוא עצמו לבחי' שוב, דהנה מבחי' ההשגה דבינה באיכות התהוות המ[ת]הווה הנק' עומק תחת וביטול המתהווה למהווה הנק' עומק רום יולד מזה בלב בחי' התפעלות רשפי אש בבחי' רצוא ולהפשיט אהבת לבו מכל [וכל] מיני התקשרות שלא יהי' לה[ם] שום אחיזה והתקשרות בשום דבר גשמי' ורוחני' כ\"א לה' לבדו, ואח\"כ מתגלה בחי' הראי' דחכ' בעצם המהווה [ש]מתהווה מזה בחי' דאגה בלב לעצם הפלאת המהווה אשר לא יכול לאדבקא כו' ומזה נמשך אח\"כ בחי' התהפכות הרצוא עצמו לשוב, והיינו אשר התשוקה ברשפי אש שהיתה מקודם ליכלל וליבטל לגמרי עתה מתהפכת בבחי' שוב והיינו שיחפוץ בבחי' המשכת אא\"ס בריבוי כלים מכלים שונים ע\"י עשיית התורה והמצות כנ\"ל. וכמו עד\"מ בנשיקת הנוק' לגבי דכורא קודם היחוד ואח\"כ כאשר מקבלת השפע אתבסמת נוק' ונופלת התשוקה, והנה גם בשעה שצריך המקבל לקבל השפע מוכרח ג\"כ שיעצור בעצמו רשפי אש תשוקתו שזהו התקררות הצימאון שנמשך מצד תוקף הצימאון דווקא וכמו אש אכלה אש<sup data-n=\"469\">87</sup>, כ\"א יהי' בהתגברות התשוקה ברשפי אש ביותר לא יוכל להתקבל בו השפע של המשפיע כו'. וכ\"ה בהשגה דבינה בענין האלקי שבא מזה לבחי' עומק המושג שהוא תוקף התשוקה כרשפי אש ואח\"כ כאשר נעשה ביטול ההשגה לגמרי כנ\"ל כענין מה פשפשת, הנה עי\"ז נעשה בחי' כלי לקבל בחי' גילוי עצם החכ' שהוא בחי' ראיית השכל בעצם המהווה. וזהו בחי' יסוד אבא שכלול משתי בחי' חו\"ג ובחי' הגבורה שבו המה בחי' אש אכלה אש לפעול ביטול ההשגה במוח וביטול התשוקה בלב כנ\"ל (שזהו בחי' דעת הנמשך מיסוד אבא שהוא ענין הגילוי שלו בלב שיש בו ג\"כ חו\"ג<sup data-n=\"470\">88</sup> כנ\"ל ), ובחי' החסדים שביסוד אבא המה פועלים בחי' המשכה דבי' עייל אבא לאימא שפועל התהפכות גמורה להתהפך הרצוא לשוב היינו במוח בינה המשכת בחי' הראי' דחכ' לראות עצם המהווה בכל פרט מפרטי השתל' כנ\"ל, ובלב התהפכו' התשוקה לאהבת קיום התומ\"צ כנ\"ל וד\"ל.\n<b>וז\"ש</b> ההופכי הצור אגם מים<sup data-n=\"471\">89</sup> כו' דמ\"ן דנוק' שהי' בבחי' גבורה רשפי אש נהפך למי החסדים כו', אבל אם אין תיקון ומיתוק הגבו' דרצוא להתהפך לשוב אלא הי' הכל בבחי' רצוא מסתעף מזה ב' דברים א' שאין אור השפע דחסדים דנה\"י דאבא מתקבל בבינה כלל כמו אם לא הי' המקבל עוצר בחי' הרשפי אש של התשוקה בעצמו בשביל לקבל לא הי' התחלת קבלת השפע כלל, וכן אפי' כשמקבל השפע בעצמו מצד שעצר רשפי אש התשוקה כנ\"ל כ\"ז שלא נתקבל השפע דמשפיע בכל פרטי המקבל לפעול התהפכות הרצוא עצמו לשוב אין זה נק' קבלת השפע כלל, וממילא יסתעף שיסתלק אור התפעלו' ההשגה דבינה ליבא הנ\"ל ויפול הנופל בבחי' גבורות קשות דאש זרה היפוך המנגד לגבו' דקדושה (והיינו פר\"ש חגיכם<sup data-n=\"472\">90</sup>",[["469","87","<b>אש אכלה אש</b>: תרגום יונתן וירושלמי ואתחנן ד, כד."],["470","88","<b>חו\"ג</b>: ב: חו\"ב."],["471","89","<b>ההופכי הצור אגם מים</b>: תהלים קיד, ח. ראה גם שער האמונה ק, ב."],["472","90","<b>פר\"ש חגיכם</b>: מלאכי ב, ג. ראה זהר יתרו פח, ב. מאמרי אדה\"א דברים ח\"ג ע' א'קיח. וש\"נ. תו\"ח כאן קכ, ג הערה 291."]]],[4801940492,"שהחג הוא התלהבות<sup data-n=\"473\">91</sup> השמחה ברצוא בהשגה דבינה שמתהפכת ונמתקת בחסדים דאבא להתהפך ממעל להמשפיע<sup data-n=\"474\">92</sup> עד שהגבו' עצמם<sup data-n=\"475\">93</sup> נהפכים לבחי' חסדים ואז יש בבחי' החסדים תוקף יותר שהמה נמשכים מלמעלה למטה בתגבורת אש המשפיע<sup data-n=\"476\">*94</sup> (כמו נהר דינור כו' וד\"ל), וזהו בחי' ח\"ג ר\"ת חסד גבורה<sup data-n=\"477\">94</sup> שעיקרו הוא מבחי' חסד וגוונין סומקין אתחזו בי' שהוא תגבורת השפע כו' וד\"ל. ולכן צריך למחדי למסכנא<sup data-n=\"478\">95</sup> שהוא ענין השפעה מלמעלה למטה אבל כאשר לא חדי למסכני זה מורה שלא נמתקו הגבורות דרשפי אש דרצוא ושוב<sup data-n=\"479\">96</sup> ותשוקה שלו בבחי' השוב כביטול דאבא ולכן יכול להיות ממנה המשכת יניקה לחיצוני', וזה פרש חגיכם כמ\"ש במ\"א. וכן אנו רואים בחוש גם בכל מי שטעם טעם בעבודת ה' במוח ולב ברשפי אש התשוקה שנק' שלהבת י\"ה<sup data-n=\"480\">97</sup> ממש שהוא בחי' התכללות התפעלות רשפי אש התשוקה בעומק המושג דבינה וראי' בהשכלה דחכ' שנק' הלב רואה<sup data-n=\"481\">98</sup> ומבין<sup data-n=\"482\">99</sup> שאם לא יבוא לכלל ביטול דבחי' שוב בשפלות עצמות עד שיתבטל התלהבות שלו כמו וירא העם וינועו<sup data-n=\"483\">100</sup> כו' (שזהו ע\"י בחי' קבלת השפע דראי' דחכ' בכל הפרטים דהשגה דבינה שנק' יחוד כנ\"ל) אזי יפול מיד בגסות והגבהת הלב ובהמשכות חום תאוות רעות כו' וד\"ל. וכן ברוחני' העבודה בחי' האות וסימן על היחוד דביטול דחכ' בהשגה דבינה בכל הפרטי' שזהו בחי' שפלות עצמו היא כאשר רדיף בתר חייבא<sup data-n=\"484\">101</sup> להחזירו בתשובה וחדי למסכני שהוא בחי' העני בדעת<sup data-n=\"485\">102</sup> להשפיע אליו השגות אלקי' כנ\"ל במע\"ט<sup data-n=\"486\">103</sup> בגשמי' כו'.\n<b>והנה</b> כל הנ\"ל בבחי' ביטול רשפי אש מלמטה למעלה לעצור הצימאון ומלמעלה למטה להפוך הרצוא עצמו לשוב הכל הוא [ב]בחי' דעת תחתון הכולל חו\"ג<sup data-n=\"487\">104</sup> שהוא בחי' דעת של המקבל הפועל ב' בחי' הנ\"ל מצד חו\"ג שבו כנ\"ל, (אך גם בחי' דעת של המקבל שהוא בחי' יסוד אימא הוא ג\"כ מכח המשפיע שהוא בחי' יסוד אבא כנ\"ל שזהו בחי' עשיית הכלי דמ\"ן שנעשה מצד המשפיע כמ\"ש אין האשה כורתת ברית<sup data-n=\"488\">105</sup> אלא למי שעשאה כלי כו'). אך יש בחי' דעת<sup data-n=\"489\">106</sup> שהוא בחי' יסוד",[["473","91","<b>שהחג הוא התלהבות</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתי. וש\"נ. תו\"ח בא ח\"א קג, ב הערה 308."],["474","92","<b>ממעל להמשפיע</b>: ב: ממקבל למשפיע."],["475","93","<b>עצמם</b>: שם: רשם על תיבה זו יתיר."],["476","*94","<b>אש המשפיע</b>: שם: רשפי אש להשפיע."],["477","94","<b>חג ר\"ת חסד גבורה</b>: ראה זהר רע\"מ פינחס רנה, ב. סידור ברכת נשואין קלז, ג. מאמרי אדמו\"ר האמצעי דרושי חתונה ח\"ב ע' תקפד."],["478","95","<b>למחדי למסכנא</b>: זהר שבהערה 90. סידור סדר סעודת שבת רא, א ואילך."],["479","96","<b>ושוב</b>: ב: ליתא."],["480","97","<b>שלהבת י\"ה</b>: שה\"ש ח, ו."],["481","98","<b>הלב רואה</b>: קה\"ר פ\"א טז, א. ראה גם מאמרי אדה\"א שמות ח\"א ע' כ. ח\"ב ע' תנז."],["482","99","<b>הלב. . ומבין</b>: ברכות סא, א. ראה גם מאמרי אדה\"א שמות ח\"א שם."],["483","100","<b>וירא העם וינועו</b>: יתרו כ, טו."],["484","101","<b>רדיף בתר חייבא</b>: ראה זהר תרומה קכח, ב."],["485","102","<b>העני בדעת</b>: ראה כתובות סח, א. נדרים מא, א."],["486","103","<b>במע\"ט תיבה זו איננה ברורה. ב</b>: בי\"ט ביום טוב."],["487","104","<b>דעת. . הכולל חו\"ג</b>: ראה ע\"ח שער תיקון הנוקבא של\"ד, פ\"ג. מאמרי אדה\"א בראשית ע' ד. וש\"נ. תו\"ח וארא ח\"א נז, ד הערה 14."],["488","105","<b>אין האשה כורתת ברית</b>: סנהדרין כב, ב."],["489","106","<b>דעת</b>: ב: ד\"ע."]]],[4801940524,"המשפיע עצמו שכלול ג\"כ מחו\"ג ע\"ד הנ\"ל בדעת של המקבל, והוא מה שאנו רואים כמו\"כ מן המשפיע אל המקבל צריך להיות [ב]בחי' קרירות וביטול היפוך התפעלות רשפי אש, כמו שאנו רואים בכל משפיע שכל או מוסר לתלמיד שכאשר ידבר בהתפעלות ברשפי אש בקול רם לא יוכל ל[הת]קבל לנכון, רק כשמדבר בנחת דווקא כמ\"ש חכם באחור ישבחנה<sup data-n=\"490\">107</sup> בבחי' אחוריים ישבחנ\"ה יבוא למקבל בבחי' תיקון ושלימות הקבלה, וכן אמרו דברי חכמים בנחת נשמעים<sup data-n=\"491\">108</sup> בנחת דווקא נשמעים ומתקבלים למקבל וכו', וזהו בחי' חו\"ג שביסוד המשפיע שהוא במוחו ובלבו במוחו הוא בחי' צמצום השפע לא להשפיע ריבוי שפע השכל יותר מכפי כלי המקבל זהו בחי' הגבורות שבו ובחי' החסדים הוא המשכת השפע כפי הצורך ולא לצמצם יותר מכפי המדה וזהו בחי' חכם באחור הנ\"ל, שזהו במוח בינה של המשפיע. ומש\"א דברי חכמים בנחת נשמעים זהו בבחי' מקיף המשכת חו\"ג הנ\"ל בלב של המשפיע והיינו לצמצם ולעצור רשפי אש התשוקה להשפיע שלא תהי' בבחי' תגבורות יותר מכפי המדה זהו בחי' גבורות, והחסדים הם המשכות רשפי אש בהשפעה בבחי' העלם עכ\"פ בכדי שיהי' ההשפעה בבחי' חיות ובא\"ל לא יהי' חיות בהשפעה ולא יתקבל במקבל.\n<b>ואעפ\"י</b> שלפעמים אמר שדברים היוצאים מן הלב<sup data-n=\"492\">109</sup> דווקא בהתפעלות רשפי אש נכנסי' בכלי של המקבל, היינו להיות התפעלות הלב אבל להתקבל במוח בינה דבר חכ' (שזהו קבלת וקליטת השפע בבחי' פנימי משא\"כ התפעלות רשפי אש הפועל התפעלות רשפי אש בכלי המקבל הוא בחי' שפע בבחי' מקיף בלבד על המקבל כו' וד\"ל) דווקא בנחת נשמעים, וגם מוסר ברך מקבל יותר מבקשה ולפעמים בקשה יותר כדי לעשות בו כלי (שזהו מה שאור המקיף מזכך חצי הכלי מבחוץ<sup data-n=\"493\">110</sup> כו' וכמו במ\"ת שהי' קולות וברקים<sup data-n=\"494\">111</sup> שזה הי' לעשות בהם בחי' הביטול להיות כלי קיבול כו'). או אפשר לומר שגם [ב]דברי חכ' דברים היוצאים מן הלב דווקא מתקבלים במקבל, אך שתהי' ההתפעלות רשפי אש שבהשפעה בעומק יותר עד שיוכל לעצור רשפי אש ההתפעלות שלא תהי' במורגש וזה מורה דווקא על תוקף תגבורות ההתפעלות שהוא בחי' אש אכלה אש כנ\"ל במקבל כו' וד\"ל. ושרש הדברים הנ\"ל מה שבחי' ההשפעה בבחי' מקיף בא ע\"י תגבורות ההתפעלות דווקא והשפעה שבבחי' פנימי' מוכרח להיות בקרירות ובחשאי דווקא, והיינו להיות ההשפעה שבבחי' מקיף הוא כפי סדר ההשתלשלות שרק חיצוני' שבעליון נעשה פנימי' לתחתון<sup data-n=\"495\">112</sup> ופנימי' העליון נשאר בהעלם בבחי' מקיף ושרש ההשתל' הוא",[["490","107","<b>חכם באחור ישבחנה</b>: משלי כט, יא [ושם: וחכם — ראה תו\"ח כאן הערה 28]."],["491","108","<b>דברי חכמים בנחת נשמעים</b>: קהלת ט, יז."],["492","109","<b>שדברים היוצאים מן הלב</b>: ספר הישר לר\"ת שי\"ג. הובא של\"ה שער האותיות אות כ (סט, א). שירת ישראל לר' משה בן עזרא (ירושלים תשכ\"ז ע' קנו)."],["493","110","<b>שאור המקיף מזכך. . מבחוץ</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"ב. לקמן מאמר ד\"ה וספרתם תקצ\"ח הערה 113."],["494","111","<b>במ\"ת שהי' קולות וברקים</b>: יתרו יט, טז. ראה תו\"ח כאן הערה 32."],["495","112","<b>חיצוני' שבעליון נעשה פנימי' לתחתון</b>: ראה ע\"ח שער א\"א שי\"ד, פ\"ט. לקו\"ת שלח מא, ד ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ח ח\"א ע' תלז ואילך."]]],[4801940551,"מבחי' מדות שברצה\"פ שהוא בחי' חו\"ג שבו, אבל שיתקבל פנימי' העליון בתחתון בפנימיותו זהו מכח עצמו' הרצה\"פ שלמע' מחו\"ג שבו, וכח זה מתלבש בבחי' דעת כנ\"ל, שהוא בחי' ביטול רשפי אש של המדות כו' וד\"ל.\n<b>והנה</b> כל הנ\"ל הוא בחי' נה\"י דאבא שנמשך [מ]בחי' יחוד דאו\"א שהוא בכל יו\"ט וגם ב[כל] יו\"ט דפסח בכל הז' ימים שבו, שאין ההשפעה בזו\"נ מקור[י ד]נש\"י כנ\"ל רק מבחי' נה\"י דאבא שבאים בשביל המשכת מוחין דאימא שנק' מקרא קדש שזהו ע\"י הביטול והתהפכות הרצוא עצמו לשוב שזהו מצד התגברות החסדים דאבא הנמשכים ע\"י נה\"י דאבא ומתחברים ומתייחדים עם גבו' דאימא עצמו<sup data-n=\"496\">113</sup> עד שנמתקין ומתהפכין לחסדים ובשבת מאיר ג\"כ רק מבחי' נה\"י דאבא, אך בשבת מתגלים נה\"י דאבא לצורך השפעת מוחין דאבא עצמו ע\"י יחוד דאו\"א שזהו בחי' הביטול דשוב עצמו שהוא בחי' ביטול בעצם מצד אא\"ס עצמו שלמע' מהשתל' וכמ\"ש אז תתענג על הוי'<sup data-n=\"497\">114</sup> למע' משם הוי' שבהשתל', וכידוע ההפרש בין עונג לשמחה כו' שבחי' העונג הוא מצד הביטול לאור האלקי עצמו עד שאינו תופס מקום כלל [בו] בחי' הביטול של הנבראים כלל<sup data-n=\"498\">115</sup> ובחי' השמחה הוא מבחי' הביטול של כל הנבראים באור האלקי השופע בהם כו'. אך כל הנ\"ל הוא בחי' נה\"י דאבא שמתגלים בהם הארת כל הי\"ס אפי' מבחי' הג\"ר אבל אינו מתגלה רק הארתן בלבד, אבל בחי' קטנות דאבא שהוא בחי' מצה הגם שבא בקטנות הרבה יותר אפי' מבחי' נה\"י דאבא שזהו בחי' נה\"י דנה\"י, אבל היא הנותנת שמלובש בזה ממהות ועצמות דג\"ר דאבא שלמע' מבחי' גילוי אור שלהם כנ\"ל.\n<b>וביאור</b> הענין להבין ההפרש בין בחי' נה\"י לנה\"י דנה\"י הוא כידוע שהמשל בזה הוא ממשארז\"ל אין התינוק יודע לקרות<sup data-n=\"499\">116</sup> אבא ואימא עד שיטעום טעם דגן דווקא וידוע ענין מה שיודע התינוק לקרות אבא כו' ידיעה זו אינ[ה אצלו] בדרך ידיעת שכל ודעת<sup data-n=\"500\">117</sup> כלל שהרי אינו משכיל ומבין בדעתו איך שהוא אביו בתולדה וגם איך שזנו ומפרנסו ומלבישו כו', רק שעכ\"ז קוראו אבא בלא טעם ודעת כלל שממילא ומעצמו קוראו בלשון זה בפה דווקא ואעפ\"כ קריאה זאת אינה בחיצוני' בלבד רק הוא בכל פנימי' ועצמי' נפשו להיות נמשך אחריו בכל לב ונפש. והטעם לזה הוא להיות כי קריאה זאת בא מצד טבע התולדה בעצם שלמטה<sup data-n=\"501\">118</sup> מן הטעם לגמרי, כי הנה ידוע ההפרש בין כל כחות הנפש הקבועים ונטועים בעצם הנפש כמו כח השכל וכח האה' כו' ובין כח המוליד שבנפש<sup data-n=\"502\">119</sup>, כי הנה כל כחות הנפש שרשם אינו רק בבחי' גילוי אור הנפש שראשיתם הוא בחי' התענוג שבנפש עצמו, ואפי'",[["496","113","<b>עצמו</b>: ב: ליתא."],["497","114","<b>אז תתענג על הוי'</b>: ישעי' נח, יד. ראה גם לקמן ד\"ה וספרתם תרי\"ב ובהערה 31."],["498","115","<b>כלל. . כלל</b>: כ\"ה בהכת\"י."],["499","116","<b>אין התינוק יודע לקרות</b>: ראה ברכות מ, סע\"א. מאמרי אדה\"א דברים ח\"א ע' רמה. וש\"נ. תו\"ח בא ח\"א צה, ב. וש\"נ."],["500","117","<b>ודעת</b>: ב: וטעם."],["501","118","<b>שלמטה</b>: שם: שלמעלה."],["502","119","<b>כל כחות הנפש. . כח המוליד</b>: ראה גם שער האמונה נג, ב."]]],[4801940570,"בחי' עונג פשוט הבלתי מורכב בדבר נבדל כמו שעשועי' העצמי' שמשתעשע מכח ויכולת חכמתו שבעצמי' [נפשו] שלמע' מהתחכמות בדבר מה הנק' עונג מורכב כו', ואפי' מה שמשתעשע מעצמו' נפשו בכלל שלמע' [מ]שעשועי' בעצמו' כחות נפשו הכל הוא בחי' גילוי אור הניתוסף על העצם של הנפש ממש, אבל עצמי' הנפש ומהותה ממש הוא למעלה לגמרי מדבר<sup data-n=\"503\">120</sup> וסוג גילוי אור כלל.\n<b>והנה</b> שרש גילוי אור הנפש בא מבחי' האותיות שבנפש שהוא בחי' כ\"ב<sup data-n=\"504\">121</sup> תנועות להתנענע מהעלם עצמותה לבוא לכלל גילוי אור כו', ואותיות אלו נק' אותיות הכתובים שבנפש כדוגמת אותיו' הכתב למטה שבאים מדבר נבדל הניתוסף על העצם ומתאחדים עמו אבל אינו [עמו] בבחי' יחוד בעצם כו', אבל בחי' אותיות החקוקי' שבנפש הוא כמו שחוקק באבן שהחקיקה אינו מדבר נבדל רק מיני' ובי', כ\"ה בנפש התעוררות הנפש לבוא בגילוי כמ\"ש בהעלם עצמותה ממש הנה בחי' זאת נק' כח המוליד בנפש שבחי' זאת לא תוכל לתפוס רק בבחי' היותר אחרונה שבנפש שהוא בבחי' הדומם שבו, ובחי' זאת דחיבור כח היותר אחרון שבנפש לבחי' המהות והעצמות שבנפש שלמעלה מגילוי אור נק' בשם עלי' ולא בחי' המשכה מגבוה לנמוך כמו בחי' גילוי אור הנפש כו', וזהו בחי' עלה ברצונו המורגל בלשון המקובלים<sup data-n=\"505\">122</sup> כי בחי' העלי' שברצון הוא בחי' סיבה עצמי' בנפש הפועל בחי' גילוי הרצון בו וסיבה זאת היא עלי' בחי' היותר אחרונה בנפש לעצמו' הנפש כו' כנ\"ל וד\"ל. ובחי' זאת נק' אותיות החקוקים כו' ומבחי' זאת בא ונמשך בחי' כח המוליד שהוא להוליד ולהמשיך כח עצמי' הנפש בגשמי' דווקא, ולכן ראשית גילוי כח הזה הוא בגוף הוא בבחי' המוחין<sup data-n=\"506\">123</sup> בגשמיות המוחין דווקא ומשם נמשך בהגשמה דרך ח\"י חוליות השדרה ומשם דרך היסוד בבטן הנוק' עד שמוליד ולד בגוף נפרד כו'.\n<b>ולכן</b> יש ג\"כ בוולד הנולד בחי' התקשרות בטבעו מלמטה למעלה והיינו מתכלית ההגשמה שבו שהוא כמ\"ש מלובש בגשמי' גופו לתכלית הרוחני' שהוא פנימי' ועצמות הנפש דאב<sup data-n=\"507\">124</sup> דווקא, ולכן מתלבש התקשרות זאת בבן במוח ג\"כ בהגשמת המוחין שהוא בחי' הכרה חיצוני' כהכרת השור וחמור שזהו בחי' נה\"י דנה\"י, דהיינו שנתעלם הארת המוחין לגמרי מכל וכל עד שאינו אלא בבחי' הכרה בלבד (משא\"כ בחי' נה\"י עצמו יש בהם הארת המוחין בגילוי<sup data-n=\"508\">*125</sup>, וכן מתלבש אח\"כ התקשרות זאת גם בדיבור בבחי' היותר אחרונה שבדיבור שהוא בחי' הקריאה בלשונו בלבד [בלי טעם כלל, אך התקשרות זאת אינה למטה מהטעם רק להיותה בבחי' העצמי' לזאת הוא למעלה מכל טעם, כי שרש היותר ראשון של טעם ושכל הוא בחי' העונג העצמי' שהוא ג\"כ רק בחי' גילוי אור בלבד] כנ\"ל, אבל קריאה זאת",[["503","120","<b>מדבר</b>: ב: מגדר."],["504","121","<b>האותיות שבנפש. . כ\"ב</b>: ראה אגה\"ק ס\"ה. תו\"ח שמות ח\"א לב, א ובהערה 246."],["505","122","<b>עלה ברצונו. . המקובלים</b>: נסמן לעיל הערה 62."],["506","123","<b>כח המוליד.. בבחי' המוחין</b>: ראה לקמן הערה 174."],["507","124","<b>דאב</b>: ב: דאם."],["508","*125","<b>בגילוי</b>: אוצ\"ל: בגילוי)."]]],[4801940585,"הוא מצד התקשרות עצמות ומהות נפשו בעצמות ומהות נפשו דאביו ולזאת לא תוכל להתלבש בבחי' טעם וגילוי אור. ולכן גם מה שאח\"כ כשיגדיל בשנים וקוראו אבא מצד השכל וטעם שמבין איך שהוא אביו בתולדה כו', אין זה עיקר בקריאה זאת רק טפל כי העיקר הוא עצם טבע הבן שנמשך אחר אביו ואמו המולידים אותו וע\"כ שוה אצלו קריאה זו בקטנות[ו] כמו בגדלות[ו] ממש להיות שקריאה זו בלשונו דווקא שהוא כח היותר אחרון שבכחות נפשו (שהוא בחי' נה\"י דנה\"י שבדיבור כו' וד\"ל) הוא בא רק מצד ההכרה וההרגשה שמכיר ומרגיש מעצמו וטבעו (שהוא בחי' עצמות נפשו ממש שלמע' אפי' מבחי' התענוג העצמי שבנפש כנ\"ל) שהוא אביו כו' ע\"כ הוא נמשך אחריו דווקא בכל לב ובכל נפש כנ\"ל, ולא לאחר זולתו שלא יקראנו אבא כו'. [כי] כל דבר נמשך לשרשו<sup data-n=\"509\">125</sup> ו[ל]מקורו דוקא מצד עצם הדבר כמו שהוא ממש ולא מצד השכל וטעם כמו המשכת הניצוץ אחרי השלהבת שאין בזה טעם ושכל כלל רק מצד עצם טבעו על שממנו לוקח, ומה שישכיל ויבין בזה מצד הידיעה בשכל שהוא אביו המולידו אינו רק כמוסיף על עצם הדבר שבחי' זאת נמשך מצד הרצון באב להיטיב לבנו לזונו ולפרנסו, ומצד זה נמשך בחי' רצון בבן להיות נמשך אחריו ויכול להתבטל בחי' רצון זה כשלא ייטיב עמדו וכה\"ג, אבל מה שהוא מצד העצם בלתי הרכבה לא בטעם ושכל ולא ברצון לא יבוטל לעולם כי כל עצם בלתי משתנה<sup data-n=\"510\">126</sup> כלל<sup data-n=\"511\">127</sup> כו' וד\"ל. ונמצא שמה שהוא יודע ומכיר את אביו לקרותו אבא ונמשך אחריו אעפ\"י שאינו רק בחי' קריאה בעלמא הרי בזה דווקא להיותו [ה]כח היותר אחרון מלובש כל בחי' עצמות השפע דאביו שיש בטבע התולדה שהולידו מכחו וראשית אונו<sup data-n=\"512\">128</sup> (שזהו כח היותר ראשון הסיבה לבחי' התעוררות הנפש בעצמו בבחי' רצון להחיות שהוא בחי' עליות הרצון כנ\"ל), והוא למעלה הרבה מן השכל ו[ה]טעם שמשכיל ומבין בזה עצמו אחר שיגדל כו', רק שבא בהתלבשות והעלם ביותר בקריאה והמשכה זו שנמשך אחריו וקוראו אבא בלשונו בלבד בלי טעם ושכל כלל רק שמלובש בזה בחי' ההכרה בלבד שהוא בחי' הקטנות דנה\"י דנה\"י שבחכ' כנ\"ל, אבל בזה מלובש מעצם הדבר ממש כמ\"ש שהיא כח עצם התולדה שמעצמו' אביו כו'.\n<b>והנה</b> עיקר ההפרש בין שפע זאת דכח התולדה לכל מיני שפע, כמו שפע שכל מרב לתלמיד וכעשיר לעני וכה\"ג שנק' שפע דעילה לעלול הוא בזה שכל שפע דעילה לעלול אינו בא מעצמות המשפיע למקבל רק גילוי אורו בלבד, וכל בחי' גילוי אור לא יוכל ל[י]משך [מ]משפיע [ל]מקבל כמ\"ש רק ע\"י צמצום עצמות אור המשפיע [עד שלא יומשך רק בחי' אחרונה שבו שהוא הארתו וזיוו, שאינו שייך לעצמו כלל ונק' בחי' זאת בחי' נה\"י דמשפיע כו', וגם בחי' השפע דנה\"י דמשפיע שהוא בחי' נה\"י שבו נמשך ע\"י צמצום הזיו] עד שלא יומשך רק הארה דהארה, וכן",[["509","125","<b>כל דבר נמשך לשרשו</b>: ראה גם מאמרי אדה\"א נ\"ך ע' תצא. וש\"נ. תו\"ח בא ח\"א צה, ב הערה 408."],["510","126","<b>כל עצם בלתי משתנה</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' תעד. וש\"נ. תו\"ח וארא ח\"א עח, ב. וש\"נ."],["511","127","<b>כלל</b>: ב: ליתא."],["512","128","<b>מכחו וראשית אונו</b>: ע\"פ ויחי מט, ג. תצא כא, יז."]]],[4801940596,"בהעלאה אין העלאת המקבל מגיע רק לחיצוני' שפע זו דמשפיע ולא לעצמות ומהות המשפיע כלל. וכן אפי' [השפע] שממשפיע<sup data-n=\"513\">129</sup> למקבל שאינו חוץ ממנו כמו המשכת חיות הנפש בגוף<sup data-n=\"514\">130</sup> בעשר כחות דשכל ומדות שבמוח ולב, הנה המשכת השכל במוח הוא רק הארה דהארה מצומצמת מעצמות מקור השכל הנעלם כמ\"ש קודם שבא לכלל גילוי שכל, וכן בחי' [ביטול] ההעלאה דחומר המוח המקבל את השכל שזהו בחי' ביטול דחומר המוח שנעשה ע\"י יגיעת המוח לא יגיע רק לחיצוני' כח ומקור השכל כידוע<sup data-n=\"515\">131</sup> שהוא בחי' הארתו וזיוו בלבד. משא\"כ כח התולדה דאב המלובש בבן שבא מעצמות ופנימי' נפש האב שהוא מהותה ועצמותה שלמעלה מגילוי אורה, וכל עצם אינו מתחלק<sup data-n=\"516\">132</sup>, ולכן אינו שייך בו צמצום כלל רק תפיסתו אפי' בפרט אחד בלבד היא תופסת כל העצמי' ולכן אעפ\"י שהבן הוא פרט אחד בלבד מאביו (שיכול להוליד כמה בנים לאין שיעור כו') מ\"מ נתפס בו [כל] עצמות ופנימי' דנפש אביו כמ\"ש ולא [ב]בחי' צמצום רק בבחי' הלבשה בהעלם. וכ\"ה בבחי' ההעלאה שהוא בחי' קריאת התינוק לאביו ואמו בשם אבא או אימא וכן ההמשכה שנמשך אחריהם בקריאה זאת בכל לב ונפש מגיע לעצמו' אביו ואמו, להיות [ש]בקריאה והמשכה זאת מלובש מעצמות נפש דאביו ואמו דווקא. ואעפ\"י שאינו בא מצד השכל וטעם כלל ולא בהתפעלות הלב רק קריאה והכרה לבד, מ\"מ היא הנותנת שמלובש בזה כל העצמות והמהות כי כל הגבוה יותר לא יוכל להתלבש רק ביותר נמוך<sup data-n=\"517\">133</sup> שהוא בחי' הדומם שבדומם היותר אחרון כנ\"ל בענין אותיות החקוקים שהמה בבחי' הגשם הדומם דווקא כו' וד\"ל.\n<b>אך</b> הנה לכאורה יש להבין כיון שכח המוליד הוא בא מעצמות ופנימי' הנפש דאב [ו]לכן לא תוכל להתלבש רק בבחי' היותר אחרונה שבו א\"כ למה אנו רואים שכל כח ה[ה]ולדה הוא מן המוחין דווקא שהם בחי' ראש ומקור לכל אברי הגוף, וגם בתינוק הי' צריך להתלבש בחי' המהות רק בקריאה בלשונו בלבד שהוא בחי' הדיבור בחי' היותר אחרונה שבנפשו, אבל באמת מתלבש בבחי' הכרה שבמוח שהוא בחי' היותר אחרונה דמוחין ומשם בא לבחי' קריאה בפה כו'. אך הענין יובן בהקדם שכל בחי' השפעה ממהות למהות א\"א להיות כ\"א ע\"י ממוצע שהוא בחי' החכ' והטעם לזה להיות שבחכ' נתפס שני הפכים דאין ויש כא', שמצד פנימיות [שבה] הוא בחי' אין להיותה נכללת בבחי' האין דכח המשכיל ממש ומצד חיצוני' שבה שהוא בחי' ברק המבריק<sup data-n=\"518\">134</sup> תמצא מאין ליש דווקא, לזאת היא ממוצעת להמשיך מאין ליש,",[["513","129","<b>שממשפיע</b>: אוצ\"ל: שמשפיע."],["514","130","<b>בגוף</b>: ב: ליתא."],["515","131","<b>כידוע</b>: שם: ליתא."],["516","132","<b>וכל עצם אינו מתחלק</b>: ראה פלח הרמון וירא נח, א בשם הבעש\"ט [ראה כש\"ט קה\"ת סקי\"א. ובהוספות שם במהדורת תשנ\"ט סרכ\"ז ובהנסמן שם]. מאמרי אדה\"א דברים ח\"ג ע' תתכד. וש\"נ. לקמן מאמר ד\"ה אם בחוקותי הג' על יד הערה 138. לקוטי ביאורים — לשער היחוד קה\"ת — קפג, א ובהערה 1."],["517","133","<b>כל הגבוה. . ביותר נמוך</b>: ראה ש\"א שער הפורים נח, א. סה, א. תו\"ח שמות ח\"א כא, ב הערה 863. סה\"מ תרל\"ב ח\"א ע' קכב. וש\"נ. לקמן מאמר ד\"ה והניף הכהן תקפ\"ו על יד הערה 61."],["518","134","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק לקמן מאמר ד\"ה והניף הכהן אותם הב' הערה 54."]]],[4801940602,"ובחי' זאת דחכ' היא ממוצעת בין [ב]השפעת האור וזיוו מעילה לעלול כמו כחות הנפש שבעצמו' הנפש<sup data-n=\"519\">135</sup> [כאשר מתגלי' בגוף כנ\"ל, בין בהשפעת עצמי' ומהות הנפש לבא לכלל גילוי הכחות בעצמו' הנפש בבחי' גילוי אור, ואפי' גילוי כח היותר ראשון בעצמו' הנפש הנק' ששעשועי' העצמי' הוא ג\"כ ע\"י החכ', רק שחכ' זאת אינה נוגעת בנפש רק להביא אותה לכלל גילוי ולא לבחי' העצמי' ופנימי' שבה, משא\"כ בחי' חכ' שבעצמי' הנפש ממש שנוגעת בעצמי' ופנימי' הנפש להמשיך עצם המהות שבה שזהו בחי' כח התולדה שנמשך ג\"כ ע\"י החכ' דייקא, ולכן נק' הנפש בשם נפש המשכלת<sup data-n=\"520\">136</sup> ע\"ש שכל הנפש מלובש בבחי' החכ' העצמי' שבנפש עצמה ולכן] כאשר באה המשכה זאת בגוף מוכרח להיות שתתלבש בבחי' המוחין תחלה. אך להיותה השפעה עצמות ופנימי' לזאת התלבשותה בבחי' היותר אחרונה דמוחין שהוא בחי' גשם המוחין ואח\"כ נמשכת בכל אברי הגוף ג\"כ בבחי' הגשם ש[ב]הם עד שיוצאת בבחי' תולדה לחוץ ע\"י בחי' סיומא דגופא. וכן בתינוק מלובש בחי' התקשרות זאת [בבחי'] היותר אחרונה דמוחין שהוא בחי' ההכרה שבמוח ואח\"כ מתגלית בדיבור חיצוני' שבלי טעם כלל, ובחי' זאת נק' במוח בחי' נה\"י דנה\"י דחכ', כי באמת גם בבחי' נה\"י דחכ' יש חב\"ד חג\"ת נה\"י, ובחי' חב\"ד שבנה\"י היינו כאשר בא השכל לכלל גילוי אור להתקבל במקבל [שזהו בחי' נה\"י שבו בלבד כנ\"ל בענין כל שפע דעילה לעלול שאינו רק מבחי' אחרונה שבו, ובחי' חג\"ת דנה\"י היינו כאשר בא השכל לכלל גילוי אור להתקבל במקבל], אבל בחי' נה\"י דנה\"י היינו כאשר נתעלם השכל וההתפעלות שבו לגמרי עד שאינו מתגלה רק בחי' הקטנות שבו שהוא [בחי'] ההכרה בלבד כמו הכרת השור והחמור כו', אך בבחי' זו באדם מלובש כל עצמו' ומהות פנימי' הנפש כנ\"ל. וכן בדיבור הכח להתעורר להיות נמשך בדיבור הוא בחי' ג\"ר שבו וכאשר מתגלה בבחי' קול הוא בחי' חג\"ת שבו ועקימת שפתיו הוי' מעשה להוציא לחוץ דבורו הוא בחי' נה\"י שבו. אך בבחי' נה\"י דעקימת שפתיו יש ג\"כ בחי' חב\"ד חג\"ת, והיינו כאשר מדבר דברים מצד השכל והטעם נק' בחי' חב\"ד שבנה\"י שבדיבור, וכאשר מדבר דברים היוצאים מן הלב נק' חג\"ת שבנה\"י שבדיבור, אבל כשמדבר דברים בבחי' חיצוני' שלא מצד הטעם והתפעלות כלל כמו שיחה שאינו מגיע לעצמות נפשו כלל נק' בחי' נה\"י שבנה\"י שבדיבור. וכ\"ה עד\"ז הקריאה חיצוני' דתינוק שיודע לקרות אבא שזה[ו] כמו שיחה בעלמא שאינו נוגע לעצמו' הנפש אבל מ\"מ מלובש בזה כל העצמי' ומהות מצד טבע [ה]התקשרות דבן לאב שבא<sup data-n=\"521\">137</sup> מצד כח התולדה כנ\"ל וד\"ל.\n<b>והנמשל</b> מכל הנ\"ל<sup data-n=\"522\">138</sup> יובן למשכיל בענין שרש המצה הנק' בחי' קטנות דאור אבא שהוא מה שאומרים אבינו כו' וכמ\"ש כי אתה אבינו<sup data-n=\"523\">139</sup> וכה\"ג, וכמו שהי' בישראל בהיותם במצרים שלא הי' בהם רק בבחי' ההכרה שהכירו את בוראם כי",[["519","135","<b>הנפש</b>: בכת\"י זה נרשם בין השיטין: חסר, ובין בהשפעה עצמיות כמו כח המוליד כו'."],["520","136","<b>נפש המשכלת</b>: ראה תניא פ\"ג. פ\"ה. פל\"ג. פ\"נ."],["521","137","<b>שבא</b>: ב: ליתא."],["522","138","<b>מכל הנ\"ל</b>: ב: מכ\"ז. וכ\"ה בתו\"ח כאן."],["523","139","<b>כי אתה אבינו</b>: ישעי' סג, טז."]]],[4801940608,"הוא אבינו כו' כתינוק שנמשך אחר אביו מפני ההכרה בלבד ע\"כ קוראו אבא. והכרה זאת יש בה ג\"כ בחי' חו\"ג החסד הוא בחי' ההתקשרות לקרוא לאביו בשם אבא והגבו' הוא מה שמבחין ומבדיל בין אביו לזולתו שלא יקרא לזולתו אבא, אך ב' הבחי' דחו\"ג המה א' ממש ואינם נבדלים זמ\"ז כלל, כי מצד תוקף ההתקשרות לאביו נמשך כל העצמו' אחרי אביו וממילא לא יוכל לפרד ממנו איזה חלק להיות נמשך אחר[י] זולתו כי כל עצם בלתי מתחלק. משא\"כ האה' לאיזה דבר בבחי' גילוי אור יוכל חלק ממנו לתפוס בדבר אחר לאהוב ג\"כ דבר זולתו אפי' ההפכי, לכן מה ששונא לדבר ההפכי הוא כח אחר נבדל מכח האה' וא\"כ בחי' החו\"ג שבאה' זאת המה שני כחות נבדלים רק שמתאחדים כאחד. משא\"כ תוקף התקשרות העצם הוא בכל העצם וממילא לא יוכל להתקשר בדבר אחר זולתו כלל א\"כ כח הגבורה עם כח החסד הוא כח א' ממש כו' וד\"ל. וזהו מש\"א זכרתי לך חסד נעוריך<sup data-n=\"524\">140</sup> [חסד] דווקא שהוא בחי' התקשרות עצמית (שממילא ניכלל בזה בחי' גבורה לשנוא דבר אחר זולתו כו' וד\"ל<sup data-n=\"525\">141</sup> ), ונעורייך דווקא להיות שהתקשרות זאת אינו בא רק בתכלית הקטנות שהוא בחי' נה\"י דנה\"י דחכ' [ונה\"י דנה\"י] שבדיבור כנ\"ל וד\"ל. וזהו ג\"כ לכתך אחרי שהוא בחי' ההילוך בפו\"מ שהוא בחי' היותר אחרונה דנה\"י כנ\"ל, וגם הילוך זה הוא בבחי' אחוריים וחיצוני' בלי טעם ושכל כלל ונק' נה\"י דנה\"י וכן א' כי נער ישראל שהוא תכלית הקטנות כנ\"ל ואוהבהו<sup data-n=\"526\">142</sup> שבזה מלובש דווקא אה' העצמי' כו' וד\"ל.\n<b>והנה</b> בחי' זאת נתגלה בהם בליל פסח דמצרים ע\"י אכילת [ה]מצה שאכלו שם דווקא, והטעם לזה כי לכאורה יש בהם התקשרות זאת מצד עצם התולדה ולמה היו צריכים לאכילת מצה דווקא, אך הענין יובן ע\"ד אין התינוק יודע לקרות אבא [ואימא] עד שיטעום טעם דגן תחלה כי אעפ\"י שיש בו בהעלם בחי' התקשרות לאביו מצד כח התולדה מ\"מ אינו בא בגילוי כ\"א ע\"י טעימת טעם דגן דווקא, אבל מצד עצם כח חכמתו שבנפשו הצומחת מידי יום יום מהעלם אל הגילוי לא תתגלה [הכרה זאת בנפשו לקרות אבא כו', כי הנה ידוע בענין דצח\"מ שבחי' דומם למטה מהכל<sup data-n=\"527\">143</sup> וצומח למעלה מבחי' דומם ולכן יש בו אור וחיות יותר עד שניתוסף] בו על בחי' נפש המרכבת (שישנה ג\"כ בדומם כמש\"כ בליקוטי אמרים בשם האריז\"ל שגם בדומם<sup data-n=\"528\">144</sup> יש צירופי אותיות מעש\"מ המחי' ומהווה את הדומם כו') בחי' נפש הצומחת כו', וחי למעלה מצומח לכן ניתוסף בו נפש החיונית המתנוענעת כו', ומדבר יש בו חיות יותר לכן ניתוסף בו נפש המדברת כו'. וכן הוא למעלה ברוחני' די\"ס דמל' הוא בחי' דומם למטה מהכל ובחי' צומח הוא ו\"ק<sup data-n=\"529\">145</sup> דמדות למע' מבחי' המל' דדומם ובחי' חו\"ב הנק' חי הוא למעלה מצומח דמדות ובחי' החכ' בעצם שהוא למעלה מבחי' חו\"ב שנק' חכם בבינה<sup data-n=\"530\">146</sup> [כו'] הוא בחי' מדבר הוא למעלה",[["524","140","<b>זכרתי לך חסד נעוריך</b>: ירמי' ב, ב."],["525","141","<b>וד\"ל</b>: ב: כנ\"ל."],["526","142","<b>כי נער ישראל. . ואוהבהו</b>: הושע יא, א."],["527","143","<b>דומם למטה מהכל</b>: ראה גם לקמן מאמר ד\"ה הנה להבין המדרש והצרוע תקצ\"ט ובהערה 98."],["528","144","<b>בליקוטי אמרים. . בדומם</b>: שער היחוה\"א פ\"א."],["529","145","<b>ו\"ק</b>: ב: בחי'."],["530","146","<b>חכם בבינה</b>: ס\"י פ\"א, מ\"ד."]]],[4801940614,"מהכל. וכ\"ה בכללות העולמות בחי' עשי' הוא בחי' דומם ולמעלה ממנה עולם היצירה שהוא בחי' צומח ועולם הבריאה הוא בחי' חי ובחי' עולם האצי' הוא בחי' מדבר<sup data-n=\"531\">147</sup> הוא למעלה מהכל כו'.\n<b>וכ\"ז</b> הוא בסדר ההשתל' הבא ע\"י צמצום והעלם עצמות האור להיות נראה אור בבחי' הארה דהארה וכל שמתמעט האור יותר ע\"י ריבוי צמצומים הוא למטה יותר, אבל בבחי' העצמות שלפני הצמצום כאשר מתעורר לבוא לכלל גילוי אור מהעלם העצמי הוא להיפוך שכל מה שמתגלה האור יותר מהעלמו העצמי' הוא בבחי' ירידה יותר וכל מה שהוא בבחי' מיעוט האור וה[ה]תגלות הוא בבחי' קירוב לעצמו יותר. ולכן שם בחי' הדומם הוא למעלה מהכל<sup data-n=\"532\">148</sup> שזהו בחי' התעוררות העצמי' שבהעלם שנשאר בבחי' העלם לעולם ולא תבוא לידי גילוי אור כלל שזהו סומ\"ע שעלה תחלה למח' ורצה\"פ שעלה ברצונו להיטיב כנ\"ל, וע\"ז נאמר במי נמלך בנשמתן של צדיקים. ואח\"כ מה שעלה ברצונו הפשוט<sup data-n=\"533\">149</sup> להיטיב היינו להיות טוב ואור גילוי<sup data-n=\"534\">150</sup> שזהו בחי' גילוי העלם העצמי', רק שהגילוי הוא לעצמו עדיין שלא בגדר מקום<sup data-n=\"535\">151</sup> להשתל' הוא הנק' בחי' צומח [וזהו] בחי' רב חסד שבעצמות השעשועים<sup data-n=\"536\">152</sup> כו'. ומה שנתלבש בחי' עונג ושעשועים אלו בבחי' חפץ חסד<sup data-n=\"537\">153</sup> להיות מקור להשתל' שזהו נק' בחי' חסד עולם שבעצמו' היינו שעלה ברצונו להיטיב גילוי אור הזה [שהוא בחי' השעשועי' העצמי' לברואיו דווקא והיינו להלביש גילוי אור הזה] במקור ההשתל' זהו נק' בחי' חי שהוא בחי' תנועה ממקום למקום, אך למעלה הוא בחי' מלמע' מגדר מקום להיות מקום אתי<sup data-n=\"538\">154</sup> שהוא בחי' מקום הטפל ובטל אתו. ואח\"כ בחי' חפץ חסד הזה נתעורר לבוא לידי גילוי בפ\"מ ההתלבשות<sup data-n=\"539\">155</sup> שזהו בחי' מל' דא\"ס גילוי הזיוו מן האור העצמי', ועוד שיער בעצמו בחי' גילוי הזיוו הזה איך יבוא בפועל ההשתל' שכבר [ה]וכן כל ההשתל' באיזה אופן יבוא בפועל רק צריך להיות בחי' צמצום כו' (ועיין בשעה\"י פ'<sup data-n=\"540\">156</sup> ) וזהו בחי' האותיות דגליף גליפו בטה\"ע<sup data-n=\"541\">157</sup> זהו בחי' מדבר שבעצמו' והוא למטה מכל המדריגות שבהעלם העצמו' כו'.\n<b>ועד\"ז</b> יובן בנפש הגוף שכלול מכל הבחי' דדצח\"מ שיש בו הפרש בין העלם לגילוי שבבחי' הגילוי דהיינו כאשר באים כל כחות הנפש בבחי' התלבשות בגוף אז בחי' המדבר הוא למע' מהכל שהוא בחי' החכ' שבנפש, ואח\"כ בחי' [ה]חכ' המלובשת בהשגה שזהו בחי' חכ\"ם בבינה הוא בחי' ח\"י ובחי' המדות הוא בחי'",[["531","147","<b>עשי'. . אצי' הוא בחי' מדבר</b>: ראה סה\"ש ה'תשנ\"ב ע' 139 הערה 54. תו\"ח משפטים ח\"ב רצט, א. וש\"נ."],["532","148","<b>הדומם הוא למעלה מהכל</b>: ראה גם לקמן מאמר ד\"ה הנה להבין המדרש והצרוע תקצ\"ט ובהערה 99."],["533","149","<b>הפשוט</b>: ב: ליתא."],["534","150","<b>ואור גילוי</b>: שם: וגילוי אור."],["535","151","<b>מקום</b>: שם: מקור."],["536","152","<b>השעשועים</b>: ראה לקמן מאמר ד\"ה הפך ים תר\"א ע' עד. וש\"נ."],["537","153","<b>חפץ חסד</b>: מיכה ז, יח."],["538","154","<b>מקום אתי</b>: תשא לג, כא."],["539","155","<b>ההתלבשות</b>: ב: ההשתלשלות."],["540","156","<b>פ'</b>: שם: פ\"ו. ראה שם פ\"י."],["541","157","<b>דגליף גליפו בטה\"ע</b>: ראה זהר בראשית טו, א. לקמן מאמר ד\"ה אם בחוקותי הג' הערה 61."]]],[4801940619,"צומח ואותיו' מחדו\"מ המה בחי' דומם. אבל בעצמות הנפש כאשר מתעוררת לבוא בגוף סיבה ראשונה הנעלמת המעוררת אותה לבוא לכלל גילוי אור שזהו כח המפליא לעשות הוא בחי' הדומם ע\"ש שהוא נעלם בתכלית, ועצמי' גילוי אורה מהעלמה הוא בחי' צומח ומה שנתלבש גילוי אורה להיות בבחי' מקור להחיות זהו בחי' חי, ומה שמתעורר הכח ומקור להחיות מהעלם אל הגילוי בפ\"מ שהוא בחי' הזיו דאור הוא בחי'<sup data-n=\"542\">158</sup> מדבר כו'. והנה כח התולדה הוא מבחי' דומם שבעצמי' הנפש שזהו בחי' כח הא\"ס המפליא לעשות לפעול בנפש התעוררות בהעלם<sup data-n=\"543\">159</sup> לבוא לכלל גילוי אור עד שבא אור הזה בדרך השתל' להחיות הגוף, כן זה הכח עצמו מעורר בחי' הנפש להתעורר לבוא מהעלם עצמותה ולהתלבש בבחי' תולדה נבדלת, ואדרבה זה מורה על תוקף הכח הנ\"ל יותר כיון שפועל התלבשות עצמות הנפש בדבר נבדל. וכ\"ה במקבל מלמטה למעלה יש בחי' [ה]התקשרות בהעלם עצמות נפשו למקור המולידו מצד שממנו לוקח אך התקשרות זאת הוא בהעלם להיותה בבחי' עצמי', אך ע\"י טעם דגן שהוא בחי' צומח ושרשו בעצמו' הנפש להתעורר<sup data-n=\"544\">160</sup> יותר גבוה מבחי' מדבר היינו מבחי' צומח דשם שהוא עצמות גילוי אור ושעשועים המתגלה מהעלם עצמות הנפש לכן הוא פועל ג\"כ בחי' הכרה שהוא בחי' גילוי עצם התקשרות למולידו, אך להיותו בבחי' [ה]עצמו' לזאת לא יוכל לבוא כ\"א בבחי' גילוי המצומצם יותר שהוא בחי' הכתר<sup data-n=\"545\">161</sup> הנק' נה\"י דנה\"י בלבד כו' וד\"ל. ועד\"ז יובן ענין המצה שאכלו אבותינו במצרים שפעל בחי' גילוי ההתקשרות בנש\"י בבחי' עצמות עד שנמשכו אחרי הקב\"ה לצאת ממצרים, והמשכתם זאת היתה בכל לב ונפש למעלה מהטעם ודעת לגמרי מצד שנמשכה זאת ההתקשרות מעצמי' שרשם כמו שהם מקושרים מעצמי' ופנימי' אא\"ס מצד סו\"מ שעלה במח' תחלה, תחילה אפילו לשעשועי' העצמי', ומשם הוא שרש כח התולדה דנש\"י, והתגלות זאת ההתקשרות מצד שאכלו לחם דגן דמצה שהוא בחי' צומח ששרשו בשעשועים העצמי' שהוא בחי' גילוי אור עצמו המגלה העלם העצמי' ולכן נתגלה בחי' זאת ההתקשרות בנש\"י ע\"י לחם דמצה כו' וד\"ל.\n<b>אך</b> ג\"כ<sup data-n=\"546\">162</sup> אינו מובן למה נצטוו במצוות אכילת מצה דווקא שאין בה שום טעם כלל ולכן נק' לחם עוני<sup data-n=\"547\">163</sup> הלוא יותר הי' ראוי שיצטוו באכילת לחם פנג<sup data-n=\"548\">164</sup> ולהתענג בו בכדי לעורר עי\"ז שרשו שהוא בחי' שעשועי' העצמי' ועי\"ז יתגלה כח התולדה דעצמו' אוא\"ס בנפשם בבחי' גילוי אור, וכמו במשל בתינוק שיודע לקרות אבא מצד טעימת [טעם] דגן דווקא<sup data-n=\"549\">165</sup> שאינו תלוי בטעם מצה דווקא רק בטעם דגן מצד שרשו שהוא בחי' צומח כו' וד\"ל. אך הענין הוא שיש הפרש בין המשל לנמשל, כי הנה בגשמי' כח התולדה שהיא מעצמי' הנפש שלמע' מגילוי אורה העצמי' אעפ\"י",[["542","158","<b>הוא בחי'</b>: ב: והוא."],["543","159","<b>בהעלם</b>: שם: ליתא."],["544","160","<b>להתעורר</b>: שם: ליתא."],["545","161","<b>הכתר</b>: שם: הכרה."],["546","162","<b>ג\"כ</b>: שם: א\"כ."],["547","163","<b>מצה. . לחם עוני</b>: פ' ראה טז, ג. ראה גם מאמרי אדה\"א ויקרא ח\"א ע רצג. וש\"נ."],["548","164","<b>לחם פנג</b>: ראה זהר ויחי רלה, ב. רמו, א. תו\"ח שמות ח\"א כג, ב הערה 956."],["549","165","<b>דווקא</b>: ב: ליתא."]]],[4801940624,"שהיא בבחי' מאור שלמע' מאור, היינו מצד שרשה באיזה עולם שהוא, היא למעלה מבחי' גילוי אור שבעולם ההוא רק מבחי' המאור שבעולם ההוא, כמו נפש דעשי' שנלקחה מפנימי' הכלים די\"ס דעשי' שהמה למעלה מבחי' גילוי אור דעולם העשי' שהוא בחי' המל' דמל' דעשי', וכאשר עולה ברצונו להביאו בגוף אזי נפעל בנפש זאת בחי' ירידה והמשכה לבוא בבחי' גילוי אור ע\"י האותי' דמל' דעשי' במאמר נעשה אדם<sup data-n=\"550\">166</sup> וע\"י אלו האותיו' היא יורדת ג\"כ ומתלבשת בגוף כו', אבל כללות הי\"ס דעשי' ואפי' מקורם שהוא בחי' הכתר נמשך מבחי' המל' דיצי' שהוא בחי' גילוי אור דעולם היצי', נמצא שמה שהוא בבחי' עולם העשי' [ב]בחי' מאור למע' מאור הוא בבחי' עולם היצי' בחי' גילוי אור בלבד, וכ\"ה עד רום המעלות, ולכן ע\"י טעימת דגן ששרשו בשעשועים העצמי' הוא מעורר כח התולדה שבנפש להביאו לידי גילוי אור כו'. אבל שרש נש\"י שהוא בחי' הניצוץ האלקי שלמעל' משרש הנר\"ן שרשה בפנימי' ועצמי' העלם המאור דעצמו' אא\"ס שלמע' משעשועים העצמי' שאינו בגדר וסוג אור כלל, לזאת [לעורר] בחי' [העלם] העצמי לבוא לידי גילוי א\"א כ\"א ע\"י אכילת מצה דווקא הנק' לחם עוני דווקא שעי\"ז דווקא יוכל להתעורר בחי' העלם העצמי שבנשמה שנק' בחי' יחידה, ששרשה בהעלם העצמי דאא\"ס שלמע' מגילוי אור לגמרי שזהו בחי' אמונה הפשוטה שבכללות נש\"י שהוא למע' ממה שיש בכח כל נשמה להתענג על ה' בעונג ושעשועים [ה]עצמי' כו', ולכן נק' המצה מיכלא דמהמנותא<sup data-n=\"551\">167</sup> דווקא וד\"ל.\n<b>אך</b> איך יוכל לימשך גילוי אמונה הפשוטה ע\"י אכילת מצה שהוא ג\"כ רק בחי' צומח בלבד כו', אך הענין יובן בהקדם שרש<sup data-n=\"552\">168</sup> בבחי' צומח שני בחי' הא' בחי' צומח סתם שצומח מעפר הארץ שהוא בחי' דומם ואינו רק בחי' גילוי אור מבחי' העלם הדומם (שהוא בחי' כח הצומח שבהעלם עפר הארץ הוא בחי' דומם המצמיח כל מיני צומח בבחי' גילוי אור בלבד כו') [בלבד], אבל יש עוד בחי' צומח שבדומם עצמו שהוא מה מהדומם עצמו בא לידי צמיחה והתפשטות כמו הרים הגבוהים ואבנים הצומחים כו'. והנה לכאורה יש יתרון מעלה בבחי' צומח שבדומם במה שהדומם עצמו בא לכלל התפשטות משא\"כ בצומח סתם אינו רק בחי' גילוי אור דכח המצמיח כנ\"ל אבל באמת אנו רואין יתרון מעלה בצומח סתם מבחי' צומח שבדומם, והוא במ\"ש אשר זרעו בו<sup data-n=\"553\">169</sup> שניתן בו כח להצמיח עד אין שיעור ונמצא שנותן בו עצם כח המצמיח ממש [כמ\"ש בבחי' העלם עצמותו ממש], משא\"כ בצומח שבדומם אעפ\"י שעצם הדומם בא בבחי' צמיחה והתפשטות מ\"מ הוא התפשטות העצם (למעלה מבחי' התפשטות מן העצם כנ\"ל ) ולא העצם ממש כמ\"ש בבחי' העלם העצמי' ממש<sup data-n=\"554\">170</sup> כו'.",[["550","166","<b>נעשה אדם</b>: בראשית א, כו."],["551","167","<b>המצה מיכלא דמהמנותא</b>: ראה זהר רע\"מ בא מא, א. מאמרי אדה\"א ויקרא ח\"ב ע' תרלו. וש\"נ."],["552","168","<b>שרש</b>: ב: שיש."],["553","169","<b>אשר זרעו בו</b>: בראשית א, יא."],["554","170","<b>בבחי' העלם העצמי' ממש</b>: ב: ליתא. ראה לעיל בפנים בהחצאי ריבוע."]]],[4801940629,"<b>ובזה</b> יובן ענין אכילת מצה שנק' לחם עוני וכמו שאו' הא לחמא עניא די אכלו כו' עני מן הדעת כמו שאין במצה שום טעם כלל כידוע, לכן מלובש בה דווקא מעצמית כח התולדה דאב שהולידו מכחו וראשית אונו כנ\"ל במשל שזהו שרש ומקור תולדות נש\"י בפנימי'<sup data-n=\"555\">171</sup> מפנימי' אוא\"ב דאצי' ששרשו בפנימי' עתיק<sup data-n=\"556\">172</sup>, שהוא בחי' סיבה הנעלמת לעורר עצמית השעשועים בבחי' גילוי אור שהוא בחי' העלם עצמית דא\"ס שלמעלה מגילוי אור העצמי וכמ\"ש כי אתה אבינו כי אתה ממש וכמ\"ש בנים אתם כו' וא' בני בכורי ישראל<sup data-n=\"557\">173</sup> כמו הבן שנולד מטיפה שבמוח האב<sup data-n=\"558\">174</sup> שהוא מעצמותו ממש (אך בגשמי' עצמו' נפשו הוא בחי' גילוי אור לגבי שלמעלה הימנו כו' אבל בנש\"י שרשם בעצמו' שלמע' מגילוי אור לגמרי כנ\"ל, ולכן נק' בני בכורי בני דווקא שהוא כח התולדה שבעצמו' וגילוי אור שמתהווה מכח דתולדה שבעצמי' הוא ראשית הגילוי דכל מיני גילוי אור שאח\"כ ולכן נק' בכורי שהוא ראשית אונו דווקא כנ\"ל ). וע\"כ יש בטבע כ\"א מישראל לימשך אחר ה' ולהכיר את בוראו לקרותו אבא כו' בלי שום טעם והתבוננות בהשגה כלל, מצד שהוא למעלה מכל אשר ישיג בהשגות והתבוננות איך שהוא ית' מקורא דכולא<sup data-n=\"559\">175</sup> כו' שאין זה מצד עצם אלקות רק בחי' אור השפעתו שבא בסדר השתלשלות עו\"ע דחו\"ב ומדות כו' שהוא רק מבחי' נה\"י דאו\"א בזו\"נ כידוע בשרש ענין מע\"ב. וכ\"ה למעלה מכל מיני עונג שיתענג מהתבוננו' זאת איך שהוא מקורא דכולא וכן למע' אפילו מבחי' עונג ושעשועים העצמי' אשר יתענג על הוי' מצד עצמו' ממש כמ\"ש למעלה מהיותו מקור להשתל' כנ\"ל, רק קריאה זאת הוא מצד תוקף גילוי אמונה הפשוטה שבעצמות הניצוץ אלקי ששרשה בהעלם עצמות המאור, וגילוי זה בא בהלבשה במוח בבחי' הכרה בלבד הנק' קטנות דאבא ובבחי' הדיבור ג\"כ בבחי' הקטנות שנק' נה\"י שבנה\"י דדיבור כנ\"ל. ונמצא שבבחי' קטנות זאת מלובש מהות ועצמות ג\"ר דאבא (ולא הארתן בלבד כו'), ששרשם בפנימי' עתיק העלם עצמות המאור כנ\"ל וד\"ל. וכל אשר יבוא לבחי' השגות אלקות בגדלות המוחין וכן לבחי' עונג באלקות אפי' בחי' עונג ושעשועים עצמי' אינו רק כמו מוסיף על העצם בבחי' הרכבה שיוכל להתבטל מאיזה סיבה מצד מעה\"ת<sup data-n=\"560\">176</sup> שגורמים חורבן וגלות ה' ירחם, אבל עצמות אמונה הפשוטה אינו משתנה כלל משום גלות וחורבן והוא פועל בזמן הגלות בחי' התקשרות בנש\"י בכל לב ונפש כמו לע\"ל ממש ובלי שינוי כלל כו' וד\"ל. וזהו משא\"מ ע\"כ ה' אלקינו בשכבינו ובקומינו נשיח בחוקיך<sup data-n=\"561\">177</sup>, כי בשכבינו הוא בזמן הגלות דרישא שכיבת לעפרא<sup data-n=\"562\">178</sup> ובקומנו הוא לע\"ל שיתגלה אור גדול מתוך החשך שהוא ענין גילוי טעמי המצות שיתגלה לע\"ל<sup data-n=\"563\">179</sup>, וע\"ז א' נשיח בשיחה",[["555","171","<b>בפנימי'</b>: שם: ליתא."],["556","172","<b>מפנימי' אוא\"ב. . בפנימי' עתיק</b>: נסמן לקמן הערה 310."],["557","173","<b>בני בכורי ישראל</b>: שמות ד, כב."],["558","174","<b>הבן שנולד מטיפה שבמוח האב</b>: ראה תניא פ\"ב. תו\"ח כאן הערה 49."],["559","175","<b>מקורא דכולא</b>: זהר בראשית לג, א."],["560","176","<b>מעה\"ת</b>: מעשה התחתונים."],["561","177","<b>ע\"כ. . נשיח בחוקיך</b>: ברכת אהבת עולם (ערבית)."],["562","178","<b>דרישא שכיבת לעפרא</b>: ראה זהר במדבר קיט, ב. ע\"ח שער מיעוט הירח של\"ו, פ\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' יד."],["563","179","<b>טעמי המצות שיתגלה לע\"ל</b>: ראה רש\"י שה\"ש א, ב. אותיות דר\"ע אות ז — אוצר המדרשים (אייזענשטיין) ח\"ב ע' 414. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תקצ. שה\"א ג, ב הערה 10. סה\"מ תרל\"ח ע' רכא."]]],[4801940634,"חיצוני' שהוא מה שקוראו אבא בלשונו בלבד כנ\"ל, וזהו בחקיך דייקא שהוא למע' מן הטעם לגמרי ובבחי' נשיח בשווה בשכבינו ובקומנו עד שאין הפרש כלל ביניהם כו'. וא\"כ א'<sup data-n=\"564\">180</sup> ונשמח בדברי תורתך ובמצותיך שהוא השמחה מצד שהיא תורתינו<sup data-n=\"565\">181</sup> בלבד ולא מצד הטעמים הגנוזים בה, וכן בעסק המצות מצד שהם רצונו בלבד ולא מצד התענוגים הגנוזים בה[ם], ושמחה זאת היא ג\"כ לעולם ועד בלי השתנות כלל מצד שאעפ\"י שהוא בחי' גילוי אור מ\"מ הוא בחי' אור חדש שהוא מה שהעצם ממש שלא הי' מעולם בגדר וסוג אור הוא מאור<sup data-n=\"566\">182</sup> וא\"כ הוא בחי' אור עצמי בלתי משתנה כמו שהעצם ממש בלתי משתנה כו' וד\"ל.\n<b>והטעם</b> לזה שע\"י המצה דווקא יתגלה כח זה דאמונה הפשוטה ששרשו בהעלם עצמות המאור לבוא לכלל גילוי אור חדש ע\"י התומ\"צ בשמחה מצד שהמה תורתו ומצותיו [כו'] כנ\"ל, היינו משום שהמצה אין בה טעם מורגש כלל וגם אינ[ה] באה בניפוח והגבהה כלל מצד שאין בה שאור המחמיץ כידוע, וא\"כ לא נתגלה בה כח המצמיח בבחי' גילוי אור רק שמלובש בה העלם עצמות כח המצמיח עצמו [כמ\"ש ] לכן ע\"י המצה דווקא תתגלה כח האמונה העצמי' בבחי' גילוי. אך התלבשות זה הגילוי לא יוכל להיות כ\"א בבחי' הקטנות שהוא בחי' העדר התפשטות וגילוי אור כמו לחם המצה שאין בה טעם כלל בבחי' התפשטות עונג וגילוי אור, וכך הוא ענין האמונה שהוא בלא טעם ושכל כלל ובלא התפעלות מורגשת בלב כלל רק מצד האמונה שהוא כמו האומן את היונק<sup data-n=\"567\">183</sup> שהתינוק נמשך אחר האומנת שלו בלא טעם ודעת כלל כו', שזהו מצד ההרגל בבחי' טבע שני<sup data-n=\"568\">184</sup> שיוכל להיות בבחי' המשכה זאת התקשרות חזקה כמו בבחי' התקשרות לאביו ולאמו שבא מצד בחי' טבע ראשון שהולידו אותו. וכן ע\"י אכילת מצה תתגלה כח האמונה הפשוטה בעצמי' הנשמה האלקי' בבחי' טבע ראשון ובנה\"ט בבחי' טבע שני עד שגם נה\"ט תתקשר לבחי' אלקו' ולהגות בתורתו ולעסוק במצותיו בלי שום טעם ודעת והתבוננות כלל ובלי שום עונג ושעשועים כלל מצד התומ\"צ (כרבים מגדולי האחרונים שאהבו את<sup data-n=\"569\">185</sup> התו' מצ\"ע כו') רק בבחי' שמחה מצד שהיא תורת הקב\"ה ומצותיו שזהו בחי' שמחה עצמי' כנ\"ל וד\"ל.\n<b>וזהו</b> מ\"ש במ\"א בפי' אמונה שיש בו ב' פירושי', הא' מל' ותקעתיו יתד במקום נאמן<sup data-n=\"570\">186</sup> שזהו תוקף התקשרות החזקה שבעצמו' הנשמה אלקי' עצמה, והב' מלשון אומן את היונק כנ\"ל כמ\"ש ויהי אומן את הדסה<sup data-n=\"571\">187</sup> כו' שזהו בחי' גילוי",[["564","180","<b>וא\"כ א'</b>: ב: ואח\"כ."],["565","181","<b>תורתינו</b>: שם: תורתו."],["566","182","<b>מאור</b>: שם: מאיר."],["567","183","<b>האומן את היונק</b>: בהעלותך יא, יב."],["568","184","<b>ההרגל בבחי' טבע שני</b>: ראה תניא ספי\"ד. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תרכ. תו\"ח תצוה ח\"ב שלח, ג הערה 724."],["569","185","<b>את</b>: ב: ליתא."],["570","186","<b>ותקעתיו יתד במקום נאמן</b>: ישעי' כב, כג. ראה גם מאמרי אדה\"ז על ענינים ע' תמא."],["571","187","<b>ויהי אומן את הדסה</b>: אסתר ב, ז."]]],[4801940638,"אמונה הפשוטה בנה\"ט בבחי' טבע שני מצד הרגילות כו', וב' בחי' האמונה אלו נמצא בכללות נש\"י<sup data-n=\"572\">188</sup> מצד עצם שרשם שהמה מאמינים בני מאמינים<sup data-n=\"573\">189</sup> כי המה מאמינים מצד שרשם שעלו במח' תחילה כנ\"ל שזהו מצד עצם כח התולדה כו', [ו]מבחי' זאת נמשך גילוי אור האמונה בעצמו' הנשמה בבחי' טבע ראשון כנ\"ל, ומה שהמה בני מאמינים היינו ירושת האמונה שיש להם מאבותי[הם] כמו אאע\"ה שהי' המאמין הראשון<sup data-n=\"574\">190</sup> להתקשר בהעלם העצמי' שלמע' מגילוי אור אפי' אור העצמי שהוא בחי' שעשועים העצמי' כמ\"ש והאמין בה'<sup data-n=\"575\">191</sup> כנ\"ל (משא\"כ דורות שלפניו אעפ\"י שהיו צדיקים<sup data-n=\"576\">192</sup> מופלגים לעבוד ה' בכל לב ובכל נפש הי' רק מחמת שכל ותענוג כו'), ובחי' זאת הוא הממשיך בחי' אמונה בנה\"ט בבחי' טבע שני כו' וד\"ל. וז\"ש וארשתיך לי באמונה<sup data-n=\"577\">193</sup> שזה הי' ביציאת מצרים שנגלה עליהם ממ\"ה<sup data-n=\"578\">194</sup> בבחי' מקיף הנק' אירוסין כו', אך גילוי המקיף הזה לא נגלה עליהם רק בבחי' הלבשה בבחי' קטנות הנק' אמונה ולכן יצאו ממצרים בבחי' אמונה בלבד כמ\"ש ויאמן העם<sup data-n=\"579\">195</sup> כו' (משא\"כ במ\"ת שנתגלה בחי' מקיף הזה בכל פרטי כחות הנפש שהוא בבחי' תומ\"צ שנק' ג\"כ אירוסין ונשואין שיהי' לע\"ל<sup data-n=\"580\">196</sup> כו'). ובחי' אמונה זאת נתגלה בב' בחי' בעצמות נשמתם האלקי מצד עצם שרשה, וכן בגופם ונה\"ט שלהם מצד הירושה מאבות<sup data-n=\"581\">197</sup> ולכן יצאו בלי שום קושיא כלל האיך [ני]לך במקום מדבר מצד שלא הסתיר לבחי' אמונה זאת אפי' בחי' חומר הגוף כו'. והנה ב' הבחי' הנ\"ל נתגלו ע\"י המצה שאכלו במצרים בליל [ה]פסח וע\"כ נק' המצה מיכלא דמהמנותא מאכל שזן ומפרנס לחזק כח האמונה עד שתתגלה כח זה גם בנה\"ט שיהי' בו ג\"כ חוזק התקשרותו בבחי' טבע שני כמו טבע ראשון שבנשמה עצמה שבכאו\"א מישראל שטבעו להתמשך אחרי הוי' שמלובש בזה עצמות המאור שלמעל' מבחי' גילוי אור, כן ע\"י המצה תמשך טבע זו גם בנה\"ט וזהו עיקר ענין המצה שנק' בשם מיכלא דמהמנותא כי עיקר המאכל הוא להמשיך כח הנשמה בגוף דווקא (אך גם בעצם הנשמה נמשך תוס' אור משרשה העצמי דיחידה ע\"י אכילת מצה ועי\"ז תוכל להאיר בנה\"ט, אך עיקר הכוונה הוא בשביל נה\"ט כנ\"ל וד\"ל).\n<b>וזהו</b> הא לחמא עניא די אכלו כו' בחי' הוי' למע' מן הטעם ודעת ובלא התפעלות הלב כלל כמצה זו שאין בה טעם ולא התנשאות והגבהה כלל,",[["572","188","<b>בכללות נש\"י</b>: ב: ליתא."],["573","189","<b>מאמינים בני מאמינים</b>: שבת צז, א."],["574","190","<b>אאע\"ה שהי' המאמין הראשון</b>: ראה שמו\"ר פכ\"ג, ה. שהש\"ר פ\"ד, ח (ג)."],["575","191","<b>והאמ[י]ן בה'</b>: לך טו, ו."],["576","192","<b>צדיקים</b>: ב: ליתא."],["577","193","<b>וארשתיך לי באמונה</b>: הושע ב, כב. ראה שה\"א ט, א ובהערה 8. תו\"ח בא ח\"א קי, א הערה 541."],["578","194","<b>שנגלה עליהם ממ\"ה</b>: הגדה ש\"פ פיסקא מצה זו."],["579","195","<b>ויאמן העם</b>: שמות ד, לא. ראה גם תו\"ח כאן קטז, ג ובהערה 61. משפטים ח\"ב רעז, ג."],["580","196","<b>במ\"ת. . אירוסין ונשואין שיהי' לע\"ל</b>: ראה תו\"ח בשלח ח\"א קפ, ב. וש\"נ. סה\"מ תרכ\"ט ע' רלט."],["581","197","<b>אמונה. . הירושה מאבות</b>: ראה תניא פי\"ח ופל\"ג. מאמרי אדה\"א נ\"ך ע' כח. וש\"נ. שה\"א ו, א ובהערה 13."]]],[4801940641,"וע\"כ נק' לחם עוני שאין בו שום גילוי אור והיא הנותנת שמלובש בזה<sup data-n=\"582\">198</sup> כו', שזהו בחי' ד' דיו\"ד הנ\"ל<sup data-n=\"583\">199</sup> שהוא<sup data-n=\"584\">200</sup> בחי' המל' דאצי' שאינה מאירה בעשי' כלל וגם בברי' ויצי' אינה מאירה רק כפי קו המדה שבהשלשלות העולמות שזהו בחיצוני' המל', ובפנימי' המל' שהוא בחי' תוס' אור להאיר יותר מכפי המדה אינה רק בחי' נקודה בלבד דלית בה חיוור<sup data-n=\"585\">201</sup> כלל, ובבחי' נקודה זאת נמשך בחי' קטנות דאבא שהוא בחי' נה\"י דנה\"י שבחכ' שנמשך בבחי' נה\"י דנה\"י דמל' (כמו ענין ההכרה שנמשך בתינוק בדיבור<sup data-n=\"586\">202</sup> לקרותו אבא כנ\"ל). ובבחי' קטנות דאבא מלובש בהעלם מעצמות אור אבא שלמעל' גם מהמשכות דאור אבא באימא מנה\"י שבו כנ\"ל, וא\"כ המצה אפי' שהיא בחי' קטנות דאבא בשרשה היא למעל' אפי' מבחי' [ה]מוחין דגדלות דאימא, ואפי' מבחי' מוחין דגדלות דאבא המאירים באימא כי בחי' זאת הוא עצמות ומהות אור אבא שלא יוכל להאיר באימא כלל (וז\"ש חכם מה הוא אומר מה העדות כו' כמשי\"ת<sup data-n=\"587\">203</sup> ). וזהו לחמא עניא כי לחם הוא בחי' ג' הוי'<sup data-n=\"588\">204</sup> ששרשם הוא בחי' שנים עשר ת\"ד ומזל הי\"ג הכוללם<sup data-n=\"589\">205</sup> שהם נגלים בג' בחי' חיוורי' ותיקונין ונימין<sup data-n=\"590\">206</sup>, ושרש החיוורתא שהוא בחי' היותר עליונה שבהם הוא בבחי' עונג הפשוט ושעשועים העצמי' כו', אבל הא דלחמא מורה על חד ארחא דבפלגותא דשערי<sup data-n=\"591\">207</sup> שהוא מקור תרי\"ג מצות התו' בבחי' המעשה שלהם למעלה מן הטעם ודעת לגמרי רק בבחי' עול, וארחא זאת היא יסוד המעמיד ומקיים שלהם שזהו כח האמונה הפשוטה שבכנס\"י שהוא מצד שרשם כנ\"ל<sup data-n=\"592\">208</sup> שבהעלם עצמות המאור שלמע' אפי' משעשועי' העצמי' כנ\"ל, וכח זה נגלה ע\"י ארחא זאת כנ\"ל. ועניא בגי' קל\"א<sup data-n=\"593\">209</sup> שזהו היפוך הגסות דס\"מ א\"ל<sup data-n=\"594\">210</sup> שהיפוכו האמיתי אינו רק מבחי' שפלו' בעצם שלא מצד ביטול דעלול בעילתו וכמאמ' דהע\"ה לא גבה לבו<sup data-n=\"595\">211</sup> מצד השפלות בעצם שהי' לבו חלל בקרבו<sup data-n=\"596\">212</sup>, וא\"ת שזה הי' מצד הביטול דהתבוננות והשגה או עונג ושעשועי' לזה א' לא רמו עיני<sup data-n=\"597\">213</sup> ולא הלכתי בגדולות ובנפלאות ממני, ואעפ\"כ לא גבה לבי אין זה אלא מצד שפלות בעצם כו'. והנה בחי' זאת הוא בחי' פנימי' חכ' שלמע' אפילו מבחי' דהב\"ן בחכ' כי אין לבינה בבחי' פנימי' זאת מקום כלל, וזהו מהות",[["582","198","<b>הוי' למע'. . בזה</b>: ב: נקודה."],["583","199","<b>ד' דיו\"ד הנ\"ל</b>: ראה לעיל בפנים על יד הערה 23."],["584","200","<b>ד'. . שהוא</b>: ב: ד' יו\"ד כנ\"ל שזהו."],["585","201","<b>נקודה. . חיוור</b>: ראה זהר בלק קצא, א."],["586","202","<b>בדיבור</b>: ב: ליתא."],["587","203","<b>חכם מה הוא אומר. . כמשי\"ת</b>: נוסח ההגדה. תו\"ח כאן קטז, ג. ראה הנרשם ברשימת הכת\"י בריש המאמר."],["588","204","<b>לחם הוא בחי' </b>[ב: בגי']<b> ג' הוי'</b>: פע\"ח שער השבת שי\"ח, פי\"ז."],["589","205","<b>ומזל הי\"ג הכוללם</b>: ראה ע\"ח שער הולדת או\"א וזו\"ן שט\"ו, פ\"ו."],["590","206","<b>בב' </b>[ב: בג']<b> בחי' חיוורי ותיקונין ונימין</b>: ראה פע\"ח שם."],["591","207","<b>חד ארחא דבפלגותא דשערי</b>: ראה זהר אד\"ר נשא קכט, א."],["592","208","<b>כנ\"ל</b>: ב: ליתא."],["593","209","<b>ועניא בגי' קל\"א</b>: להעיר מס' מעיל צדקה סי' א'ת\"ץ: ענ\"י בגימטריא ק\"ל ועם הכולל קל\"א כמנין סמא\"ל."],["594","210","<b>דס\"מ א\"ל</b>: ב: דשם אל אחר [ואוצ\"ל: דס\"מ]."],["595","211","<b>לא גבה לבו </b>[ב: ליבי]: תהלים קלא, א."],["596","212","<b>לבו חלל בקרבו</b>: תהלים קט, כב."],["597","213","<b>לא רמו עיני</b>: המשך הכתוב לא גבה ליבי [ושם: ולא]."]]],[4801940643,"ועצמות אבא המתלבש במל' כמ\"ש בבחי' נקודה תחי'<sup data-n=\"598\">214</sup> שמאיר ע\"י לחם המצה וזהו לחמא עניא<sup data-n=\"599\">215</sup> די כנ\"ל וד\"ל.\n<b>ולפ\"ז</b> הרי מובן שהמצה למע' הוא בעצם כח מ\"ה דחכמה<sup data-n=\"600\">216</sup> שלמעלה משפע דחכ' בבינה מאין ליש ורק הוא בבחי' אין האמיתי דעצמי' החכ' שהיא בטילה ונכללת בעצמי' ממש (וכנ\"ל בענין החכ' שבהעלם עצמו' המאור, וכמו בנפש הכח להוליד הכלול בעצמות הנפש שע\"ז נק' הנפש בשם נפ' המשכלת [כו'] וד\"ל). ובחי' זאת הוא בחי' שוב בלבד והוא למע' מיחוד חו\"ב שהוא בחי' רו\"ש שהמים<sup data-n=\"601\">217</sup> אינו אלא לפ\"ע הרצוא וזה השוב הוא מבחי' גילוי אור ושעשועים העצמי', אבל בחי' השוב בלבד שלא ע\"י רצוא הוא בחי' המשכת העצמי' ממש כו'. דהנה מבואר למעלה בענין רו\"ש שהרצוא [הוא] במדות שבלב בא רק מצד השכל בהתפעלותו במוח בינה (שהוא גילוי בחי' עומק רום שלפ\"ע עומק תחת כו'<sup data-n=\"602\">218</sup>, שזהו [ב]בחי' עומק המושג דבינה הגורם ביטול והפשטה במדות שבלב שתתפשט האה' מלבושי' כנ\"ל באריכות), וגם הוא נתבטל לגבי בחי' הראי' דחכ' שהוא בחי' שוב (שזהו גילוי העצם דיחידה<sup data-n=\"603\">219</sup> שלמע' מגדר מקום דרום ותחת, אך עיקר הגילוי שלו למטה מצד פנימי' הכוונה דנתאווה כנ\"ל [באריכות אמנם כ\"ז אינו מגיע לבחי' העצמו' ממש רק לבחי' אור העצמו' כו', משא\"כ בבן בהגיעו אל אביו שנמשך אחריו מצד עצם התולדה כנ\"ל], וכמו בחי' האמונה אעפ\"י שאין בה התפעלות רצוא שמצד השגה אלקי' כלל ואין בזה הגבהה והתנשאות הלב כלל עכ\"ז נמשך בכל נפשו [ממש] מצד ההכרה בעצם כנ\"ל, וזהו ענין המצה שאין בה טעם והגבהה כנ\"ל, להיותה למע' הרבה מבחי' [ה]טעם והשגה שהוא בבחי' מוחין דאימא, שהוא [ב]בחי' רצוא הנ\"ל וד\"ל. וגם למעלה מבחי' אין דחכ' שנמשך לבינה בדרך עו\"ע ביו\"ט, וגם בשבת שהוא בחי' מוחין דאבא<sup data-n=\"604\">221</sup> עצמו שנק' קדש שזהו הגילוי דאא\"ס כמ\"ש למעלה מהשתל' דעו\"ע (ולכן בחי' מוחין דאימא שהוא בחי' הגילוי דאא\"ס שבהשתל' המה טפלין למוחין דאבא משא\"כ ביו\"ט שמוחין דאימא<sup data-n=\"605\">220</sup> המה עיקרין כנ\"ל) אין<sup data-n=\"606\">222</sup> כ\"ז רק בחיצוני' שפע הנמשך מעצמי' המאציל שהוא בחי' גילוי אור ושעשועים בלבד שנק' חיצוני' לגבי הפנימי' דהעלם עצמות המאור כנ\"ל. וגם שפע זאת דשעשועי' עצמות<sup data-n=\"607\">223</sup> המאיר בשבת נמשך בדרך עו\"ע רק ש[ה]השתל' דעו\"ע אינ[ו] מסתיר רק פועל השפעה בדרך מעביר בלבד כו', משא\"כ אכילת מצה דפסח בלילה הראשונה הוא המשכת העלם העצמות המאור שלא בדרך השתלשלות דעו\"ע אפי' בדרך",[["598","214","<b>תחי'</b>: תחילה אוצ\"ל: תח\"י תחת יסוד ב: בחי'."],["599","215","<b>עניא</b>: ב: ליתא."],["600","216","<b>כח מ\"ה דחכמה</b>: זהר רע\"מ צו כח, א. לד, א."],["601","217","<b>שהמים</b>: ב: שהשוב."],["602","218","<b>כו'</b>: שם: כנ\"ל."],["603","219","<b>דיחידה</b>: שם: דנקודה."],["604","221","<b>דאבא. . קדש</b>: ראה הערה 85."],["605","220","<b>בשבת. . מוחין דאבא. . ביו\"ט שמוחין דאימא</b>: ראה פע\"ח שער מקרא קדש ש\"כ, פ\"א. לקו\"ת צו יא, ד. בחוקותי מז, ג. סה\"מ תרכ\"ז ע' תפט. וש\"נ. שע\"ת צח, ב בשם הע\"ח. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'מד. לעיל סד\"ה להבין כו' פנים חדשות תרי\"ט."],["606","222","<b>אין</b>: ב: אך."],["607","223","<b>עצמות</b>: שם: עצמי'."]]],[4801940645,"מעבר רק בדרך דילוג המהות במדריגה היותר אחרונה דייקא ולכן הוא בבחי' התלבשות בהעלם דוקא בבחי' קטנות דאבא וקטנות דמל' כנ\"ל באריכות כו' וד\"ל. ולפ\"ז יש יתרון מעלה ליו\"ט דפסח מצד אכילת מצה גם על השבת כידוע בטעם שנק' פסח מל' דילוג<sup data-n=\"608\">224</sup> כמ\"ש ופסח הוי' על הפתח<sup data-n=\"609\">225</sup> כמשי\"ת כו' וד\"ל.\n<b>והנה</b> מזה הטעם יובן מה שנאסר החמץ בפסח כמ\"ש כל מחמצת<sup data-n=\"610\">226</sup> כו'<sup data-n=\"611\">227</sup> להיות שעיקר ענין יצי\"מ הי' בבחי' האמונה שהוא ההכרה וההמשכה מצד העצם כנ\"ל, והיינו להיות כי יצי\"מ פירושו לצאת מן המיצר וגבול וכל בחי' גילוי אור מוכרח להיות ע\"י צמצום העצמי', ואפי' בחי' שעשועים העצמי' שהוא ענין עליות הרצון להיות טוב בבחי' גילוי אור שזהו החפץ שמהעלם עצמותו יבוא לכלל גילוי אור בעצמו תחילה כיון שנעשה ע\"י רצון והרצון הוא אור מציאות פרטי א\"כ הוא בא ע\"י העלם עצמותו. והנה ידוע דכח ההעלם הנ\"ל נמשך ממדריגה למדריגה בצמצום האור ובמיעוט אחר מיעוט עד שנעשה למטה למטה<sup data-n=\"612\">228</sup> העלם גמור וחשך המסתיר לבחי' אלקות המחי' ומהווה, ומבחי' הסתר אור האלקי נמשך בחי' הרע דמדות רעות, ולכן למטה מצרים דקליפה היא מקור כל מיני רע<sup data-n=\"613\">229</sup> כמש\"א פרעה שהוא מלך מצרים לא ידעתי את הוי'<sup data-n=\"614\">230</sup> היינו שאינו עדיין רע גמור בתאוות דמדות רעות, רק הסתר אור האלקי עד שאינו יודע משם הוי' שהוא הי' הוה ויהי' כאחד<sup data-n=\"615\">231</sup> מצד שבבחי' זאת כל ההשתל' בתכלית הביטול וכלא חשיב קמי', רק מבחי' אלקות בגי' הטבע<sup data-n=\"616\">232</sup> בזה יש לו ידיעה ולכן קראו לו אלקא דאלקיא<sup data-n=\"617\">233</sup> ע\"י השתל' רבות דריבוי הממוצעים. ולכן גם בעסק מו\"מ תופסים מקום אצלו הסיבות להביא ולהמציא טרף לנפשו עד שעושה אותם בעומק הלב והמוח, אבל אם הי' מאיר בו הביטול דשם הוי' לא הי' הסיבה תופסת כלל מקום אצלו רק לעשותה בלבד בלי עומק הלב ומוח רק מח' חיצוני' כו'. ולכן גלות הראשון שהיו ישראל [הי'] במצרים להיות כי קליפה זאת הוא קליפה ראשונה המסתרת וממנה נמשך כל מיני רע כו' (שהוא הרע דעמלק ראשית גוים<sup data-n=\"618\">234</sup> הרגשת עצמו ליש ביותר שזהו ג\"כ מצד הרגשת העדר הביטול דשם הוי', ואח\"כ מקליפת עמלק נמשכת ז' מדות [ה]רעות<sup data-n=\"619\">235</sup> כו').",[["608","224","<b>פסח מל' דילוג</b>: ראה רש\"י בא יב, יא. יג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקלד ובהנסמן לשם. תו\"ח בא ח\"א קכג, א הערה *4."],["609","225","<b>ופסח הוי' על הפתח</b>: בא יב, כג."],["610","226","<b>כל מחמצת</b>: בא יב, כ."],["611","227","<b>כו'</b>: ב: לא תאכלו."],["612","228","<b>למטה</b>: שם: ליתא."],["613","229","<b>מצרים. . מקור כל מיני רע</b>: ראה גם תו\"ח בשלח ח\"א קצא, סע\"ב ואילך ובהנסמן שם."],["614","230","<b>לא ידעתי את הוי'</b>: שמות ה, ב. ראה גם לקמן מאמר ד\"ה וספרתם תקצ\"ח על יד הערה 26."],["615","231","<b>הוי' שהוא הי'. . כאחד</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."],["616","232","<b>אלקות </b>[ב: אלקי']<b> בגי' הטבע</b>: ראה שבילי אמונה — לר' מאיר אבן אלדבי — הנתיב הראשון (ט, ב). פרדס שער הנתיבות שער י\"ב, פ\"ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקעג. תו\"ח שמות ח\"א לח, א הערה 20."],["617","233","<b>אלקא דאלקיא</b>: מנחות בסופה. ראה סה\"מ תרל\"ב ח\"א ע' נג בהערה."],["618","234","<b>דעמלק ראשית גוים</b>: בלק כד, כ."],["619","235","<b>עמלק נמשכת ז' מדות [ה]רעות</b>: ראה גם מאמרי אדה\"א קונטרסים ע' רמא."]]],[4801940647,"<b>ולכן</b> לצאת ממצרים לא היו יכולים אם לא ע\"י שיצאו מהעלם היותר ראשון למע' שנק' מצרים דקדושה<sup data-n=\"620\">236</sup> ואפי' מבחי' מקור ההעלם הזה בעצמי' שהוא ענין ההעלם הראשון שנמשך ממנו רצה\"פ להיות טוב ואור כנ\"ל, ועי\"ז האיר בהם אמונה הפשוטה שהוא [ה]התקשרות [ה]עצמי' [מ]נקודת יהדות[ם] בבחי' פנימי' ועצמי' מהות דאא\"ס [ש]למע' אפי' מבחי' מקור כל רצון, ואמונה זאת נתגלה בהם בבחי' ההכרה הנק' נה\"י דנה\"י<sup data-n=\"621\">237</sup> דאבא ובחי' הכרה זאת נתגלה בדיבור במה שצועקין אבינו וכן בהילוך דיצי\"מ למשך אחרי ה' בכל לב ונפש בלי שום קושיא המסתרת כנ\"ל. והיינו מטעם שגם הדיבור חיצוני' וההילוך הוא בחי' היותר אחרונה שבזה מתלבש בחי' היותר אחרונה שבשכל שבזה מתגלה [בחי'] כח אמונה הפשוטה הנ\"ל, ובכח זה דווקא היו יכולים לצאת ממצרים. וזהו ענין קטנות דאבא שהוא המשכה מעצמות אור אבא בלי [ה]העלאה דרצוא כלל (כמו בשבת ושאר[י] המועדים כנ\"ל), אדרבה בחי' ההעלאה דרצוא הוא בחי' המנגד לביטול זה העצמי' דאמונה והכרה בלא טעם והתפעלות מורגשת רק כתינוק שקורא אבא כנ\"ל, לפי שהתפעלות זאת דרצוא הוא בבחי' יש [מי] שמשיג ויש מי שמתפעל ועולה בבחי' העלאה למע' כנ\"ל שזה[ו] הכח דגבורות[יו] של הקב\"ה לצמצם עצמי' אורו להיות נכלל במאור, וכל מה שמתעלה האור במאור יותר נק' [עמ\"ר] נעשה מזה עומק תחת<sup data-n=\"622\">238</sup> יותר שהוא ענין הגילוי הארה דהארה בהשתל' למטה מטה יותר, וכח זה נתפס בכח הבינה שהוא ג\"כ בחי' השגה בבחי' [ה]יש ועי\"ז יכול לתפוס כח אור האלקי המחי' ומהווה שהוא ג\"כ בחי' יש לגבי אין האמתי דעצמות אא\"ס, רק להיות ששרש עומק תחת [הזה] הוא בבחי' עומק רום לכן ע\"י השגה זאת בבחי' יש בא לפנימי' השגה שהוא ענין<sup data-n=\"623\">239</sup> עומק המושג להשיג בחי' אין של היש שהוא ביטול והתכללות האור במאור הנק' עו\"ר<sup data-n=\"624\">240</sup> ולכן נעשה מזה העלאה דרצוא. אך כל הנ\"ל בהשגת היש וביטול היש ג\"כ בחי' יש יחשב ולכן יוכל להסתעף מזה אש זרה בהתנשאות והגבהה בגסות היפוך הביטול ושפלות דבחי' שוב, ולכן צ\"ל שוב אחר הרצוא שהו\"ע הראי' דחכ' שזהו בעצמות המאור דחפץ חסד כנ\"ל שממתיק בחי' הגבורה דרצוא, לכן נמשך בחי' השוב מצד הרצוא דווקא מצד ששרשם אחד הם [מ]בחי' הרצון להיטיב שהוא בחי' טוב וחסד<sup data-n=\"625\">241</sup> נמשך מזה בחי' הצמצום דהשתל' כנ\"ל. אך כ\"ז הוא בחי' התגלות הביטול דאור אבא שהוא בשרשו [מ]בחי' ח\"ח<sup data-n=\"626\">242</sup> הנ\"ל או למע' יותר עצמי' השעשועי' שזה נגלה בשבת, אבל עצמות הביטול דאור אבא הוא בחי' השפלות בעצם הבא מצד התקשרות העצמי' הנגלה בנש\"י, וכאשר נתגלה התקשרות זאת מצד העלם העצמי' אזי גילוי האור אינו תופס מקום כלל לכן הוא [ב]בחי' שוב בלי רצוא דווקא, כי כאשר יש איזה העלאה דרצוא זה מורה שיש איזה בחי' גילוי אור וא\"כ הוא אות וסימן שלא ניטה<sup data-n=\"627\">243</sup> כח ה[ה]תקשרות שבהעלם העצמי' כ\"א הי' מתגלה התקשרות",[["620","236","<b>מצרים דקדושה</b>: ראה גם תו\"ח וארא ח\"א סט, ב. וש\"נ."],["621","237","<b>דנה\"י</b>: ניתוסף ע\"פ ב."],["622","238","[עמ\"ר]<b>. . עומק תחת</b>: ראה גם ס\"י פ\"א, מ\"ה. שע\"ת כג, א ובהערה 3."],["623","239","<b>ענין</b>: ב: ליתא."],["624","240","<b>עו\"ר</b>: שם: עומ\"ר עומק רום."],["625","241","<b>טוב וחסד</b>: שם: חסד."],["626","242","<b>ח\"ח</b>: חפץ חסד."],["627","243","<b>ניטה</b>: ב: נתגלה."]]],[4801940649,"זאת לא הי' מקום לבחי' גילוי אור כלל. וזהו טעם איסור חמץ בפסח מצד שנתגלה כח ההתקשרות העצמי' בנש\"י שהוא אמונה הפשוטה שבהם ומחמת זה יש בהם בחי' ביטול עצמי' בבחי' שפלות בעצם, ולכן אסור להמשיך בנפשו בחי' החיות דגילוי אור שהוא המנגד לביטול זה העצמי' כנ\"ל וד\"ל.\n<b>והנה</b> להבין בתוס' ביאור ענין איסור אכילת חמץ הנ\"ל, יש להקדים מה שאנו רואים שאיסור אכילת חמץ תלוי בהקרבת הפסח<sup data-n=\"628\">244</sup> דווקא, ולכן מחצי היום זמן הקרבת הפסח<sup data-n=\"629\">245</sup> מחויב להשבית חמץ, ויש בזה מ\"ע<sup data-n=\"630\">246</sup> וכאשר מקריבים בפועל ולא ביער את החמץ הוא עובר בל\"ת דלא תשחט<sup data-n=\"631\">247</sup> כו', וגם בזמן הגלות שאין לנו קרבן פסח עובר במ\"ע שתלוי בזמן הקרבה בלבד. וגם להבין מצות אכילת מצה עם הפסח ביחד כמ\"ש על מצות ומררים יאכלהו<sup data-n=\"632\">248</sup> כו', הנה יש להקדים בתחלה הטעם שנק' יו\"ט זה בשם חה\"פ, כי הנה ענין פסח הוא מלשון ופסח הוי' על הפתח כו', שהו\"ע הדילוג הגדול מגבוה לנמוך וזהו כמו ענין הנאמ' בשה\"ש קול דודי הנה זה בא מדלג על ההרים<sup data-n=\"633\">249</sup> כו' כידוע. והנה להבין [בתוס' ביאור] למה בתו' נאמ' [ב]לשון פסיחה ובשה\"ש נאמר לשון דילוג, ובתו' נאמר שהדילוג הוא על הפתח ובשה\"ש נאמר שהדילוג הוא על ההרים. הנה מתחלה י\"ל מהות ענין הדילוג מה ענינו, ולמה הי' צריך לדילוג מה<sup data-n=\"634\">250</sup>, כי הנה כנס\"י הי' בזה\"ג דמצרים<sup data-n=\"635\">251</sup> בבחי' הקטנות מאד במדריגה שאין למטה הימנה וע\"ד תינוק הנולד ביומו שהי' בעיבור במעי אמו בתחלה ראשו בין ברכיו<sup data-n=\"636\">252</sup> ועיניו סתומים<sup data-n=\"637\">253</sup> כו', ומשנולד נפתחו עיניו ולא נתחדש בו מזמן העיבור רק ענין התפשטות הקומה בגשמי' שיהי' ראשו למע' ורגליו למטה שהוא ענין זקיפת הקומה שבה נבדל האדם מן הבהמה, וגם נתחדש בו פתיחת העינים בגשמי' כו'. וגם זאת יש בו ביום ראשון בתחילת לידתו שהוא מלוכלך ומתבוסס בדם הלידה והפסולת היוצא בזמן הלידה עד שמרחיצין אותו. וכך הי' כנס\"י בזמן הגלות דמצרים ברוחני' נפשם האלקי' כו' כתינוק בתחילת לידתו בגשמי' והיינו שלא נתגלה בהם רק כח האמונה הפשוטה והכרה עצמי' הנ\"ל, וגם גילוי [זה] לא נתגלה בהם רק בבחי' הכרה בלבד.\n<b>והנה</b> כח האמונה הנ\"ל ישנו בהעלם בתוך כאו\"א מישראל מצד שרש נשמתן בבחי' העלם [ה]עצמי' שהוא בחי' כח המוליד שבפנימי' אבא כנ\"ל, רק שמוסתרת מאד בחי' אמונה זו בבחי' עקבי' שהוא בחי' ההסתר דעוה\"ז הגשמי' (שהוא בחי' היותר אחרון בהשתל' המקבל מכח האלקי המשתל' בצמצום היותר",[["628","244","<b>שאיסור אכילת חמץ תלוי בהקרבת הפסח</b>: שו\"ע שבהערה 246 ס\"ב."],["629","245","<b>מחצי היום זמן הקרבת הפסח</b>: נסמן בהערה הבאה."],["630","246","<b>מחצי היום. . להשבית חמץ. . מ\"ע</b>: שו\"ע אדה\"ז הל' פסח סתל\"א, ס\"א."],["631","247","<b>בל\"ת דלא תשחט</b>: תשא לד, כה. שו\"ע אדה\"ז שם."],["632","248","<b>על מצות ומררים יאכלהו</b>: בהעלותך ט, יא. ראה גם תו\"ח כאן קיז, ב הערה 90."],["633","249","<b>קול דודי. . מדלג על ההרים</b>: שה\"ש ב, ח."],["634","250","<b>מה</b>: ב: זה."],["635","251","<b>בזה\"ג דמצרים</b>: שם: במצרים."],["636","252","<b>תינוק. . ראשו בין ברכיו</b>: נדה ל, ב."],["637","253","<b>ועיניו סתומים</b>: ראה ת\"ז ת\"ע (קלו, א ד\"ה פתח). תו\"ח וארא ח\"א סו, ד הערה 337."]]],[4801940651,"אחרון הנק' בשם עקב כו'), ולכן אפי' גנבא אפום מחתרתא<sup data-n=\"638\">254</sup> רחמנא קריא מצד כח האמונה הפשוטה מ\"מ עושה היפוך רצונו מצד ההסתר שמוסתר אמונה זאת בנפשו בבחי' עקבי' שהוא חומר גופו (המקבל ג\"כ מצד כח האלקי בצמצום היותר אחרון הנק' עקב כנ\"ל), וזהו כדוגמת העיבור דולד שמונח ראשו בין ברכיו כו'. אך בליל יצי\"מ קודם שיצאו לגמרי האיר בחי' הלידה ב[בחי'] אמונה זאת והיינו שנזקף הראש דכללות נש\"י להאיר בהם כח האמונה הפשוטה בבחי' הכרה בלבד<sup data-n=\"639\">255</sup>, והגם שהכרה זאת הוא בבחי' קטנות מ\"מ בהכרה זאת הי' בהם כח למשול על כללות חומר גופם, ולא עוד אלא שהאיר כ\"כ כח האמונה להקיף כללות נפשם הטבעי' עד שנתבטל ממציאותה ולא הי' יכול לפעול פעולתה להסתיר על הנה\"א, ולכן יצאו באמונה זאת הנגלה בנפשם בלי שום קושי' כנ\"ל (רק שלא הי' בחי' התהפכות וכמ\"ש במ\"א בענין גפן ממצרים תסיע<sup data-n=\"640\">256</sup> כו' כמשי\"ת). וכן בכ\"י חייב כל<sup data-n=\"641\">258</sup> אדם לראות א\"ע כאלו יצא ממצרים<sup data-n=\"642\">257</sup> שהוא ענין זקיפת הראש בבקר בעת קומו משנתו שע\"ז ארז\"ל [כד] זקיף אינש ראשו<sup data-n=\"643\">259</sup> מברך זוקף כפופים כו'. והנה עוד זאת נתגלה בנפשם כח הראי' וההסתכלות ביקרא דמלכא<sup data-n=\"644\">260</sup> בעא\"ע בלי שיעור, והיינו מצד שהעצמי' ממש בא ג\"כ לכלל גילוי אור חדש שלא כמו אור הזה קודם ההשתל' שהוא בחי' שעשועים העצמי' הנ\"ל, שהוא רק גילוי אור שנגלה ע\"י רצה\"פ להיטיב כנ\"ל, אבל בחי' גילוי אור זה הוא גילוי [אור] העלם העצמות ממש<sup data-n=\"645\">261</sup> ובחי' זאת הוא פתיחת העינים שהוא בחי' כח הראי' דחכ' שהוא בחי' חיצוני' חכ', אך כחו מגיע בבחי' הפנימי' והעצמי' להסתכל בגילוי אור העצמי שהוא בחי' אור חדש הנ\"ל. אך אעפ\"כ לא הי' רק בבחי' הקטנות בתכלית בלבד היינו שחסר מהם כל כחות הפנימי' (כמו בתינוק בתחילת לידתו כנ\"ל), שלא הי' בהם כח להשיג השגות אלקות בבחי' מוחין דאימא ולהתפעל במדות שבלב שנק' רצוא שנמשך מחמת התבוננות הנ\"ל איך הוא בעצמו ממלא וסובב רק הודו כו' כנ\"ל, רק אמונה והכרה עצמי' שבלא טו\"ד נתגלה בבחי' הכרה מצד גילוי התקשרות [ה]עצמות שיש בהם בשרשם בהעלם העצמי', וגילוי כח<sup data-n=\"646\">262</sup> הראי' לאסתכלא ביקרא דמלכא דווקא שהוא העילוי והפלאה דעצמות אא\"ס שהוא בחי' אור חדש הנ\"ל שהוא בחי' גילוי העלם העצמי' ממש.\n<b>אך</b> גם כח האמונה וכח הראי' דלאסתכלא כו' לא נגלה רק בבחי' מקיף על נה\"ט עד שלא הי' יכול לפעול פעולתו כמו בחי' שינה הנא' בלק\"א בבינונים בעת",[["638","254","<b>גנבא אפום מחתרתא</b>: ראה ברכות סג, א ע\"פ גי' הע\"י. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' ט."],["639","255","<b>בלבד</b>: ב: ליתא."],["640","256","<b>גפן ממצרים תסיע</b>: תהלים פ, ט. ראה גם אוה\"ת (יהל אור) שם ע' רפא. לקמן מאמר ד\"ה וספרתם תקצ\"ח על יד הערה 47. ד\"ה וספרתם הה' על יד הערה 263."],["641","258","<b>כל</b>: ב: ליתא."],["642","257","<b>בכ\"י חייב. . יצא ממצרים</b>: ראה פסחים קטז, ב (במשנה). תניא פמ\"ז. הגדה עם לקוטי טעמים (קה\"ת תשמ\"ו ואילך) ע' תריח בשולי הגליון."],["643","259","<b>[כד] זקיף אינש ראשו</b>: ראה ברכות ס, ב שע\"ת ז, ג ובהערה 37."],["644","260","<b>וההסתכלות ביקרא דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."],["645","261","<b>ממש</b>: ב: ליתא."],["646","262","<b>וגילוי כח</b>: ב: וכח."]]],[4801940653,"התפלה<sup data-n=\"647\">263</sup> אבל עצם נה\"ט לא נתהפך כלל ונשאר מעורב טו\"ר והוא מה שנאמ' מתבוססת בדמיך<sup data-n=\"648\">264</sup> כו', וע\"כ גם מלמעלה למטה לא הי' אפשר שיומשך בהם האור האלקי העליון בסדר ההשתל' דעו\"ע כמו מחכ' לבינה ומדות כו' אחר שלא הי' בהם העלאה דבינה ליבא<sup data-n=\"649\">265</sup> מצד בחי' הקטנות שלהם, וידוע דרוח אייתי רוח<sup data-n=\"650\">266</sup> ולכן כאשר אין ההתעוררות מלמטה ע\"י בחי' בינה ליבא ע\"כ גם למעלה בבחי' י\"ס דאצי' לא נמשך האור בבחי' הבינה ומדות דאצי' כו'. אך אדרבה היא הנותנת שיש בזה יתרון מעלה הגבה מאד נעלה והוא שנמשך עליהם האור [מ]בחי' מהו\"ע א\"ס ב\"ה שהוא בחי' העלם העצמי' הנ\"ל שבפנימי' ועצמי' דאור אבא דאצי' מבלי שהקדים לזה העלאה דאימא כנ\"ל<sup data-n=\"651\">267</sup>, והיינו להיות שההמשכה דאור אבא שנמשך ע\"י העלאה דאור אימא הוא כפי סדר ההשתל' שמבחי' רצוא נמשך בחי' שוב כנ\"ל בענין רוח אייתי רוח כו', אבל בליל פסח נמשך האור למעלה מסדר ההשתל' שהוא מהעלם העצמי' שבפנמי' ועצמות אור אבא כנ\"ל וירד ונמשך למטה מטה בהתלבשות והעלם בבחי' קטנות דאמונה והכרה זאת כתינוק שיודע לקרות שאביו מחזיר פניו אליו ממילא כו'. וכך הי' בגלות מצרים ע\"י המיצר ולחץ שהי' להם בגלות זכו לגילוי האמונה הפשוטה בנפשם ובנקודת לבבם עד שמצד זה צעקו בצעקה פשוטה למעלה מן הטו\"ד לגמרי מצד הריחוק של המנגד כו', ועי\"ז נתעורר למע' בבחי' פנימי' והעלם העצמות להחזיר פניו אליהם שהו\"ע וידע אלקי'<sup data-n=\"652\">268</sup> שנתלבש אא\"ס במוחי' עליונים דחב\"ד להרגיש בצרתם, ובחי' הרגשה זאת היא הגורמת שיהי' נמשכים כל בחי' המוחין שלמע' שהמה מוחין עצמי' שבפנימי' ועצמות אור אבא להתלבש בבחי' המל' דאצי' שהי' אז בבחי' הקטנות בתכלית וכנ\"ל שהיתה בבחי' נקודה תחי'<sup data-n=\"653\">269</sup> וכן למטה בכנס\"י לא הי' בהם רק גילוי האמונה הפשוטה הנ\"ל בנקודת לבבם. אך ע\"י החזרת פנים הנ\"ל נתגלה בהם בחי' הקטנות בבחי' פרצוף שלם בחיצוני' והיינו ענין ההכרה והקריאה בדיבור וההילוך כנ\"ל, שזהו בחי' פרצוף אדם דמוח ולב ומעשה בחיצוני' בלבד וזהו ענין המבואר בכתבי האריז\"ל בקריאת שם פסח מלשון פ\"ה ס\"ח<sup data-n=\"654\">270</sup>, והיינו שנמשכו המוחין הנגלים תמיד במח' עליונה ועכשיו ירדו להאיר בדיבור דווקא שלא ע\"י אמצעות המח' כו' כידוע שענין הדיבור הוא בחי' המל'<sup data-n=\"655\">271</sup> המקור לנבראים כו', וכן למטה בכנס\"י חלק הנשמה המלובש בגוף הוא הנק' בשם דיבור ואז ביצי\"מ הי' עיקר הגילוי למטה בנש\"י שבגופים כו'. וזהו ענין ופסח הוי' על הפתח, כי הנה בחי' פסח נק' בחי' המל'<sup data-n=\"656\">272</sup> שהוא פתח לנכנסין ויוצאין [כו'] כי",[["647","263","<b>שינה הנא' בלק\"א. . התפלה</b>: פי\"ג."],["648","264","<b>מתבוססת בדמיך</b>: יחזקאל טז, ו."],["649","265","<b>דבינה ליבא</b>: ת\"ז בהקדמה יז, א."],["650","266","<b>דרוח אייתי רוח</b>: ראה זהר תרומה קסב, רע\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשג. מאמרי אדה\"א בראשית ע' רל. וש\"נ."],["651","267","<b>דאימא כנ\"ל</b>: ב: דאא\"מ [ דאור אימא] כלל."],["652","268","<b>וידע אלקי'</b>: שמות ב, כה."],["653","269","<b>תחי'</b>: ב: תה\"י [ תחת היסוד]. ראה לעיל הערה 214."],["654","270","<b>פסח מלשון פ\"ה ס\"ח</b>: פע\"ח שער חה\"מ שכ\"א, פ\"א. פ\"ד."],["655","271","<b>הדיבור הוא בחי' המל'</b>: ראה זהר לך פו, ב. ע\"ח שער מוחין דצלם שכ\"ג, ספ\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפב. וש\"נ."],["656","272","<b>פסח. . המל'</b>: אוצ\"ל: פתח — ראה זהר בהקדמה א, ב. ועוד. לקמן מאמר ד\"ה והתהלכתי תרכ\"ב ובהערה 9."]]],[4801940654,"ע\"י בחי' המל' עולין כל ג' עולמות דבי\"ע בבחי' ביטול לעולם האצי' וגם כל האורות דאצי' נתגלים ונכנסים<sup data-n=\"657\">273</sup> ע\"י המל' בבי\"ע, וכן הוא בחי' הדיבור שמגלה העלם המשפיע למקבל וגם ע\"י דיבור המשפיע נעשה בחי' ביטול במוחין דמקבל בבחי' נקודה העדר ההתפשטות לגמרי כו'. וזהו ג\"כ ענין הפתח שיש בו משקוף ושתי מזוזות כו' והוא ענין ג' קווי המל' שזהו מבחי' חו\"ג דמל' שהוא [ענין] שתי המזוזות דימין ושמאל שפועלים העלאת המקבל והמשכת המשפיע, וב' בחי' אלו דהעלאה והמשכה באים כאחד דווקא ע\"י קו האמצעי המחברם שהוא בחי' משקוף שעל שתי המזוזות כו' וד\"ל.\n<b>והנה</b> בחי' זאת הדילוג שלמע' מסדר [ה]השתלשלות נק' מגבוה לנמוך (כי גבוה נק' מה שלמע' מהשתל' לגמרי שאינו בגדר מעלה ומטה כלל ונמוך נק' בחי' היותר אחרונה שבהשתל', ולכן כאשר בא האור מלמעלה מהשתלשלות לגמרי אז מוכרח שיתלבש במדריגה היותר אחרונה דהשתלשלות כי כל הגבוה יותר כו', ולכן נק' זה מגבוה לנמוך, משא\"כ כאשר בא האור בסדר ההשתלשלות נק' המשכה מלמע' למטה כו' להיות המשכה זאת הוא בגדר מקום דהשתלשלות מעומק רום לעומק תחת כו' וד\"ל), כאשר באה בהתלבשות בתוך הנמוך נק' בשם פסיחה בלשון הקדש וזהו ופסח הוי' על הפתח והיינו התלבשות שם הוי' שבהעלם עצמי' בבחי' המל' שנק' פתח. אך התלבשות זאת הייתה בבחי' מקיף על הפתח והיינו שהי' הגילוי בבחי' ראי' דלאסתכלא הנ\"ל שזהו בחי' [ה]מקיף דחי'<sup data-n=\"658\">274</sup> שלמע' מהשגה בפנימי' והתפעלות בלב, וזהו ענין ובמורא גדול זו גילוי שכינה<sup data-n=\"659\">275</sup> בבחי' מקיף עליהם עד שפעל בהם בחי' הביטול מכל וכל ולכן א' על הפתח מצד שלא נמשך בבחי' פנימי' בהשגה דבינה כנ\"ל (וכן בכתבי האריז\"ל שהמוחין הבאים לרחל [ב]לילה [ה]זאת נמשכים מבחי' מקיף<sup data-n=\"660\">276</sup> כו' וד\"ל). וזהו ג\"כ מה שנאמ' בשה\"ש מדלג על ההרים שהן המדות<sup data-n=\"661\">277</sup> ומוחין דאימא וגם על מדות דחכ' וכתר שבחכ'<sup data-n=\"662\">278</sup> עד רום המעלות בבחי' התלבשות רצה\"פ בהעלם עצמות להתלבש בבחי' המדות דחסד וטוב שבעצמי' על כל המדריגות האלו הי' הדילוג, וענין הדילוג היינו שלא נמשך בהם כלל בחי' קול דודי שהו\"ע המשכה הנעלמת שבהעלם עצמי שבאה לכלל גילוי אור כנ\"ל, שבחי' זאת לא נתגלה בכל סדר ההשתל' מבחי' היותר ראשונה דמח'<sup data-n=\"663\">279</sup> שבעצמי' עד בחי' היותר אחרונה שבמדות דאצי' שהוא בחי' יסוד הנק' סיומא דגופא<sup data-n=\"664\">280</sup> רק בבחי' המל' מגלה<sup data-n=\"665\">281</sup> בחי' זאת בבחי' מקיף כנ\"ל. והטעם לזה להיות שגילוי אור הזה הוא למע' מבחי' רצוא דבינה כנ\"ל, כי הבינה לא תוכל לתפוס רק מציאותו שהוא בחי' הארה",[["657","273","<b>נתגלה ונכנסים</b>: ב: מתגלים ונמשכים."],["658","274","<b>דחי'</b>: ב: ליתא."],["659","275","<b>ובמורא גדול זו גילוי שכינה</b>: תבוא כו, ח ובספרי שם. הגדה של פסח."],["660","276","<b>שהמוחין הבאים לרחל. . מקיף</b>: ראה פע\"ח שער חה\"מ שכ\"א, פ\"ד."],["661","277","<b>ההרים שהן המדות</b>: ראה סבא משפטים קט, ב ובמפרשים שם. תו\"ח שמות ח\"א יד, ד הערה 642."],["662","278","<b>ההרים שהן המדות ומוחין. . שבחכ'</b>: ראה גם תו\"ח כאן קיז, א."],["663","279","<b>דמח'</b>: ב: דח\"ח [ דחפץ חסד]."],["664","280","<b>יסוד הנק' סיומא דגופא</b>: ת\"ז בהקדמה יז, א. ראה הנסמן במאמרי אדה\"א קונטרסים ע' רכד."],["665","281","<b>מגלה</b>: ב: נגלה."]]],[4801940655,"וזיו בלבד וגם בחי' ביטול ההארה לגבי העצמי' כנ\"ל, אבל בבחי' גילוי העצמו' ממש למתב\"כ רק בחי' חכ' בה שורה עצמות אא\"ס<sup data-n=\"666\">282</sup> שהוא בחי' גילוי אור העצמי' כנ\"ל, ובחי' זאת האירה בעת יצי\"מ ולכן הי' מוכרח להיות דילוג המהות והיינו לדלג כל המדריגות שבהשתלשלות דאינם יכולים לקבל גילוי אור הזה מצד שאין להם שום תפיסא מצד שהוא למע' משרשם רק בבחי' כנס\"י אשר שרשם בהעלם העצמי' נתגלה בחי' זאת דאור העצמו' כו' וד\"ל.\n<b>והנה</b> דילוג זה הי' מצד עצמי' המשפיע ג\"כ שלא ע\"י ההעלאה מלמטה כלל, כי הצעקה שצעקו מן העבודה הייתה מן העבודה בלבד שלא היו יכולים לסבול המנגד כו' (עיין באוה\"ח<sup data-n=\"667\">284</sup> הק'<sup data-n=\"668\">283</sup> ) ואין זה נק' העלאה, כי העלאה הוא מלמטה למעלה שנמשך ע\"י התבוננו' דהשתלשלות שהם בגדר מעלה ומטה כו' וזה לא הי' ביכולתם מצד שכל המדריגות שבנפשם הי' בבחי' הסתר והעלם רק כח האמונה הפשוטה בלבד נתגלה בהם מצד המנגד כו', ועי\"ז וידע אלקי' כנ\"ל. ולכן הי' ביכולת[ו] להתלבש בקטנות דכנס\"י במקום שהם כי לגבי עצמות המשפיע כאשר מתגלה מצד עצמו אין מונע כלל, ולא עוד אלא שהי' זה בבחי' אור תגבורת התשוקה במשפיע ברב חסד ואה' רבה יתירה<sup data-n=\"669\">285</sup> יתר מכפי טבע התקשרות דאב לבן כאדם שרואה את בנו הקטן האהוב לו מאד שהוא מתבוסס בדמים בארץ למטה באין משגיח עליו שמתעורר ברוב עוז חמלה רבה ויתירה להצילו כו', ובחי' אה\"ר זאת ניתוסף ונתרבה בה גילוי אור יתר מכפי טבע ההתקשרות הנ\"ל דאב אל הבן כו'. והענין הוא דהגם שסומ\"ע עלה במח\"ת כנ\"ל להיותה סיבה לגילוי רצה\"פ הנה בחי' זאת נק' התעוררות העצמי' ממש בהעלם להיותה מקור לרצון ולכן נק' בשם בעהר\"צ<sup data-n=\"670\">286</sup> או רעדכ\"ר<sup data-n=\"671\">287</sup> כו', ואין לה ערך לבחי' העצמות ממש אשר אינו בגדר תפיסא כלל אפי' בבחי' התעוררות העצמי' הנ\"ל, ולכן מצד המנגד יעורר לבחי' העצמי' ממש להאיר בתוקף יותר בבחי' טבע ההתקשרות הנ\"ל ששרשה בבחי' סיבה הנ\"ל אשר הוא מקור כל רצון כנ\"ל, ובחי' זאת היא הגורמת הדילוג במהירות גדול לעבור על כל המדריגות שבהשתל' בכדי להתלבש בכנס\"י להצילם מצרתם כו'.\n<b>וזהו</b> קול דודי הנה זה בא מדלג על ההרים שהם הרים העליונים דהיינו מדות שבחכ\"ע ולמע' מעלה עד בחי' מדות שבעצמי' אא\"ס ועל כולם הי' הדילוג בכדי להתלבש בכנס\"י, שכח הדילוג דווקא בא מצד כח התעוררות העצמי' בכח ועוז גדול דחסד עליון שבעצמות ממש שנותן תוקף ועוז בבחי' התקשרות העצמי' דאא\"ס",[["666","282","<b>חכ' בה שורה עצמות אא\"ס</b>: ראה תניא פי\"ח (ובמ\"מ הגהות והע\"ק שם). פל\"ה בהג\"ה (ובמ\"מ הגהות והע\"ק שם). לקו\"ת במדבר יד, ב [ושם מציין: ”בע\"ח שער מ\"ז פ\"ג\" ולפנינו הוא פ\"ב ”ושער ב' במה\"ב פ\"א פ\"ג\" ולפנינו הוא בשער סדר אצי' ש\"ג]. תו\"ח שמות ח\"א ז, ד הערה 333."],["667","284","<b>באוה\"ח הק'</b>: ראה לקו\"ש ח\"ב ע' 508 סל\"ג."],["668","283","<b>עיין באוה\"ח הק'</b>: שמות ב, כג."],["669","285","<b>יתירה</b>: ב: ליתא."],["670","286","<b>בעהר\"צ</b>: ראה גם בענין בעל הרצון לקמן מאמר ד\"ה הפך ים הא' ובהערה 10. וש\"נ."],["671","287","<b>רעדכ\"ר</b>: ראה זהר ספדצ\"נ תרומה קעו, ב. תו\"ח בראשית לו, ג הערה 23. תצוה ח\"ב שעו, ג. לקמן ביאור למאמר ד\"ה והתהלכתי בתוככם תר\"ב על יד הערה 87."]]],[4801940656,"לנש\"י כו', וזהו נק' דילוג. ועוד הוא בחי' הדילוג לבוא למטה מטה בהתלבשות ובהעלם גדול בבחי' קטנות [ד]מוחין שבכנס\"י כמו<sup data-n=\"672\">288</sup> שהי' אז בבחי' אמונה פשוטה לבד כו', שזה הי' מצד [ה]אה' העצמי' דהתקשרות העצמי' דאא\"ס לכנס\"י מצד שרשם כנ\"ל, ובחי' זאת נק' פסיחה בלשון הקדש וכמשל המדלג בחלל העולם למרחוק יותר לא לפ\"ע הילוכו בסדר והדרגה שיש בזה שני ענינים, הא' במה שמדלג אויר גדול שאינו פוסע בו כלל שהוא ענין ההפסק שנק' דילוג בלה\"ק, והב' במה שמעמיד<sup data-n=\"673\">289</sup> רגל פסיעתו במקום הרחוק יותר ששם הוא עיקר הכוונה שלו לעמוד שם וזה נק' פסיחה בלה\"ק (כידוע דח' וע' מתחלפים כו'). וכך הוא למעלה הי' בבחי' הדילוג דאא\"ס לנש\"י ב' ענינים, הא' בחי' הדילוג על ההרים להפסיק אותם ולא להתלבש בהם בסדר ההשתל' מלמעלה למטה שנק' הרים כו', והב' הוא בחי' הדילוג להתלבש בכנס\"י<sup data-n=\"674\">290</sup>, וכח הדילוג הב' הוא מצד החכ' וכוונה נעלמה שבעצמי' אשר סומ\"ע עלה במח' תחילה (וזה בא מצד חכ' שבעצמי' שרש ומקור כח המוליד כנ\"ל). והדילוג הא' הוא נמשך מכח האה' עצמי' ששרשה ברצון עצמי' הנעלם שבהעלם עצמות ממש שלמע' מהתקשרות זאת<sup data-n=\"675\">291</sup> כנ\"ל, שזה גורם תוקף הדילוג לעבור על כל ההשתל' כו' וד\"ל. ולכן בתו' דמחכ\"ע נפקית<sup data-n=\"676\">292</sup> היינו מבחי' חכ' שבהעלם עצמי' המוליד לנש\"י שמצד זה נק' בנים ולכן ישראל מתקשראן באורייתא<sup data-n=\"677\">293</sup> מקור כח המולידם [ו]לכן נא' בחי' זאת דפסיחה על הפתח בבחי' מקיפים להאיר בהם, שהארה זאת נמשך מצד טבע התקשרות דאא\"ס לכנס\"י וכאב אל הבן וכמ\"ש בנים אתם. אבל בשה\"ש שהוא קדש קדשים<sup data-n=\"678\">294</sup> גילוי האה' הנגלה בבחי' תוקף ועוז יותר מכפי טבע ההתקשרות דאב אל הבן והיינו כאשר באה מצד המנגד דווקא, וכן בנין בהמ\"ק נאמר עליו זאת מנוחתי<sup data-n=\"679\">295</sup>, והיינו אחר שנלחם דוד באויבי ה' שעמדו על כנס\"י לכלותם וביערם מכל וכל עד בימי שלמה בנו באו מכל העמים לשמוע חכמתו שהיתה חכמת אלקי' בקרבו וא\"כ היו כולם נכנעים ובטלים לבחי' אלקות עד שלא הי' שום מנגד לה' ולישראל עמו הממשיכים גילוי אלקות למטה. וסיבה זאת הבאה מצד המנגד גורמת גילוי אור ושעשועים עצמי' בבן יותר מכפי טבע ההתקשרות (ובתחילה בעת הירידה להצלה נתלבש אה' זאת העצמי' בבחי' גבורות להנקם מאויבי בנו ואח\"כ כשמצילו<sup data-n=\"680\">296</sup> נתגלה בבחי' אה' זאת בחי' חסדים ותענוג להשתעשע ממנו יותר מכפי המדה דטבע ההתקשרות כנ\"ל), ולכן בבנין בהמ\"ק נתגלה שה\"ש שהוא ענין גילוי האה' בתוקף ועוז יותר מכפי המדה כנ\"ל, לכן נאמר בחי' הדילוג הנ\"ל והוא מה שדולג על ההרים שהוא כל בחי' ההשתלשלות ולא נתלבש בהם כלל שזהו הדילוג הא' שבא מצד אה' העצמי' כו' וד\"ל.",[["672","288","<b>כמו</b>: ב: ליתא."],["673","289","<b>שמעמיד</b>: שם: שמעורר( )."],["674","290","<b>בכנס\"י</b>: שם: במוחין( )."],["675","291","<b>זאת</b>: שם: ליתא."],["676","292","<b>בתו' דמחכ\"ע נפקית</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["677","293","<b>ישראל מתקשראן באורייתא</b>: ראה זהר אחרי עג, א."],["678","294","<b>בשה\"ש שהוא קדש קדשים</b>: ידים פ\"ד, מ\"ה."],["679","295","<b>זאת מנוחתי</b>: תהלים קלב, יד. ראה זבחים קיט, א. רמב\"ם הל' ביה\"ח פ\"א, ה\"ג. וראה גם לקו\"ש פקודי כרך טז ע' 470 ואילך. כרך כא ע' 460 ואילך ובהנסמן בהנ\"ל."],["680","296","<b>כשמצילו</b>: ב: כשמצליח."]]],[4801940657,"<b>ועם</b> כל הנ\"ל יובן ענין איסור אכילת חמץ בתוס' ביאור וטעם איסורו מזמן הקרבת הפסח, והיינו כי מחצות יום י\"ד ולמעלה מתחיל בחי' הדילוג שבהעלם עצמי' על כל ההשתלשות ששרשם [ב]בחי' מדות ולכן זמן הקרבת הפסח [הוא] בשש שעות אלו שמחצות היום ולמעלה שמורה על הדילוג דמדות בכלל שהם במספר שש כמ\"ש לך הוי' הגדולה<sup data-n=\"681\">297</sup> כו' (כי באמת יש בחי' המתגלה מצד הדילוג שעל המדות שאעפ\"י שלא נתגלה אפי' בבחי' מקיף, מ\"מ עבר בדרך מעבר עליהם כמשי\"ת לקמן בענין ד' כוסות<sup data-n=\"682\">298</sup> כו'), ולכן מצוה להשבית החמץ שלא יראה כלל, כי שרש החמץ הוא בבחי' הרצוא דמדות כנ\"ל ושרש גילוי אור המאיר ע\"י הקרבת הפסח הוא למע' מבחי' הרצוא דמדות עד שעובר בדרך מעבר עליהם, ולכן החמירה תו' על השבתתו דווקא מכל ביתו וגבולו כי בכולם מאיר אור הגדול הזה שבהעלם עצמי' ע\"י הדילוג דפסח. אך בזמן הקרבת הפסח וכן עכשיו בזמן הגלות שמאירה הארה זאת בכלל אז כשמשהה החמץ אינו פועל פגם בנפשו רק העדר האור בנפשו שזהו ביטול מ\"ע בלבד, אבל כשמקריב הוא בעצמו פסחו בפרט אז נמשך האור הנ\"ל בפרטי' על נפשו ואז כאשר משהה החמץ בביתו הוא פועל פגם בנפשו ולכן אז הוא בל\"ת, ולכן הל\"ת נאמר בלשון [יחיד] לא תשחט שזהו כל חד וחד כי שחיט אבל העשה נאמ' תשב[י]תו<sup data-n=\"683\">299</sup> לרבים<sup data-n=\"684\">300</sup> בכלל כו' וד\"ל.\n<b>ומעתה</b> יש להבין ענין המצה שמצוה לאכול בליל פסח<sup data-n=\"685\">301</sup> בערב ובזמן בהמ\"ק הי' המצוה לאכול אותה עם הפסח וכמ\"ש על מצות ומררים יאכלהו. דהנה ההפרש בין מצות הקרבת הפסח למצות אכילת הפסח הוא בזה, שהקרבת הפסח ע\"י שחיטתו וזריקת דמו על המזבח והקטר חלבי' העולה באש שלמעלה הוא עולה למעלה מעלה ומעורר בחי' העלם העצמי' ממש לבוא ולהמשיך בבחי' דילוג, ודילוג זה הוא המאיר בדרך מעבר על המדות שהוא בחי' ההשתל' בכלל עד רום המעלות בבחי' מדות שבעצמי' ממש. ולכן קרבן הזה הוא מבחי' חי כי הוא כלי לבחי' הדילוג הזה וע\"י מאיר אור הגדול בכל ההשתלשלות שהוא בחי' המדות בשרשם במדות שבעצמי' (שש[רש]ם הם בחי' חי כנ\"ל), ואז מאיר על נש\"י האור הזה בבחי' מקיף בכלל בזמן ההקרבה ובבחי' מקיף בפרט לכאו\"א בעת הקרבתו כנ\"ל, והארה זאת דבחי' מקיף מאיר בנש\"י ע\"י המדות שגם עליהם מאיר האור בדרך מעבר כו'. וכ\"ז האור נמשך ע\"י הקרבת הפסח הנק' אכילת מזבח כו' שהוא ענין עליות הבירורים המתבררים מנוגה ע\"י ארי' דאכיל קורבנין<sup data-n=\"686\">302</sup> וע\"י המזבח עליון שהוא בחי' המל' דאצי'<sup data-n=\"687\">303</sup>, והוא בחי' הבירור דשם ב\"ן שאינו מעורר למעלה בבחי'",[["681","297","<b>לך הוי' הגדולה</b>: דהי\"א כט, יא."],["682","298","<b>לקמן בענין ד' כוסות</b>: לא נמצא בהכת\"י שלפנינו. ראה הנרשם לקמן ברשימת הכת\"י בריש המאמר."],["683","299","<b>תשב[י]תו</b>: בא יב, טו."],["684","300","<b>לרבים</b>: ב: ל' ריבוי( )."],["685","301","<b>המצה שמצוה לאכול בליל פסח</b>: ראה לעיל הערה 5."],["686","302","<b>ארי' דאכיל קורבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שה\"א עט, ב הערה 13."],["687","303","<b>המזבח עליון. . המל' דאצי'</b>: במאמרי אדה\"ז תקס\"ו ע' רמג: כמ\"ש בזהר ע\"פ אש תמיד תוקד על המזבח. ראה גם זהר צו ל, סע\"א ואילך ובמק\"מ שם. אמור קה, א ובאוה\"ח שם. בהעלותך קנא, ב ובהגהות מהרח\"ו שם. תו\"ח יתרו ח\"ב רסט, סע\"ג ואילך ובהערה 22. סה\"מ תרל\"ה ח\"ב ע' שלא."]]],[4801940658,"אדה\"ע רק בבחי' מקיף בכלל ובפרט ע\"י המשכת אורות דתהו בבחי' התיקון כו'. אבל ע\"י אכילת הפסח שהוא בחי' אכילת אדם נעשה בירור [אחר בירור] ע\"י שם מ\"ה דאדה\"ע דאצי' ואז נמשך בחי' האורות דתוהו בבחי' התיקון בבחי' פנימי' ממש היינו להיות מזון וחיות פנימי' לבחי' אדה\"ע, וכן למטה בכל נשמה<sup data-n=\"688\">304</sup> בפרט נמשך בחי' האור העליון בבחי' חיות ומזון [ממש] כו'.\n<b>אך</b> כדי שיוכל לימשך אור העליון שבהעלם עצמות שנק' אור חדש ולבוא למטה בנש\"י ולהתלבש בבחי' מזון ממש כנ\"ל ע\"י [ה]הלבשה בבחי' מצוה<sup data-n=\"689\">305</sup> דווקא שהוא בחי' ההכרה בבחי' קטנות דווקא, ומזה נמשך חיות במוח ולב והיינו שיהי' נמשך אחרי אא\"ס אבינו האמיתי בכל לב ונפש שבמוח, וההמשכה זאת באה מצד ההכרה [דייקא] שבבחי' קטנות שזהו ע\"י ההלבשה לאור העליון בבחי' מצה דווקא עי\"ז יוכל לבוא אור העליון שהוא בחי' פסח בבחי' חיות ממש. והטעם לזה הנה מבואר למעלה בשרש ענין דצח\"מ, שלמטה בהשתל' בחי' החי גבוה מבחי' צומח אבל למע' מהשתל' בחי' הצומח גבוה מבחי' חי כי בחי' חי הוא בחי' השתל'<sup data-n=\"690\">306</sup> דאא\"ס בח\"ח העצמי<sup data-n=\"691\">307</sup> להיות רוצה להיטיב לזולתו שזהו ההלבשה<sup data-n=\"692\">308</sup> שלו בבחי' מקור להשתלשלות, אבל בחי' צומח הוא בחי' גילוי אור עצמות השעשועים מהעלם עצמית כנ\"ל. וכ\"ז הוא בחי' גילוי הצומח אבל עצם הצומח הוא כח הרוחני המלובש בעפר הארץ הוא הבא ומתלבש בבחי' הצמיחה בפרט, והוא כמ\"ש אשר זרעו בו שהוא נותן כל עצמות כחו בפרט א' בלבד שיוכל ג\"כ להצמיח לאין שיעור (אך בתנאי כאשר יחזור בבחי' העלאת היינו בחי' הביטול למקורו ע\"י רקבון הגרעין כו'). וזהו ענין אכילת מצה שאין בה שום טעם כלל שהטעם הוא בחי' התפשטות וגילוי הצמיחה אבל במצה מתלבש עצם הצמיחה, והו\"ע עצם כח התולדה שבנש\"י שהו\"ע אא\"ס עצמו המלובש בכל נשמה בפרט מצד שכבר נתן בחי' העצמי' שלו להם שזהו ענין סומ\"ע עלה במח' תחילה ומחמת זה בכחם להצמיח עד אין שיעור בגילוי הצמיחה, והיינו להמשיך אורות עליונים דעצמות השעשועים ע\"י תומ\"צ שלהם לאין שיעור ושעשועים אלו הוא בחי' אור חדש מהעלם העצמי' כנ\"ל בענין ונשמח בדברי תורתך<sup data-n=\"693\">309</sup> כו'.\n<b>ובכל</b> הנ\"ל יובן ענין המצה שמצוה לאכול בליל פסח דווקא, ולא בע\"פ מזמן ביעור חמץ כו', וגם מצוה לאוכלה עם הפסח, כי הנה בחי' ענין הפסח וענין המצה הם ב' דברים, ענין הפסח הוא ענין הדילוג והקפיצה מלמעלה מעלה על כל סדר ההשתל' דע\"ס כנ\"ל שהוא [בחי'] המשכה מעצמו' אור אבא הנק' פנימי' אבא ששרשו בהעלם עצמות אא\"ס שקדם לרצון ושעשועים העצמי', שזהו פנימי' עתיק<sup data-n=\"694\">310</sup>",[["688","304","<b>בכל נשמה</b>: ב: בכלל לנשמה."],["689","305","<b>מצוה</b>: שם: מצה."],["690","306","<b>השתל'</b>: שם: התלבשות."],["691","307","<b>בח\"ח העצמי</b>: שם: בחי' העצמי'."],["692","308","<b>שזהו ההלבשה</b>: שם: שהיא התלבשות."],["693","309","<b>כנ\"ל בענין ונשמח בדברי תורתך</b>: ראה לעיל ע' נא."],["694","310","<b>פנימי' אבא. . פנימי' עתיק</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. לקו\"ת נצבים מט, ד. תו\"ח שמות ח\"א כג, א הערה 951."]]],[4801940659,"עונג הנעלם שבעצמי' מהעלאת מ\"ן דמעה\"ת דנש\"י בגופים ע\"י תומ\"צ שלהם דווקא, שזהו ענין סומ\"ע עלה במח' תחילה ובמי נמלך כו', אשר זהו סיבה נעלמת לגילוי רצה\"פ להיטיב כנ\"ל, ובחי' זאת לא תוכל להאיר בהשתלשלות כלל רק בבחי' מעבר עליהם בלבד כנ\"ל. אך מבואר למעלה שבענין הדילוג יש להבין ענינם<sup data-n=\"695\">311</sup> הא' ענין<sup data-n=\"696\">312</sup> ההפסק שמפסיק הפסק גדול ומרחק<sup data-n=\"697\">313</sup> שאינו פוסע בו כלל, והב' המקום שאליו הי' פנימי' הכוונה להעמיד רגל פסיעתו בו, לכן בחי' אור הגדול הזה דהארת פנימי' אבא שהוא פנימי' עתיק כנ\"ל שלא יוכל להאיר בהשתל' כנ\"ל הוא המתלבש בנש\"י שבגופים דווקא (ולא בבחי' שרש הנשמה שגם שם אינו מאיר אלא בבחי' מקיף כנ\"ל). אך כח ואור הזה הוא צריך להתלבש באיזה לבוש בכדי שעל ידו יוכל להאיר אור גדול כזה בנשמה שבגוף ותוכל הנשמה לקבלו, הנה לזה הוא ענין המצה שהוא ענין ההלבשה של אור הגדול הנ\"ל שמתלבש בבחי' הקטנות המוחין ביותר שהיא האמונה וההכרה כתינוק המכיר לאביו שהוא לחם עני דמצה כנ\"ל, שלמטה מן הדעת והשכל (אך שרשה למעלה מן הדעת שהיא בחי' פנימי' ועצמי' הכוונה כו' וד\"ל). וזהו ענין אכילת הפסח בליל ט\"ו דווקא על מצות כו' שזהו כדי שיהי' זכרון לב' הבחי' שהי' בעת יצי\"מ שהו\"ע הדילוג הגדול דגילוי שכינה שנגלה עמהם<sup data-n=\"698\">314</sup> ממ\"ה כו', וההלבשה שלו<sup data-n=\"699\">315</sup> בבחי' הקטנות דהכרה שבנש\"י שנק' חסד נעוריך כנ\"ל, וזה הי' בליל ט\"ו דווקא, אך התחלת הדילוג הזה לעבור על כל ההשתל' בדרך מעבר הי' מתחלה ביום י\"ד כנ\"ל.\n<b>ונמצא</b> שענין הפסח עם המצה הם ב' ענינים כי עיקר ענין הפסח הוא הדילוג ש[ע]ל כל ההשתל' והמצה הוא התלבשות בנש\"י כו'. אמנם עכ\"ז שניהם ענין א' הוא משום דהא בהא תליא דווקא שכאשר באה ההתעוררות החזקה<sup data-n=\"700\">316</sup> מצד עצמות [עוז] אור<sup data-n=\"701\">317</sup> אה\"ר ורב חסד העליון שזהו בא מצד העצם ממש שלמע' מטבע התקשרות [דאב אל הבן כנ\"ל שזהו גורם הדילוג הנ\"ל. . . ממילא בא בבחי' הלבשה זאת דקטנות דמצה שהוא המקום שירד לשם ולשם הוא מדלג ממקומו הגבוה והיינו כנ\"ל בענין המצה שאין בה שום טעם מעורר בה עצם הצמיחה אשר זרעו בו כו' שזהו בא מצד בחי' העצמי' שלמעלה מטבע ההתקשרות דאב אל הבן] ולכן בחי' המצה הוא בחי' לבוש לאור המלובש בו ושרשה למע' מאור המלובש (כמו המשל ששרשו גבוה מן הנמשל<sup data-n=\"702\">318</sup> כידוע בענין השבח דשלמה במשלים דווקא כו'), שהוא ענין האור הבא ע\"י אכילת הפסח שהוא בחי' מזון וחיות לנש\"י המלובשים בגופים להיות נמשכים אחרי אא\"ס אבינו האמיתי<sup data-n=\"703\">319</sup> בכל לב ונפש שזהו אור פנימי' בלבד. אבל שרש הלבוש הוא בבחי' אור המקיף שהוא ענין הדילוג בכח ועוז לעבור בדרך",[["695","311","<b>להבין ענינם</b>: ב: ב' עניני'."],["696","312","<b>ענין</b>: שם: ליתא."],["697","313","<b>הפסק גדול ומרחק</b>: שם: מרחק גדול."],["698","314","<b>עמהם</b>: שם: עליהם."],["699","315","<b>שלו</b>: שם: ליתא."],["700","316","<b>החזקה</b>: שם: ליתא."],["701","317","<b>אור</b>: שם: ליתא."],["702","318","<b>המשל ששרשו גבוה מן הנמשל</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ס\"ע תקכב ואילך. וש\"נ."],["703","319","<b>אא\"ס אבינו האמיתי</b>: ב: אבינו."]]],[4801940660,"מעבר שזהו למע' מעצם טבע ההתקשרות וסיבה זאת עצמה היא הגורמת לצמצם א\"ע ולהלביש א\"ע בלבוש. ובזה יובן שמה שנאמ' בשה\"ש קול דודי הנה זה בא מדלג ולא נזכר להיכן הוא מדלג רק אומר מדלג על ההרים מקפץ על הגבעות, שהכוונה לדלג אותם בלתי התלבשות בהם רק דרך מעבר כו', ובתו' מפרש להיכן דילוגו כמ\"ש ופסח הוי' על הפתח שזהו בחי' המל' שנק' פתח ושער כנ\"ל והוא בחי' שרש כנס\"י למטה שגם המה בחי' פתח לנכנסין שהו\"ע כל הבירורים העולים שהוא ע\"י נש\"י שבגופים כו', וגם פתח ליוצאין להיות נמשך ע\"י כל אורות האצי' למטה בעשי' וכמ\"ש מי כעמך ישראל<sup data-n=\"704\">320</sup> גוי אחד בארץ היינו להמשיך בחי' אחד שהוא בחי' יחו\"ע בארץ שהוא בחי' עשי' הגשמי', והדילוג דאא\"ס הי' בשביל נש\"י שבגופים בכדי לשכון עליהם בבחי' אור מקיף ולהדבק בהם בבחי' או\"פ כו', ונמצא דמצה ופסח שניהם ענין אחד שהוא הדילוג מגבוה לנמוך, רק שהפסח הוא הדילוג ממקומו והמצה הוא בחי' ירידתו והתלבשותו למטה מטה כו', ושניהם באים משרש אחד ממש שהוא ענין תוקף האה' שהאירה מצד המנגד שהוא למע' מטבע ההתקשרות דאב אל הבן כנ\"ל וד\"ל.\n<b>וזהו</b> שאו' בהגדה מצה זו שאנו אוכלים כו' ע\"ש שלא הספיק כו' עד שנגלה עליהם מלך כו', פי' מצה זו הוא ענין ירידתו למטה בהתלבשותו בבחי' הקטנות דאבא שהוא בחי' ההכרה בלבד שיש בה תוקף וחוזק ההתקשרות [ל]אחד האמיתי שהוא בחי' העלם העצמי' שלמע' מגילוי אור העצמי'<sup data-n=\"705\">321</sup> כו' וזהו שלא הספיק להחמיץ [כי במקום גילוי העלם האור בטל ונכלל בו לגמרי ולכן לא הספיק להחמיץ] (כי שרש החמץ הוא בבחי' הרצוא שעולה בהעלאה מצד ההרגשה בבחי' גילוי האור ובחי' הגילוי נתבטל ונכלל מצד התגלות העלם העצמי' לבוא לידי גילוי כנ\"ל). וזהו עד שנגלה עליהם בבחי' מקיף המלובש בלבוש דמצה (כידוע שבכל לבוש מתלבש מבחי' המקיפים<sup data-n=\"706\">322</sup> כו' ופסח זה כו' ע\"ש שפסח כו' שהו\"ע אור העליון הנ\"ל הבא בבחי' חיות ומזון ע\"י הלבוש שבחי' זאת נק' פסיחה כנ\"ל, וזהו שאנו אוכלים דקאי על אכילת הפסח בליל ט\"ו שהו\"ע אור פנימי הנ\"ל, וע\"כ אמר על מצות ומרורים יאכלהו שהוא המצוה שצריך וחובה לאכול מצה בליל א' דפסח דווקא בכדי להמשיך ע\"י המצה אור הגדול והעליון [הנ\"ל] בבחי' חיות ומזון ממש משום דהא בהא תליא כנ\"ל דשניהם באו מבחי' תוקף העלם העצמי' שלמע' מטבע ההתקשרות [דאב אל הבן] כנ\"ל וד\"ל.",[["704","320","<b>מי כעמך ישראל</b>: דהי\"א יז, כא [ושם: ומי]. ראה גם לקמן מאמר ד\"ה וידבר כו' אלה הם מועדי תר\"כ על יד הערה 67."],["705","321","<b>העצמי'</b>: ב: ליתא."],["706","322","<b>שבכל לבוש מתלבש מבחי' המקיפים</b>: ראה גם לקמן מאמר ד\"ה ענין העבודה דיוה\"כ ובהערה 14."]]],[4801940082,"<b>יו\"ט ב' של פסח בפאריטש תר\"י</b>\n<b>הפך</b> ים ליבשה<sup data-n=\"707\">1</sup> בנהר יעברו ברגל כו', הפך בקי\"ס יעברו לעתיד, קי\"ס הי' הכנה לגליא דאורייתא<sup data-n=\"708\">2</sup> כן לעתיד בשביל התגלות סתים דאורייתא טעמי תורה יהי' בנהר, כמ\"ש והניף ידו על הנהר<sup data-n=\"709\">3</sup> כו'. וצ\"ל למה ניתנה התו' ע\"י משה וסתים דאורייתא ע\"י משיח. הנה אמרז\"ל במס' מנחות, יבוא טוב<sup data-n=\"710\">4</sup> ויקבל טוב מטוב לטובים, יבא טוב זה משה מבואר שגם לטעמי תורה משה כלי מוכן. ולהבין כ\"ז י\"ל ההפרש בין גליא דאורייתא לסתים דאורייתא, ופי' סתים שאינו בגדר גילוי כלל ונקרא עדן עין לא ראתה [עדן סתימאה<sup data-n=\"711\">6</sup> (חכ' שבתענוג)] אלקים זולתך יעשה למחכי<sup data-n=\"712\">5</sup> לו, עין לא ראתה עין דמשה וכמ\"ש וראית את אחורי<sup data-n=\"713\">7</sup> ופני לא יראו רק יעשה למחכי לו למאן דבעי למנדע לי'<sup data-n=\"714\">8</sup> במילי דחכמתא, רזין דאורייתא, וע\"י משה לא נתגלה כ\"א נגלה שבתו' שניתנה לשעורין וגבולין רמ\"ח מ\"ע כו', ונק' נובלות חכמה של מעלה תורה<sup data-n=\"715\">9</sup>, ופי' נובלות יובן עפ\"י ג' משלים ב' גשמים אחד רוחני, א' מחבית המלאה ביותר נוטפת טיפין טיפין, והטיפין נובלות רק שמורה על מליאות החבית ביותר. והב' משערות שבאדם, אבר מיוחד ומקושר עם הנפש ויכאוב בחתכו משא\"כ בחיתוך השערות, הגם שיונקים מהמוח, אבל הוא דרך מותרות ונובלות. ומשל הרוחני המשכת שכל מן המשכיל שהוא רק מציאות אור של תולדה, אבל כח המשכיל מיוחד בנפש. עד\"ז יובן למעלה הנה העצמות מובדל ומרומם גם מגדר א\"ס, ותחלת הבריאה הי' ע\"י צמצום ונקודת חכמה עליונה שנמשך א\"ס בחכ' בבחי' צמצום הנקודה והקו, והנה מקור החכ' הוא הרצון וגם לרצון יש מקור ונק' בעל הרצון<sup data-n=\"716\">10</sup>. ונמצא יש כאן ג' מדרי' א' גילוי אור בלבד חכמה דאצי' וחסד ומל' דא\"ס, והרצון נק' מקור כתר מל', ויש מקור למקור ונק' בעל הרצון. והנה גם מקור למקור זה הוא הארה לגבי העצמיות, והסיבה לזה הוא עונג הנעלם שבעצמותו ונק' כוונה נעלמה,",[["707","1","<b>הפך ים ליבשה</b>: דרוש ר' הלל.\nלקמן באים ששה דרושים לפסח מר' הלל שנדפסו בספר אמרי נעם (ראה לקמן ברשימת הכת\"י) ונסדרו כאן באותו הסדר שהם מופיעים שם."],["708","2","<b>הפך ים. . קי\"ס. . לגליא דאורייתא</b>: תהלים סו, ו. ראה שער האמונה לב, ב ובהערה 9. תו\"ח בשלח ח\"א קמח, ג ובהערה 146. פלח הרמון בשלח ע' קס. לקמן מאמר ד\"ה שרש ענין קי\"ס על יד הערה 38. הנסמן בהערה הבאה."],["709","3","<b>לעתיד. . סתים דאורייתא. . והניף ידו על הנהר</b>: ישעי' יא, טו. ראה גם לקמן מאמר ד\"ה הפך ים הב' והג' בתחלתם. ד\"ה והניף הכהן אותם הב' על יד הערה 17."],["710","4","<b>במס' מנחות יבוא טוב</b>: נג, ב."],["711","6","<b>עדן סתימאה</b>: ראה גם תו\"ח שמות ח\"א ה, ג הערה 250."],["712","5","<b>עדן עין לא ראתה. . למחכי</b>: ישעי' סד, ג (ושם: למחכה)."],["713","7","<b>וראית את אחורי</b>: תשא לג, כג."],["714","8","<b>למחכי לו למאן דבעי למנדע לי'</b>: ראה זהר ח\"ש קל, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקעט. וש\"נ. תו\"ח בראשית לה, ג ובהערה 49."],["715","9","<b>נובלות חכמה של מעלה תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["716","10","<b>בעל הרצון</b>: ראה גם בענין בעל הרצון לעיל מאמר ד\"ה להבין שרש ענין פסח ומצה על יד הערה 286. לקמן ד\"ה אם בחוקותי הא' על יד הערה 71 ואילך. ד\"ה והתהלכתי תרכ\"ב על יד הערה 54. ד\"ה רפאיני הא' על יד הערה 93. פלח הרמון תשא ע' שיד. תו\"ח ויקהל ח\"ב תיב, ד ובהערה 817. סה\"מ תרל\"ח ע' ת ובהערה 20."]]],[4801940148,"והוא כמאמר במי נמלך<sup data-n=\"717\">11</sup> בנשמתן של צדיקים וידוע הלשון בשם הרה\"מ ז\"ל, צפיות העונג<sup data-n=\"718\">12</sup> מנשמות ישראל שיקבלו עליהם עומ\"ש עפ\"י התורה והמצות הביאו לכלל רצון לעולמות, ועי\"ז נתגלה מטבע הטוב להיטיב<sup data-n=\"719\">13</sup> כו'.\n<b>והנה</b> בד\"כ יש כאן ב' מדרי', א' סיבה הנעלמה, והב' מה שבא לכלל בעל הרצון, דילוג הערך ממהות למהות, ונק' נתינת עצמותו (בל\"א דער אריבער טראג). ובע\"ח נק' ב' מדרי' הנ\"ל פנימיות אבא ופנימיות עתיק, פנימיות אבא חכ' ומקור החכ' בחסד ומל' דא\"ס, ופנימיות עתיק ענג הנעלם ורצון הנעלם שנק' בעל הרצון מקור לרצון ולחכ'. פנימיות<sup data-n=\"720\">14</sup> לא נתגלה ע\"י משה, והגם שיש רזין וסודות סתימין המתגלין ע\"י יריאיו וכמ\"ש סוד ה' ליריאיו<sup data-n=\"721\">15</sup> הוא רזין לגבי גליא דאורייתא, כמו ששמעתי מאדמו\"ר ואדמו\"ר מאדמו\"ר<sup data-n=\"722\">16</sup> מבואר בכתבי האריז\"ל וז\"ל מקצת אקדמות ששמעתי ממורי זלה\"ה<sup data-n=\"723\">17</sup>, פי' מקצת אקדמות הארה ונובלות מהרזין. והענין הוא הנה כתיב ארוכה מארץ מדה ורחבה מיני ים<sup data-n=\"724\">18</sup> וקאי על טעמי תורה סתים דאורייתא, הנה רחבת הים ואורך היבשה ישנו בתורה הנגלות לנו ע\"י משה, ים עומק רום שבתורה פנימיות התורה כמו שהיא בעלמא דאתכסיא, והם רזין וסודות התורה דעכשיו והוא כמו הים שמכסה על הברואים שבתוכו, כן ברזין דאורייתא ישנו סודות בעילוי אחר עילוי בעמק אחר עמק אבל אין בהם התחלקות, ונק' עומק ורוחב, ולא אורך, ויובן משכל האדם שרוחב השכל הוא העומק שהוא מה שמשיג השכל ברוחב ועומק, אבל אורך השכל נק' ירידות השכל למקבל, כמו וידבר שלמה<sup data-n=\"725\">19</sup> כו' שהוא ריבוי השגות שונות שכל אחד תחתון מחברו אבל טעמי תורה ארוכה מארץ כו'. ומעתה י\"ל למה לא נתגלו טעמי תורה ע\"י משה, הנה הגם שמשה הי' מרכבה למדר' גבוה מאד לבחי' אבא דאצי' מקור החכ' עכ\"ז לא הי' אפשר לו",[["717","11","<b>במי נמלך</b>: ראה ב\"ר פ\"ח, ז. רו\"ר פ\"ב, ג. לקו\"ש פ' החודש כרך טז ע' 487 בהערה."],["718","12","<b>בשם הרה\"מ ז\"ל צפיות העונג</b>: ראה גם לקמן מאמר ד\"ה הפך ים תרכ\"ד על יד הערה 29. ד\"ה וידבר וכו' אלה הם מועדי תר\"כ על יד הערה 72. ד\"ה אם בחוקותי תר\"י על יד הערה 93. פלח הרמון תולדות עט, סע\"ב ואילך. ויחי קכט, א. וארא ע' מב. בשלח ע' קפה. ע' קצט. יתרו ע' רנב. משפטים ע' רעו. תרומה ע' רפד. מג\"א ע' תו. שה\"ש ר\"ע 78. ע' 100. ע' קכו [ושם: כמו ששמעתי מאדמו\"ר שליט\"א בשם הרה\"מ נ\"ע]. וראה גם כתבי הרח\"א ביחובסקי — ברוקלין תש\"נ — ע' רלח ד\"ה עמוד ב' שמציין לעמק המלך."],["719","13","<b>מטבע הטוב להיטיב</b>: ראה שער היחוד והאמונה פ\"ד ובמ\"מ הגהות והע\"ק לשם. מאמרי אדה\"א קונטרסים ע' ה. וש\"נ. תו\"ח בראשית ל, ב הערה 4. לקמן מאמר ד\"ה והניף ידו תר\"י על יד הערה 17."],["720","14","<b>פנימיות</b>: אוצ\"ל: פנימיות התורה."],["721","15","<b>סוד ה' ליריאיו</b>: תהלים כה, יד. ראה גם תו\"ח בשלח ח\"א קסז, ב. וש\"נ."],["722","16","<b>ואדמו\"ר מאדמו\"ר</b>: כנראה הכוונה לאדה\"ז."],["723","17","<b>מקצת אקדמות ששמעתי ממורי זלה\"ה</b>: ראה ע\"ח בהקדמה (בכותרת זאת לוקחת ומועתקת מספר פע\"ח שבדמשק מכת\"י הרח\"ו ז\"ל). ושם: בקצת הקדמות שקבלתי."],["724","18","<b>ארוכה מארץ מדה ורחבה מיני ים</b>: איוב יא, ט. ראה גם לקמן מאמר ד\"ה בשברי לכם תקצ\"ט על יד הערה 97. תו\"ח פקודי ח\"ב תנט, ג ובהערה 414."],["725","19","<b>וידבר שלמה</b>: מל\"א ה, יב [בהוספת תיבת ”שלמה\" — ראה תו\"ח בשלח ח\"א רכד, ג הערה 145]."]]],[4801940212,"להמשיך עצמיות א\"ס ב\"ה בכנס\"י ובעולמות בי\"ע<sup data-n=\"726\">20</sup> רק שהמשיך חכ' דאצי' מקור ההשתלשלות, גם למעלה מאצי', כי כמה חכ' יש חכ' דאצי' ח\"ס דעתיק ואריך וחכ' הקדומה דא\"ק ומל' דא\"ס שהוא מה שעלה במחשבתו אנא אמלוך<sup data-n=\"727\">21</sup> וגם ברצון דלהיטיב ישנו בחי' חכ' הפשוטה אעפ\"כ לא זהו בחי' עצמיות ממש.\n<b>והענין</b> הוא הנה כתיב במשיח ישכיל עבדי<sup data-n=\"728\">22</sup> ירום וגבה ונישא מאד, ישכיל פי' שימשיך ע\"י ביטולו בבחי' עבדי כח המשכיל (רזין דאו'), ירום מאברהם<sup data-n=\"729\">23</sup> ראי' דחכ' אברהם אוהבי<sup data-n=\"730\">24</sup>, וגבה מיצחק<sup data-n=\"731\">25</sup> קו השמאל בג\"ה, ונישא מיעקב<sup data-n=\"732\">26</sup> קו האמצעי דת\"י ומגיע עד הכתר<sup data-n=\"733\">27</sup>, מאד מאדם<sup data-n=\"734\">28</sup>. שמה שעביד מנא רברבא<sup data-n=\"735\">29</sup> וקרו<sup data-n=\"736\">30</sup> בגרמי' חכים ועביד מנא רברבא וקרו בגרמי' מבין בא לכלל מקור לחו\"ב, ציור אדם, ומלך המשיח ימשיך מכי לא אדם הוא<sup data-n=\"737\">31</sup> חכ' שבתורה שהוא וחכמתו חד<sup data-n=\"738\">32</sup>. ונק' מלך יחיד<sup data-n=\"739\">33</sup> גילוי עצמותו, ונקרא מלך מלכי המלכים הקב\"ה<sup data-n=\"740\">34</sup>, מלכים רצון דלהיטיב ואנא אמלוך, מלכי חו\"ב שבשעשועים כמ\"ש שעשועים יום יום<sup data-n=\"741\">35</sup>, מלך שעשועים עצמם, וגם זה הוא רק גילוי הארה לגבי העצמיות שנק' קב\"ה. וזה יתגלה ע\"י משיח וקבלת עול דהע\"ה, וכמ\"ש ודוד הקים עול עולו של תורה<sup data-n=\"742\">36</sup>, והוא ע\"י יראה תתאה (דעקבי דמשיחא) יתגלה יראה עילאה ביטול בעצם, וכמ\"ש והריחו ביראת ה'<sup data-n=\"743\">37</sup> יראה עילאה. וזהו אל יתהלל חכם<sup data-n=\"744\">38</sup> בחכמתו כו', חכם אברהם, גבור יצחק, עשיר יעקב, כ\"א בזאת<sup data-n=\"745\">39</sup> קבלת עומ\"ש זהו כלי להשכל וידוע אותי רזין דאורייתא. וזהו בנהר יעברו לעתיד, כי כדי שיתגלה כח זה צריך שיתגלה תחלה העלם הנהר (בחי' בינה<sup data-n=\"746\">40</sup>, אז יתגלה חכ' שבעצמיות), וכמ\"ש עד יעבור<sup data-n=\"747\">41</sup> עמך ה' עד יעבור עם זו קנית, עד",[["726","20","<b>שמשה. . להמשיך. . בי\"ע</b>: ראה גם תו\"א בא ס, ב."],["727","21","<b>ומל' דא\"ס. . אנא אמלוך</b>: ראה גם לקמן מאמר ד\"ה הפך ים הב' על יד הערה 18. ד\"ה והניף ידו תר\"י על יד הערה 16. ד\"ה הנה וכו' והצרוע תקצ\"ט על יד הערה 19. ש\"א נה, ב ובהנסמן במ\"מ לשם."],["728","22","<b>ישכיל עבדי</b>: ישעי' נב, יג [ושם: ונישא וגבה וראה בסמוך בפנים]."],["729","23","<b>ירום מאברהם</b>: ראה תנחומא תולדות יד. שה\"א פט, א ובהערה 18. תו\"ח בשלח ח\"א רד, ד."],["730","24","<b>אברהם אוהבי</b>: ישעי' מא, ח."],["731","25","<b>וגבה מיצחק</b>: ראה זהר וישב קפא, ב."],["732","26","<b>ונישא מיעקב</b>: בתנחומא שם וגבה מיעקב — ראה הערה 22."],["733","27","<b>קו האמצעי. . הכתר</b>: מובא במאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרמה בשם הע\"ח. ראה שערי אורה לר\"י גיקטלייא שער ה (ע' סג)."],["734","28","<b>מאד מאדם</b>: ראה לקו\"ת להאריז\"ל תשא לג, ה. שה\"א פט, א ובהערה 2. תו\"ח תצוה ח\"ב שלב, א."],["735","29","<b>שעביד מנא רברבא</b>: ראה זהר (רע\"מ) בא מב, ב."],["736","30","<b>וקרו</b>: אוצ\"ל: וקרא."],["737","31","<b>מכי לא אדם הוא</b>: שמו\"א טו, כט."],["738","32","<b>שהוא וחכמתו חד</b>: תניא פ\"ב."],["739","33","<b>מלך יחיד</b>: נוסח ברכת ישתבח."],["740","34","<b>מלך מלכי המלכים הקב\"ה</b>: ברכות כח, ב."],["741","35","<b>שעשועים יום יום</b>: משלי ח, ל."],["742","36","<b>ודוד הקים עול עולו של תורה</b>: שמו\"ב כג, א [ושם: דוד. . הקם על]. ראה במדב\"ר פי\"ח, כא. הנסמן במאמרי אדה\"א שמות ח\"א ע' רכה."],["743","37","<b>והריחו ביראת ה'</b>: ישעי' יא, ג."],["744","38","<b>אל יתהלל חכם</b>: ירמי' ט, כב."],["745","39","<b>כ\"א בזאת</b>: ירמי' שם, כג."],["746","40","<b>הנהר. . בינה</b>: זהר (אדרא דמשכנא) משפטים קכג, ב."],["747","41","<b>עד יעבור</b>: בשלח טו, טז."]]],[4801940267,"יעבור בהעברה זאת, להמשיך שם ה' יו\"ד חכ'<sup data-n=\"748\">42</sup> קוצו ש\"י כתר<sup data-n=\"749\">43</sup> הממוצע<sup data-n=\"750\">44</sup> בין המאציל לנאצלים, עד יעבור עמך סתם לעתיד בעברנו בנהר יתגלה העלם עצמיות ה' לעם זו שקנית. וזהו אהי' אשר אהי'<sup data-n=\"751\">45</sup> אנא זמין לאתגלאה<sup data-n=\"752\">46</sup>, אהיה בכתר<sup data-n=\"753\">47</sup> מקור העולמות, אשר אהי' חכ' וכתר שבעצמיות, שם נשמחה בו, בעצמותו, וכמ\"ש יחיינו מיומים ביום השלישי יקימנו ונחי' לפניו, מיומים ב' ימים דחו\"ב<sup data-n=\"754\">48</sup> שבשעשועים, ביום השלישי הוא יום אשר יודע לה'<sup data-n=\"755\">49</sup> כו', ונשגב ה' לבדו<sup data-n=\"756\">50</sup> כו'. והנה הגם שהגילוי יהי' ע\"י משיח התעוררות לגילוי זה הי' ע\"י משה שהי' כלי מוכן לפנימיות אבא ורק במשה נתעורר וניתן כח ועוז לרזין דאורייתא והוא ע\"י גליא דאורייתא שניתנה ע\"י משה (ואז עין בעין יראו<sup data-n=\"757\">51</sup> עין דמשה ומשיח).",[["748","42","<b>יו\"ד חכ'</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["749","43","<b>קוצו ש\"י כתר</b>: ראה אגה\"ת פ\"ד. תו\"ח בא ח\"א קכב, א הערה 360."],["750","44","<b>כתר הממוצע</b>: ראה ע\"ח (ש' דרושי אבי\"א) שמ\"ב, פ\"א. לקמן מאמר ד\"ה לה\"ע קי\"ס תרכ\"א על יד הערה 23. תו\"ח שמות ח\"א יא, ג הערה 509."],["751","45","<b>אהי' אשר אהי'</b>: שמות ג, יד."],["752","46","<b>אנא זמין לאתגלאה</b>: ראה זהר ויקרא יא, א. אחרי סה, ב."],["753","47","<b>אהיה בכתר</b>: זהר ויקרא יא, א. ראה מאמרי אדה\"א דברים ח\"א ע' רכו. וש\"נ."],["754","48","<b>יחיינו מיומים. . דחו\"ב</b>: הושע ו, ב. ראה גם ש\"א נז, ב ובהערה 32."],["755","49","<b>יום אשר יודע לה'</b>: ראה זכרי' יד, ז."],["756","50","<b>ונשגב ה' לבדו</b>: ישעי' ב, יא. יז."],["757","51","<b>עין בעין יראו</b>: ישעי' נב, ח."]]],[4801940083,"<b>לעת ערב</b>\n<b>הפך</b> ים<sup data-n=\"758\">1</sup> ליבשה<sup data-n=\"759\">2</sup> בנהר יעברו ברגל כו', פי' כמו הכנה למ\"ת הי' קי\"ס<sup data-n=\"760\">3</sup>, כך לעתיד כתיב והניף ידו על הנהר<sup data-n=\"761\">4</sup> כו'. וזהו בנהר יעברו לשון עתיד, ועי\"ז נקבל רזין דאורייתא ע\"י משיח<sup data-n=\"762\">5</sup>. ולהבין זה בתוס' ביאור, יש להקדים ההפרש בין ים לנהר ע\"ד הרוחני, הנה מחשבה נמשל לנהר, ודבור לים<sup data-n=\"763\">6</sup>. ויובן תחלה ההפרש שבין ים לנהר גשמי, הנה הנהר נובע ממעינות מן התהום ונק' מקורא דתהום רבא, אויר רוחני המוצא מים. ויש ב' מיני מעינות מעין סתום ומעין גלוי, מעין סתום תחלת המעין סמוך להתהום ואין בו מים עדין ונק' היולי כמו שחקרו הפלסופים שיש חומר היולי<sup data-n=\"764\">7</sup>",[["758","1","<b>הפך ים ליבשה</b>: דרוש ר' הלל.\nראה הנרשם ברד\"ה שלפנ\"ז."],["759","2","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["760","3","<b>הכנה למ\"ת הי' קי\"ס</b>: ראה שער האמונה לב, ב ובהערה 9. הנסמן במאמר שלפנ\"ז בתחילתו."],["761","4","<b>והניף ידו על הנהר</b>: ישעי' יא, טו."],["762","5","<b>והניף. . רזין. . משיח</b>: ראה גם לעיל בהמאמר שלפנ\"ז. וש\"נ."],["763","6","<b>מחשבה נמשל לנהר ודיבור לים</b>: ראה גם לקמן מאמר ד\"ה והניף הכהן הב' על יד הערה 52. ד\"ה והחרים תשי\"ג (סה\"מ תשי\"ג ע' 392]."],["764","7","<b>הפלסופים שיש חומר היולי</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. שער קיצור אבי\"ע ש\"נ, פ\"י. תו\"ח תשא ח\"ב שפד, ד הערה 48. מכתב ה' מ\"ח תש\"י נדפס באג\"ק כ\"ק אדמו\"ר ח\"ג ע' רו."]]],[4801940149,"הקדום לד' היסודות (והתהום נקרא פשוט), ובמעין הגלוי מתגשמים הטפות רק שיש גם בו כח האין ובלתי מוגבל שהטיפין לאין מספר ונובע טיפין טיפין לאין שיעור מכח הבלתי מוגבל דתהום ומתפשטים הטיפות ונעשים לנהר גדול ויש לו מדה באורך ורוחב. וגם בו יש כח האין ובלתי מוגבל דתהום, שהמים שבו מתחדשים בכל רגע ונובעת מים חיים חדשים הבאים מן האין ממש ונובעים במרוצה לכלול בתהום להיות אין ואפס כבתחלה, והוא להיות שמתאחד בנהר כח הבלתי מוגבל דתהום, נמצא יש כאן ד' מדרגות המתאחדים בכח האין ובלתי מוגבל, משא\"כ מי הים הם מוגבלים, ואין בהם תוס' וגרעון מן המים הנתונים בו משי\"ב כמו מים מקובצים ונתונים במקוה בלתי מעיינות (וכמ\"ש ולמקוה המים קרא ימים<sup data-n=\"765\">8</sup> ), ומ\"ש כל הנחלים הולכים אל הים<sup data-n=\"766\">9</sup> משמע שיש בהם תוס' הנה ע\"ז כתיב בתרי' למקום שהם הולכים כו', שתיכף בבואם סמוך לים הם חוזרים לתהום ונכללים באחדות אין אלקי שבתהום. ולזה כיוונו רז\"ל באמרם מי הים מהקיפי מיברך<sup data-n=\"767\">10</sup> או ממקורו מיבריך, ופי' מיבריך שיהא מימיו שלמים וקימים, אבל אין בהם תוס'.\n<b>עד\"ז</b> ההפרש בין מח' לדבור שבדבור האותיות נמדדים במח' השייך לדבור כמה לדבר וכמה לחשות, הגם שבכל רגע מתחדש אותיות חדשים מהמח' בשעה שמדבר, אבל עכ\"פ הוא מוגבל ומדוד, ומגלה רק הארה מוגבלת מן השכל, ומה שלפעמים הדבור נק' בשם ארץ<sup data-n=\"768\">11</sup> הם ב' בחי' בדבור א' אותיו' הבאים מעצמות הנפש, וכשבאים בה' מוצאות הם מוגבלים ונק' ים שמכסים ומעלימים על המוחין, הגם שדבור מגלה רצון ושכל ומדות אך כבר באו לכלל צמצום ומדה, והקול וההבל שבא מהגרון אשר בזה הדבור במורגש לזולתו נק' ארץ ויבשה המגשם את האותיות בקול מורגש. והנה גם באותיו' הנק' בשם ים יש ב' בחי' א' אותיות הבאים ומתלבשים בקול הדבור, ב' פנימיות הדבור מח' שבדבור והוא מה שמחשב איך לדבר, וג\"ז נק' ים מוגבל שרק הארה מהמוחין מתלבש בדבור ולכן יש עת לחשות<sup data-n=\"769\">12</sup>, אבל המח' הוא כלי פנימיות לחכ' ומשוטטות כנהר הנובע במרוצה ומתחדש שפע חדשה מאין השכל ופנימיות החכ', ויש כאן ד' מדרי' נהר, השכל מקבל מכח המשכיל מקור מוצא כל מיני השכלות מהאין, ובשכל ישנו ב' בחי', א' כמו שהשכל עדיין מובדל מאותיו' גם מאותיות המחשבה (רק שבא במוח הרוחני), והמופת לזה הוא ממה שמצינו בגמ' שתק רב<sup data-n=\"770\">13</sup>, ובאמת הי' טעם לדבריו כמו שהמציא רבה<sup data-n=\"771\">14</sup>, רק לא היה מלובש עדין באותיות, ובחי' הב' בשכל כשבא באותיות קצרים ונעלמים (במוח הגשמי), אח\"כ בא להתחברות<sup data-n=\"772\">15</sup> הנהר דמח', והוא ע\"י בינה המארכת ומרחבת",[["765","8","<b>ולמקוה המים קרא ימים</b>: בראשית א, י."],["766","9","<b>כל הנחלים הולכים אל הים</b>: קהלת א, ז."],["767","10","<b>מי הים מהקיפי מיברך</b>: ראה שבת סה, ב נהרא מכיפי' מיברך. לקו\"ת שה\"ש לט, א. אמ\"ב שער התפילין קכא, סע\"ג. פלח הרמון בשלח ע' קסג."],["768","11","<b>הדבור נק' בשם ארץ</b>: ראה גם לקמן מאמר ד\"ה שבת שבתון ובהערה 40."],["769","12","<b>עת לחשות</b>: קהלת ג, ז."],["770","13","<b>שתק רב</b>: ביצה ו, א. ראה גם מאמרי אדה\"א קונטרסים ע' קיג. לקמן מאמר ד\"ה להבין ההפרש בין קי\"ס על יד הערה 39."],["771","14","<b>כמו שהמציא רבה</b>: ביצה שם."],["772","15","<b>להתחברות</b>: אוצ\"ל: להתרחבות."]]]]});
